CREATE OR REPLACE FUNCTION "public"."accept_org_invite"("invite_token" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_invite record;
  BEGIN
    SELECT * INTO v_invite
      FROM public.org_invites
        WHERE token = invite_token
          AND expires_at > now();

            IF NOT FOUND THEN
                RAISE EXCEPTION 'Invalid or expired invite';
                  END IF;

                    INSERT INTO public.org_members (org_id, user_id, role_id)
                      VALUES (v_invite.org_id, auth.uid(), v_invite.role_id)
                        ON CONFLICT DO NOTHING;

                          UPDATE public.profiles
                            SET org_id = v_invite.org_id
                              WHERE id = auth.uid();

                                DELETE FROM public.org_invites WHERE id = v_invite.id;
                                END;
                                $$;


ALTER FUNCTION "public"."accept_org_invite"("invite_token" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_agent_instant"("p_user_id" "uuid", "p_agent_id" "uuid", "p_pin" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_wallet_balance DECIMAL(15, 2);
    v_agent_status TEXT;
    v_activation_amount DECIMAL(15, 2) := 100000;
BEGIN
    IF NOT verify_pin(p_user_id, p_pin) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid PIN');
    END IF;

    SELECT status INTO v_agent_status FROM agents WHERE id = p_agent_id AND user_id = p_user_id;
    IF v_agent_status IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Agent not found');
    END IF;
    IF v_agent_status != 'approved' THEN
        RETURN jsonb_build_object('success', false, 'error', 'Agent not approved yet');
    END IF;

    SELECT wallet_balance INTO v_wallet_balance FROM profiles WHERE id = p_user_id;
    IF v_wallet_balance < v_activation_amount THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient balance', 
            'required', v_activation_amount, 'current', v_wallet_balance);
    END IF;

    UPDATE profiles SET wallet_balance = wallet_balance - v_activation_amount WHERE id = p_user_id;

    UPDATE agents SET 
        float_balance = v_activation_amount,
        status = 'active',
        activated_at = now(),
        updated_at = now()
    WHERE id = p_agent_id;

    INSERT INTO agent_float_history (agent_id, change_type, amount, balance_after, description)
    VALUES (p_agent_id, 'activation', v_activation_amount, v_activation_amount, 'Initial activation float');

    INSERT INTO transactions (user_id, type, amount, status, description, metadata)
    VALUES (p_user_id, 'agent_activation', v_activation_amount, 'completed', 
        'Agent activation float deposit', jsonb_build_object('agent_id', p_agent_id));

    RETURN jsonb_build_object('success', true, 'message', 'Agent activated successfully',
        'float_balance', v_activation_amount);
END;
$$;


ALTER FUNCTION "public"."activate_agent_instant"("p_user_id" "uuid", "p_agent_id" "uuid", "p_pin" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."activate_country_civic"("country_id" "uuid", "activated_by" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  dept RECORD;
BEGIN
  -- Activate country
  UPDATE public.civic_countries 
  SET is_active = true 
  WHERE id = country_id;
  
  -- Activate all core departments
  FOR dept IN SELECT * FROM public.civic_departments WHERE is_core = true
  LOOP
    INSERT INTO public.country_department_status (country_id, department_id, is_active, activated_by, activated_at)
    VALUES (country_id, dept.id, true, activated_by, now())
    ON CONFLICT (country_id, department_id) 
    DO UPDATE SET is_active = true, activated_by = EXCLUDED.activated_by, activated_at = now();
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."activate_country_civic"("country_id" "uuid", "activated_by" "uuid") OWNER TO "postgres";


