CREATE OR REPLACE FUNCTION "public"."add_business_director"("p_contractor_id" "uuid", "p_full_name" "text", "p_id_number" "text", "p_nationality" "text" DEFAULT 'Kenyan'::"text", "p_date_of_birth" "date" DEFAULT NULL::"date", "p_phone" "text" DEFAULT NULL::"text", "p_email" "text" DEFAULT NULL::"text", "p_share_percentage" numeric DEFAULT 0, "p_is_ceo" boolean DEFAULT false, "p_is_cfo" boolean DEFAULT false) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_director_id uuid;
    v_user_id uuid;
BEGIN
    SELECT created_by INTO v_user_id FROM civic_contractors WHERE id = p_contractor_id;

    INSERT INTO civic_contractor_directors (
        contractor_id, full_name, id_number, nationality, date_of_birth,
        phone, email, share_percentage, is_ceo, is_cfo
    ) VALUES (
        p_contractor_id, p_full_name, p_id_number, p_nationality, p_date_of_birth,
        p_phone, p_email, p_share_percentage, p_is_ceo, p_is_cfo
    ) RETURNING id INTO v_director_id;

    UPDATE civic_contractors 
    SET director_count = (SELECT COUNT(*) FROM civic_contractor_directors WHERE contractor_id = p_contractor_id),
        updated_at = now()
    WHERE id = p_contractor_id;

    INSERT INTO identity_verification_logs (user_id, event_type, event_data)
    VALUES (v_user_id, 'document_uploaded', jsonb_build_object('director_id', v_director_id, 'contractor_id', p_contractor_id));

    RETURN v_director_id;
END;
$$;


ALTER FUNCTION "public"."add_business_director"("p_contractor_id" "uuid", "p_full_name" "text", "p_id_number" "text", "p_nationality" "text", "p_date_of_birth" "date", "p_phone" "text", "p_email" "text", "p_share_percentage" numeric, "p_is_ceo" boolean, "p_is_cfo" boolean) OWNER TO "postgres";


