CREATE OR REPLACE FUNCTION "public"."add_transaction"("user_id" "uuid", "amt" numeric, "txn_type" "text", "ref_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                     DECLARE
                                                                                                                                                                     BEGIN
                                                                                                                                                                         INSERT INTO transactions (user_id, amount, type, reference_id, created_at)
                                                                                                                                                                             VALUES (user_id, amt, txn_type, ref_id, now());

                                                                                                                                                                                 -- Auto credit wallet for positive amounts
                                                                                                                                                                                     IF amt > 0 THEN
                                                                                                                                                                                             PERFORM credit_wallet(user_id, amt);
                                                                                                                                                                                                 END IF;
                                                                                                                                                                                                 END;
                                                                                                                                                                                                 $$;


ALTER FUNCTION "public"."add_transaction"("user_id" "uuid", "amt" numeric, "txn_type" "text", "ref_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."add_user_to_account"("p_account_id" "uuid", "p_user_id" "uuid", "p_role_id" smallint) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        DECLARE
          v_org uuid;
          BEGIN
            SELECT org_id INTO v_org
              FROM public.accounts
                WHERE id = p_account_id;

                  -- only org owner/admin allowed
                    IF NOT EXISTS (
                        SELECT 1 FROM public.org_members
                            WHERE org_id = v_org
                                AND user_id = auth.uid()
                                    AND role_id IN (1,2)
                                      ) THEN
                                          RAISE EXCEPTION 'Insufficient permissions';
                                            END IF;

                                              INSERT INTO public.account_members (account_id, user_id, role_id)
                                                VALUES (p_account_id, p_user_id, p_role_id)
                                                  ON CONFLICT DO NOTHING;

                                                    PERFORM public.log_audit(
                                                        v_org,
                                                            'account_user_added',
                                                                jsonb_build_object(
                                                                      'account_id', p_account_id,
                                                                            'user_id', p_user_id,
                                                                                  'role', p_role_id
                                                                                      )
                                                                                        );
                                                                                        END;
                                                                                        $$;


ALTER FUNCTION "public"."add_user_to_account"("p_account_id" "uuid", "p_user_id" "uuid", "p_role_id" smallint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_cash_in"("agent" "uuid", "customer" "uuid", "amt" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
        declare
          commission numeric;
          begin
            select percentage into commission
              from public.agent_commissions
                where tx_type = 'cash_in' and active = true
                  limit 1;

                    -- credit customer wallet
                      update public.wallets
                        set balance = balance + amt
                          where user_id = customer;

                            -- agent earns commission
                              update public.wallets
                                set balance = balance + (amt * commission / 100)
                                  where user_id = agent;

                                    -- ledger
                                      insert into public.transactions (
                                          from_user,
                                              to_user,
                                                  amount,
                                                      tx_type,
                                                          reference
                                                            )
                                                              values (
                                                                  agent,
                                                                      customer,
                                                                          amt,
                                                                              'cash_in',
                                                                                  'Agent deposit'
                                                                                    );
                                                                                    end;
                                                                                    $$;


ALTER FUNCTION "public"."agent_cash_in"("agent" "uuid", "customer" "uuid", "amt" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_cash_out"("agent" "uuid", "customer" "uuid", "amt" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
        declare
          commission numeric;
          begin
            -- check agent float
              update public.agent_float
                set balance = balance - amt
                  where agent_id = agent
                      and balance >= amt;

                        if not found then
                            raise exception 'Agent has insufficient float';
                              end if;

                                -- deduct customer wallet
                                  update public.wallets
                                    set balance = balance - amt
                                      where user_id = customer
                                          and balance >= amt;

                                            if not found then
                                                raise exception 'Customer has insufficient balance';
                                                  end if;

                                                    select percentage into commission
                                                      from public.agent_commissions
                                                        where tx_type = 'cash_out' and active = true
                                                          limit 1;

                                                            -- pay agent commission
                                                              update public.wallets
                                                                set balance = balance + (amt * commission / 100)
                                                                  where user_id = agent;

                                                                    insert into public.transactions (
                                                                        from_user,
                                                                            to_user,
                                                                                amount,
                                                                                    tx_type,
                                                                                        reference
                                                                                          )
                                                                                            values (
                                                                                                customer,
                                                                                                    agent,
                                                                                                        amt,
                                                                                                            'cash_out',
                                                                                                                'Agent withdrawal'
                                                                                                                  );
                                                                                                                  end;
                                                                                                                  $$;


ALTER FUNCTION "public"."agent_cash_out"("agent" "uuid", "customer" "uuid", "amt" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_customer_deposit"("p_agent_id" "uuid", "p_customer_phone" "text", "p_amount" numeric, "p_pin" "text", "p_customer_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_agent_user_id UUID;
    v_agent_float DECIMAL(15, 2);
    v_customer_id UUID;
    v_commission DECIMAL(15, 2);
    v_reference TEXT;
BEGIN
    SELECT user_id, float_balance INTO v_agent_user_id, v_agent_float 
    FROM agents WHERE id = p_agent_id AND status = 'active';

    IF v_agent_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Agent not active');
    END IF;

    IF NOT verify_pin(v_agent_user_id, p_pin) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid PIN');
    END IF;

    IF v_agent_float < p_amount THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient float');
    END IF;

    SELECT id INTO v_customer_id FROM profiles WHERE phone = p_customer_phone;
    IF v_customer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
    END IF;

    v_commission := p_amount * 0.005;
    v_reference := 'AGD-' || substr(md5(random()::text), 1, 8);

    UPDATE agents SET 
        float_balance = float_balance - p_amount + v_commission,
        total_commission_earned = total_commission_earned + v_commission,
        today_deposited = today_deposited + p_amount,
        monthly_volume = monthly_volume + p_amount,
        updated_at = now()
    WHERE id = p_agent_id;

    UPDATE profiles SET wallet_balance = wallet_balance + p_amount WHERE id = v_customer_id;

    INSERT INTO agent_transactions (agent_id, customer_id, transaction_type, amount, commission, 
        customer_phone, customer_name, confirmation_message, reference_code)
    VALUES (p_agent_id, v_customer_id, 'customer_deposit', p_amount, v_commission,
        p_customer_phone, p_customer_name,
        format('Deposit of KES %s confirmed. Ref: %s. Commission: KES %s', p_amount, v_reference, v_commission),
        v_reference);

    INSERT INTO agent_float_history (agent_id, change_type, amount, balance_after, description)
    SELECT p_agent_id, 'customer_debit', -p_amount, float_balance, 
        format('Customer deposit to %s', p_customer_phone) FROM agents WHERE id = p_agent_id;

    INSERT INTO agent_float_history (agent_id, change_type, amount, balance_after, description)
    SELECT p_agent_id, 'commission', v_commission, float_balance,
        format('Commission on deposit %s', v_reference) FROM agents WHERE id = p_agent_id;

    RETURN jsonb_build_object('success', true, 'reference', v_reference, 
        'commission', v_commission, 'message', 'Deposit completed');
END;
$$;


ALTER FUNCTION "public"."agent_customer_deposit"("p_agent_id" "uuid", "p_customer_phone" "text", "p_amount" numeric, "p_pin" "text", "p_customer_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."agent_customer_withdrawal"("p_agent_id" "uuid", "p_customer_phone" "text", "p_amount" numeric, "p_pin" "text", "p_customer_name" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_agent_user_id UUID;
    v_agent_float DECIMAL(15, 2);
    v_customer_id UUID;
    v_customer_balance DECIMAL(15, 2);
    v_commission DECIMAL(15, 2);
    v_reference TEXT;
BEGIN
    SELECT user_id, float_balance INTO v_agent_user_id, v_agent_float 
    FROM agents WHERE id = p_agent_id AND status = 'active';

    IF v_agent_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Agent not active');
    END IF;

    IF NOT verify_pin(v_agent_user_id, p_pin) THEN
        RETURN jsonb_build_object('success', false, 'error', 'Invalid PIN');
    END IF;

    SELECT id, wallet_balance INTO v_customer_id, v_customer_balance 
    FROM profiles WHERE phone = p_customer_phone;

    IF v_customer_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'Customer not found');
    END IF;

    IF v_customer_balance < p_amount THEN
        RETURN jsonb_build_object('success', false, 'error', 'Customer has insufficient balance');
    END IF;

    v_commission := p_amount * 0.005;
    v_reference := 'AGW-' || substr(md5(random()::text), 1, 8);

    UPDATE profiles SET wallet_balance = wallet_balance - p_amount WHERE id = v_customer_id;

    UPDATE agents SET 
        float_balance = float_balance + p_amount + v_commission,
        total_commission_earned = total_commission_earned + v_commission,
        today_withdrawn = today_withdrawn + p_amount,
        monthly_volume = monthly_volume + p_amount,
        updated_at = now()
    WHERE id = p_agent_id;

    INSERT INTO agent_transactions (agent_id, customer_id, transaction_type, amount, commission,
        customer_phone, customer_name, confirmation_message, reference_code)
    VALUES (p_agent_id, v_customer_id, 'customer_withdrawal', p_amount, v_commission,
        p_customer_phone, p_customer_name,
        format('Withdrawal of KES %s confirmed. Ref: %s. Commission earned: KES %s. Float balance: KES %s', 
            p_amount, v_reference, v_commission, 
            (SELECT float_balance FROM agents WHERE id = p_agent_id)),
        v_reference);

    INSERT INTO agent_float_history (agent_id, change_type, amount, balance_after, description)
    SELECT p_agent_id, 'customer_credit', p_amount, float_balance,
        format('Customer withdrawal from %s', p_customer_phone) FROM agents WHERE id = p_agent_id;

    INSERT INTO agent_float_history (agent_id, change_type, amount, balance_after, description)
    SELECT p_agent_id, 'commission', v_commission, float_balance,
        format('Commission on withdrawal %s', v_reference) FROM agents WHERE id = p_agent_id;

    RETURN jsonb_build_object('success', true, 'reference', v_reference,
        'commission', v_commission, 'message', 'Withdrawal completed');
END;
$$;


ALTER FUNCTION "public"."agent_customer_withdrawal"("p_agent_id" "uuid", "p_customer_phone" "text", "p_amount" numeric, "p_pin" "text", "p_customer_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."aggregate_profile_views_to_analytics"("p_date" "date" DEFAULT CURRENT_DATE) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    INSERT INTO public.profile_analytics (
        date, profile_id, profile_views, portfolio_views, 
        business_views, service_views, product_views,
        job_invitations, service_requests, product_sales,
        community_reach, revenue_generated, new_followers, new_connections,
        metadata
    )
    SELECT 
        p_date,
        pv.profile_id,
        COUNT(*) FILTER (WHERE pv.view_type = 'profile')::INTEGER,
        COUNT(*) FILTER (WHERE pv.view_type = 'portfolio')::INTEGER,
        COUNT(*) FILTER (WHERE pv.view_type = 'business')::INTEGER,
        0, 0, 0, 0, 0, 0, 0, 0, 0,
        jsonb_build_object('sources', jsonb_agg(DISTINCT pv.source))
    FROM public.profile_views pv
    WHERE DATE(pv.created_at) = p_date
    GROUP BY pv.profile_id
    ON CONFLICT (profile_id, date) 
    DO UPDATE SET
        profile_views = public.profile_analytics.profile_views + EXCLUDED.profile_views,
        portfolio_views = public.profile_analytics.portfolio_views + EXCLUDED.portfolio_views,
        business_views = public.profile_analytics.business_views + EXCLUDED.business_views,
        metadata = public.profile_analytics.metadata || EXCLUDED.metadata,
        updated_at = now();
END;
$$;


ALTER FUNCTION "public"."aggregate_profile_views_to_analytics"("p_date" "date") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_match_jobs"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  j RECORD;
  c RECORD;
  score NUMERIC;
BEGIN
  FOR j IN SELECT * FROM jobs WHERE status = 'open' LOOP

    FOR c IN SELECT * FROM job_candidates WHERE job_id = j.id LOOP

      SELECT ai_score_match(
        1,
        4.5,
        true,
        2
      )
      INTO score;

      UPDATE job_candidates
      SET match_score = score
      WHERE id = c.id;

    END LOOP;

  END LOOP;
END;
$$;


ALTER FUNCTION "public"."ai_match_jobs"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."ai_score_match"("skill_overlap" integer, "rating" numeric, "availability" boolean, "distance_km" numeric) RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  RETURN (
    (skill_overlap * 40) +
    (rating * 20) +
    (CASE WHEN availability THEN 20 ELSE 0 END) -
    (distance_km * 2)
  );
END;
$$;


ALTER FUNCTION "public"."ai_score_match"("skill_overlap" integer, "rating" numeric, "availability" boolean, "distance_km" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_content_revenue"("p_post_id" "uuid", "p_amount" numeric, "p_source" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        declare
          v_user uuid;
            v_creator numeric;
              v_platform numeric;
                v_tax numeric;
                begin
                  select user_id into v_user from posts where id = p_post_id;

                    if not exists (
                        select 1 from post_stats
                            where post_id = p_post_id
                                  and monetized = true
                                    ) then
                                        return;
                                          end if;

                                            v_creator := p_amount * 0.65;
                                              v_platform := p_amount * 0.25;
                                                v_tax := p_amount * 0.10;

                                                  insert into content_earnings (
                                                      user_id, post_id, source,
                                                          gross_amount, creator_amount,
                                                              platform_amount, tax_reserved
                                                                ) values (
                                                                    v_user, p_post_id, p_source,
                                                                        p_amount, v_creator,
                                                                            v_platform, v_tax
                                                                              );

                                                                                update post_stats
                                                                                  set earnings = earnings + v_creator
                                                                                    where post_id = p_post_id;
                                                                                    end;
                                                                                    $$;


ALTER FUNCTION "public"."allocate_content_revenue"("p_post_id" "uuid", "p_amount" numeric, "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."allocate_music_revenue"("p_track" "uuid", "p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      declare
        v_main uuid;
          v_creator numeric;
            v_platform numeric;
              v_tax numeric;
                v_collab numeric;
                begin
                  if not exists (
                      select 1 from music_stats
                          where track_id = p_track and monetized = true
                            ) then
                                return;
                                  end if;

                                    select user_id into v_main from music_tracks where id = p_track;

                                      v_creator := p_amount * 0.55;
                                        v_collab := p_amount * 0.10;
                                          v_platform := p_amount * 0.25;
                                            v_tax := p_amount * 0.10;

                                              -- main artist
                                                insert into content_earnings (
                                                    user_id, source, gross_amount,
                                                        creator_amount, platform_amount, tax_reserved
                                                          ) values (
                                                              v_main, 'music', p_amount,
                                                                  v_creator, v_platform, v_tax
                                                                    );

                                                                      -- collaborators
                                                                        insert into content_earnings (
                                                                            user_id, source, gross_amount,
                                                                                creator_amount, platform_amount, tax_reserved
                                                                                  )
                                                                                    select
                                                                                        user_id, 'music', p_amount,
                                                                                            (v_collab * split_percent / 100), 0, 0
                                                                                              from track_collaborators
                                                                                                where track_id = p_track;

                                                                                                  update music_stats
                                                                                                    set earnings = earnings + (v_creator + v_collab)
                                                                                                      where track_id = p_track;
                                                                                                      end;
                                                                                                      $$;


ALTER FUNCTION "public"."allocate_music_revenue"("p_track" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."apply_moderation"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                  DECLARE
                                                                                                                                                                      rule RECORD;
                                                                                                                                                                      BEGIN
                                                                                                                                                                          FOR rule IN SELECT * FROM moderation_rules LOOP
                                                                                                                                                                                  IF NEW.content ILIKE '%' || rule.pattern || '%' THEN
                                                                                                                                                                                              INSERT INTO moderation_flags(post_id, comment_id, flagged_by, reason)
                                                                                                                                                                                                          VALUES (COALESCE(NEW.post_id, NULL), COALESCE(NEW.id, NULL), NEW.user_id, 'Auto: ' || rule.pattern);
                                                                                                                                                                                                                  END IF;
                                                                                                                                                                                                                      END LOOP;
                                                                                                                                                                                                                          RETURN NEW;
                                                                                                                                                                                                                          END;
                                                                                                                                                                                                                          $$;


ALTER FUNCTION "public"."apply_moderation"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."archive_old_events"("p_days" integer DEFAULT 30) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  GET DIAGNOSTICS v_count = ROW_COUNT;
  DELETE FROM public.event_logs WHERE created_at < now() - interval '1 day' * p_days;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."archive_old_events"("p_days" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."assign_nearest_driver"("p_ride_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   DECLARE
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       v_driver_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           v_org_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               v_lat double precision;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   v_lng double precision;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   BEGIN
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       SELECT org_id, pickup_lat, pickup_lng
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           INTO v_org_id, v_lat, v_lng
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               FROM public.rides
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   WHERE id = p_ride_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       SELECT driver_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           INTO v_driver_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               FROM public.find_nearest_drivers(v_org_id, v_lat, v_lng, 1)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   LIMIT 1;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       UPDATE public.rides
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           SET driver_id = v_driver_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               WHERE id = p_ride_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                   UPDATE public.drivers
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       SET is_available = false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           WHERE id = v_driver_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               RETURN v_driver_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $$;


ALTER FUNCTION "public"."assign_nearest_driver"("p_ride_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."atomic_wallet_credit"("p_wallet_id" "uuid", "p_amount" numeric, "p_reference_id" "uuid", "p_description" "text" DEFAULT 'mpesa credit'::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_balance numeric;
begin

  -- idempotency guard
  if exists (
    select 1 from wallet_transactions
    where reference_id = p_reference_id
  ) then
    return;
  end if;

  -- get current balance
  select balance into v_balance
  from wallets
  where id = p_wallet_id;

  v_balance := coalesce(v_balance, 0) + p_amount;

  -- ledger entry (source of truth)
  insert into wallet_transactions (
    wallet_id,
    type,
    amount,
    balance_after,
    description,
    reference_id,
    created_at
  ) values (
    p_wallet_id,
    'CREDIT',
    p_amount,
    v_balance,
    p_description,
    p_reference_id,
    now()
  );

  -- snapshot update (cache only)
  update wallets
  set balance = v_balance,
      available_balance = v_balance,
      updated_at = now()
  where id = p_wallet_id;

end;
$$;


ALTER FUNCTION "public"."atomic_wallet_credit"("p_wallet_id" "uuid", "p_amount" numeric, "p_reference_id" "uuid", "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."atomic_wallet_debit"("p_user_id" "text", "p_amount" numeric, "p_reference" "text", "p_source" "text" DEFAULT 'transfer'::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
begin

  if exists (
    select 1 from wallet_ledger
    where reference = p_reference
  ) then
    return;
  end if;

  insert into wallet_ledger (
    user_id,
    type,
    amount,
    reference,
    source,
    metadata
  ) values (
    p_user_id,
    'DEBIT',
    p_amount,
    p_reference,
    p_source,
    jsonb_build_object('system', 'mtaa-ledger')
  );

end;
$$;


ALTER FUNCTION "public"."atomic_wallet_debit"("p_user_id" "text", "p_amount" numeric, "p_reference" "text", "p_source" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."atomic_wallet_debit"("p_wallet_id" "uuid", "p_amount" numeric, "p_reference_id" "uuid", "p_description" "text" DEFAULT 'debit'::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_balance numeric;
begin

  if exists (
    select 1 from wallet_transactions
    where reference_id = p_reference_id
  ) then
    return;
  end if;

  select balance into v_balance
  from wallets
  where id = p_wallet_id;

  if coalesce(v_balance,0) < p_amount then
    raise exception 'INSUFFICIENT_FUNDS';
  end if;

  v_balance := v_balance - p_amount;

  insert into wallet_transactions (
    wallet_id,
    type,
    amount,
    balance_after,
    description,
    reference_id,
    created_at
  ) values (
    p_wallet_id,
    'DEBIT',
    p_amount,
    v_balance,
    p_description,
    p_reference_id,
    now()
  );

  update wallets
  set balance = v_balance,
      available_balance = v_balance,
      updated_at = now()
  where id = p_wallet_id;

end;
$$;


ALTER FUNCTION "public"."atomic_wallet_debit"("p_wallet_id" "uuid", "p_amount" numeric, "p_reference_id" "uuid", "p_description" "text") OWNER TO "postgres";


