CREATE OR REPLACE FUNCTION "public"."auto_apply_bursary"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_account_id uuid;
BEGIN
  IF NEW.status='approved' AND OLD.status!='approved' THEN
    SELECT id INTO v_account_id FROM student_finance_accounts WHERE student_id=NEW.student_id;
    IF v_account_id IS NOT NULL THEN
      INSERT INTO fee_transactions (account_id, student_id, institution_id, transaction_type, amount, payment_method, description, status)
      VALUES (v_account_id, NEW.student_id, NEW.institution_id, 'bursary', NEW.amount_approved, 'bursary', 'Bursary: '||NEW.bursary_type, 'completed');
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_apply_bursary"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_create_student_finance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  INSERT INTO student_finance_accounts (student_id, institution_id)
  VALUES (NEW.id, NEW.institution_id)
  ON CONFLICT (student_id) DO NOTHING;
  RETURN NEW;
END;
$$;


