CREATE OR REPLACE FUNCTION "public"."auto_emergency_contact"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_name text; v_phone text; v_email text;
BEGIN
  SELECT raw_user_meta->>'full_name', email INTO v_name, v_email
  FROM auth.users WHERE id = NEW.parent_guardian_id;
  IF v_name IS NOT NULL THEN
    INSERT INTO child_emergency_contacts (student_id, institution_id, contact_name, relationship, phone, email, is_primary, priority, can_pickup, can_receive_alerts)
    VALUES (NEW.id, NEW.institution_id, v_name, 'Parent/Guardian', COALESCE(NEW.parent_guardian_phone,''), COALESCE(v_email,''), true, 1, true, true)
    ON CONFLICT DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_emergency_contact"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_escalate_sos"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'active' AND NEW.created_at < now() - INTERVAL '30 minutes' THEN
    NEW.status := 'escalated';
    PERFORM pg_notify('sos_escalated', json_build_object('sos_id',NEW.id,'student_id',NEW.student_id)::text);
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."auto_escalate_sos"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."auto_install_core_apps"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                        DECLARE
                                                                                                                                                                                                                                                                                                                          core_app RECORD;
                                                                                                                                                                                                                                                                                                                            position_counter INTEGER := 0;
                                                                                                                                                                                                                                                                                                                            BEGIN
                                                                                                                                                                                                                                                                                                                              -- Auto-install all core and system apps for new users
                                                                                                                                                                                                                                                                                                                                FOR core_app IN 
                                                                                                                                                                                                                                                                                                                                    SELECT id, grid_size FROM public.app_store_apps 
                                                                                                                                                                                                                                                                                                                                        WHERE app_type IN ('core', 'system') AND enabled = true
                                                                                                                                                                                                                                                                                                                                            ORDER BY created_at ASC
                                                                                                                                                                                                                                                                                                                                              LOOP
                                                                                                                                                                                                                                                                                                                                                  INSERT INTO public.app_installations (
                                                                                                                                                                                                                                                                                                                                                        user_id, 
                                                                                                                                                                                                                                                                                                                                                              app_id, 
                                                                                                                                                                                                                                                                                                                                                                    is_enabled, 
                                                                                                                                                                                                                                                                                                                                                                          pinned, 
                                                                                                                                                                                                                                                                                                                                                                                launcher_position,
                                                                                                                                                                                                                                                                                                                                                                                      grid_x,
                                                                                                                                                                                                                                                                                                                                                                                            grid_y,
                                                                                                                                                                                                                                                                                                                                                                                                  screen
                                                                                                                                                                                                                                                                                                                                                                                                      ) VALUES (
                                                                                                                                                                                                                                                                                                                                                                                                            NEW.id,
                                                                                                                                                                                                                                                                                                                                                                                                                  core_app.id,
                                                                                                                                                                                                                                                                                                                                                                                                                        true,
                                                                                                                                                                                                                                                                                                                                                                                                                              true,
                                                                                                                                                                                                                                                                                                                                                                                                                                    position_counter,
                                                                                                                                                                                                                                                                                                                                                                                                                                          position_counter % 4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                position_counter / 4,
                                                                                                                                                                                                                                                                                                                                                                                                                                                      0
                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) ON CONFLICT DO NOTHING;
                                                                                                                                                                                                                                                                                                                                                                                                                                                              position_counter := position_counter + 1;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                END LOOP;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    RETURN NEW;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $$;


