CREATE OR REPLACE FUNCTION "public"."auto_resolve_media_url"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    -- Resolve media_url from payload
    IF NEW.payload->>'media_url' IS NOT NULL AND NEW.payload->>'media_url' != '' THEN
        NEW.resolved_media_url := resolve_storage_url(NEW.payload->>'media_url');
    ELSE
        NEW.resolved_media_url := NULL;
    END IF;

    -- Resolve thumbnail_url from payload
    IF NEW.payload->>'thumbnail_url' IS NOT NULL AND NEW.payload->>'thumbnail_url' != '' THEN
        NEW.resolved_thumbnail_url := resolve_storage_url(NEW.payload->>'thumbnail_url');
    ELSE
        NEW.resolved_thumbnail_url := NULL;
    END IF;

    RETURN NEW;
END;
$$;


