CREATE OR REPLACE FUNCTION "public"."auto_savings_on_payment"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_auto_percent numeric(5,2); v_savings_amount numeric(12,2);
BEGIN
  IF NEW.transaction_type='payment' AND NEW.status='completed' THEN
    SELECT auto_save_percent INTO v_auto_percent FROM student_finance_accounts WHERE id=NEW.account_id;
    IF v_auto_percent > 0 THEN
      v_savings_amount := ROUND(NEW.amount * v_auto_percent / 100, 2);
      IF v_savings_amount > 0 THEN
        INSERT INTO fee_transactions (account_id, student_id, institution_id, transaction_type, amount, description, status)
        VALUES (NEW.account_id, NEW.student_id, NEW.institution_id, 'savings_deposit', v_savings_amount, 'Auto-savings '||v_auto_percent||'%', 'completed');
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


