CREATE OR REPLACE FUNCTION "public"."buy_mtaa_shares"("p_shares" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
                        declare
                          price numeric;
                            cost numeric;
                            begin
                              select share_price_usd into price from public.company_config where id = 1;
                                cost := p_shares * price;

                                  -- deduct wallet
                                    update public.wallets
                                      set balance = balance - cost
                                        where user_id = auth.uid()
                                            and balance >= cost;

                                              if not found then
                                                  raise exception 'Insufficient wallet balance';
                                                    end if;

                                                      -- add shares
                                                        insert into public.user_shares (user_id, shares_owned)
                                                          values (auth.uid(), p_shares)
                                                            on conflict (user_id)
                                                              do update set
                                                                  shares_owned = user_shares.shares_owned + p_shares,
                                                                      updated_at = now();

                                                                        -- update treasury
                                                                          update public.mtaa_treasury
                                                                            set total_raised = total_raised + cost;

                                                                            end;
                                                                            $$;


ALTER FUNCTION "public"."buy_mtaa_shares"("p_shares" bigint) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."buy_shares"("buyer" "uuid", "share_count" bigint) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
      declare
        cfg record;
          total_cost numeric;
          begin
            select * into cfg
              from public.platform_shares
                where id = 1;

                  if cfg.issued_shares + share_count > cfg.total_shares then
                      raise exception 'Not enough shares available';
                        end if;

                          total_cost := share_count * cfg.price_per_share;

                            update public.wallets
                              set balance = balance - total_cost
                                where user_id = buyer
                                    and balance >= total_cost;

                                      if not found then
                                          raise exception 'Insufficient balance';
                                            end if;

                                              insert into public.user_shares (user_id, shares)
                                                values (buyer, share_count)
                                                  on conflict (user_id)
                                                    do update
                                                        set shares = user_shares.shares + excluded.shares,
                                                                updated_at = now();

                                                                  update public.platform_shares
                                                                    set issued_shares = issued_shares + share_count,
                                                                          updated_at = now();

                                                                            insert into public.share_transactions (
                                                                                user_id,
                                                                                    shares,
                                                                                        price_per_share,
                                                                                            total_amount,
                                                                                                type
                                                                                                  ) values (
                                                                                                      buyer,
                                                                                                          share_count,
                                                                                                              cfg.price_per_share,
                                                                                                                  total_cost,
                                                                                                                      'buy'
                                                                                                                        );

                                                                                                                          insert into public.transactions (
                                                                                                                              from_user,
                                                                                                                                  to_user,
                                                                                                                                      amount,
                                                                                                                                          type,
                                                                                                                                              reference
                                                                                                                                                ) values (
                                                                                                                                                    buyer,
                                                                                                                                                        null,
                                                                                                                                                            total_cost,
                                                                                                                                                                'share_purchase',
                                                                                                                                                                    share_count::text
                                                                                                                                                                      );
                                                                                                                                                                      end;
                                                                                                                                                                      $$;


ALTER FUNCTION "public"."buy_shares"("buyer" "uuid", "share_count" bigint) OWNER TO "postgres";


