CREATE OR REPLACE FUNCTION "public"."calculate_company_score"("p_contractor_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_score integer := 0;
    v_tax_score integer := 0;
    v_director_score integer := 0;
    v_project_score integer := 0;
BEGIN
    SELECT CASE WHEN tax_compliant THEN 25 ELSE 0 END INTO v_tax_score
    FROM civic_contractors WHERE id = p_contractor_id;

    SELECT LEAST(director_count * 5, 15) INTO v_director_score
    FROM civic_contractors WHERE id = p_contractor_id;

    SELECT LEAST((projects_completed * 10) - (projects_stalled * 5) - (projects_incomplete * 10), 30)
    INTO v_project_score
    FROM civic_contractors WHERE id = p_contractor_id;

    v_score := 30 + v_tax_score + v_director_score + v_project_score;
    v_score := GREATEST(0, LEAST(100, v_score));

    UPDATE civic_contractors 
    SET company_score = v_score,
        score_breakdown = jsonb_build_object(
            'base', 30,
            'tax_compliance', v_tax_score,
            'directors', v_director_score,
            'projects', v_project_score
        ),
        updated_at = now()
    WHERE id = p_contractor_id;

    RETURN v_score;
END;
$$;


ALTER FUNCTION "public"."calculate_company_score"("p_contractor_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_distance_km"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) RETURNS numeric
    LANGUAGE "plpgsql" IMMUTABLE
    AS $$
DECLARE
  r numeric := 6371;
  dlat numeric := radians(lat2 - lat1);
  dlng numeric := radians(lng2 - lng1);
  a numeric;
  c numeric;
BEGIN
  a := sin(dlat/2)^2 + cos(radians(lat1)) * cos(radians(lat2)) * sin(dlng/2)^2;
  c := 2 * atan2(sqrt(a), sqrt(1-a));
  RETURN round(r * c, 2);
END;
$$;


ALTER FUNCTION "public"."calculate_distance_km"("lat1" double precision, "lng1" double precision, "lat2" double precision, "lng2" double precision) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_distance_km"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) RETURNS numeric
    LANGUAGE "sql" IMMUTABLE
    AS $$
    select
      6371 * acos(
          cos(radians(lat1)) *
              cos(radians(lat2)) *
                  cos(radians(lng2) - radians(lng1)) +
                      sin(radians(lat1)) *
                          sin(radians(lat2))
                            );
                            $$;


ALTER FUNCTION "public"."calculate_distance_km"("lat1" numeric, "lng1" numeric, "lat2" numeric, "lng2" numeric) OWNER TO "postgres";


