CREATE OR REPLACE FUNCTION "public"."calculate_fee"("p_provider" "text", "p_currency" "text", "p_amount" numeric, "p_fee_type" "text" DEFAULT 'percentage'::"text") RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_fee_record record;
  v_fee numeric;
BEGIN
  SELECT * INTO v_fee_record 
  FROM public.payment_fees 
  WHERE provider = p_provider 
  AND currency = p_currency 
  AND fee_type = p_fee_type
  AND is_active = true
  ORDER BY created_at DESC
  LIMIT 1;
  
  IF NOT FOUND THEN
    RETURN 0;
  END IF;
  
  IF p_fee_type = 'percentage' THEN
    v_fee := (p_amount * v_fee_record.fee_value) / 100;
  ELSIF p_fee_type = 'flat' THEN
    v_fee := v_fee_record.fee_value;
  ELSE
    v_fee := 0;
  END IF;
  
  RETURN LEAST(GREATEST(v_fee, v_fee_record.min_fee), COALESCE(v_fee_record.max_fee, v_fee));
END;
$$;


ALTER FUNCTION "public"."calculate_fee"("p_provider" "text", "p_currency" "text", "p_amount" numeric, "p_fee_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_gofund_limit"("vol" numeric) RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  IF vol < 10000 THEN
    RETURN 0;
  ELSIF vol < 100000 THEN
    RETURN vol * 0.2;
  ELSIF vol < 1000000 THEN
    RETURN vol * 0.4;
  ELSE
    RETURN vol * 0.6;
  END IF;

END;
$$;


ALTER FUNCTION "public"."calculate_gofund_limit"("vol" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_hours_worked"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.clock_out_at IS NOT NULL AND OLD.clock_out_at IS NULL THEN
    NEW.hours_worked := EXTRACT(EPOCH FROM (NEW.clock_out_at - NEW.clock_in_at)) / 3600;
    IF NEW.hours_worked > 8 THEN
      NEW.overtime_hours := NEW.hours_worked - 8;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_hours_worked"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_net_payroll"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.net_amount := COALESCE(NEW.base_amount, 0) + COALESCE(NEW.overtime_amount, 0) + COALESCE(NEW.bonus_amount, 0) - COALESCE(NEW.deduction_amount, 0) - COALESCE(NEW.tax_amount, 0);
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_net_payroll"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_net_revenue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.platform_fee := (NEW.gross_amount * NEW.platform_fee_percent) / 100;
    NEW.net_amount := NEW.gross_amount - NEW.platform_fee;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_net_revenue"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."calculate_penalty"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    p_rate DECIMAL(5,2);
    days_overdue INTEGER;
    new_penalty DECIMAL(12,2);
BEGIN
    IF NEW.status = 'overdue' AND OLD.status != 'overdue' THEN
        SELECT c.penalty_rate INTO p_rate
        FROM public.counties c WHERE c.id = NEW.county_id;

        days_overdue := CURRENT_DATE - NEW.due_date;

        IF days_overdue > 0 THEN
            new_penalty := NEW.amount * (p_rate / 100) * (days_overdue::DECIMAL / 30);
            NEW.penalty_amount := GREATEST(new_penalty, 0);
        END IF;
    END IF;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."calculate_penalty"() OWNER TO "postgres";


