CREATE OR REPLACE FUNCTION "public"."calculate_trust_score"("p_user_id" "uuid") RETURNS integer
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_identity_score integer := 0;
    v_activity_score integer := 0;
    v_community_score integer := 0;
    v_transaction_score integer := 0;
    v_overall integer;
BEGIN
    -- Identity component (max 40)
    SELECT CASE 
        WHEN kyc_status = 'verified' AND kyc_level >= 3 THEN 40
        WHEN kyc_status = 'verified' AND kyc_level = 2 THEN 30
        WHEN kyc_status = 'verified' AND kyc_level = 1 THEN 20
        WHEN kyc_status = 'pending' THEN 10
        ELSE 0
    END INTO v_identity_score
    FROM profiles WHERE user_id = p_user_id;

    -- Activity component (max 25) — placeholder for future integration
    v_activity_score := 15;

    -- Community component (max 20) — placeholder for future integration
    v_community_score := 10;

    -- Transaction component (max 15) — placeholder for future integration
    v_transaction_score := 5;

    v_overall := LEAST(v_identity_score + v_activity_score + v_community_score + v_transaction_score, 100);

    -- Update trust_scores table
    INSERT INTO trust_scores (user_id, profile_id, overall_score, identity_score, activity_score, community_score, transaction_score)
    SELECT p_user_id, id, v_overall, v_identity_score, v_activity_score, v_community_score, v_transaction_score
    FROM profiles WHERE user_id = p_user_id
    ON CONFLICT (user_id) DO UPDATE SET
        overall_score = v_overall,
        identity_score = v_identity_score,
        activity_score = v_activity_score,
        community_score = v_community_score,
        transaction_score = v_transaction_score,
        updated_at = now();

    -- Update profile trust_score
    UPDATE profiles SET trust_score = v_overall WHERE user_id = p_user_id;

    RETURN v_overall;
END;
$$;


ALTER FUNCTION "public"."calculate_trust_score"("p_user_id" "uuid") OWNER TO "postgres";


