CREATE OR REPLACE FUNCTION "public"."can_view_profile_section"("p_viewer_id" "uuid", "p_profile_user_id" "uuid", "p_section" "text" DEFAULT 'profile'::"text") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_visibility TEXT;
    v_is_follower BOOLEAN := false;
    v_is_mutual BOOLEAN := false;
    v_is_blocked BOOLEAN := false;
BEGIN
    -- Owner always can view
    IF p_viewer_id = p_profile_user_id THEN
        RETURN true;
    END IF;

    -- Check if blocked
    SELECT EXISTS(
        SELECT 1 FROM public.profile_blocks 
        WHERE blocker_id = p_profile_user_id AND blocked_id = p_viewer_id
    ) INTO v_is_blocked;

    IF v_is_blocked THEN
        RETURN false;
    END IF;

    -- Get visibility from profile_settings (existing table)
    SELECT COALESCE(
        CASE p_section
            WHEN 'profile' THEN (SELECT is_profile_public::TEXT FROM public.profile_settings WHERE profile_id = (SELECT id FROM public.profiles WHERE user_id = p_profile_user_id))
            WHEN 'portfolio' THEN (SELECT is_portfolio_public::TEXT FROM public.profile_settings WHERE profile_id = (SELECT id FROM public.profiles WHERE user_id = p_profile_user_id))
            WHEN 'achievements' THEN (SELECT is_achievements_public::TEXT FROM public.profile_settings WHERE profile_id = (SELECT id FROM public.profiles WHERE user_id = p_profile_user_id))
            WHEN 'skills' THEN (SELECT is_skills_public::TEXT FROM public.profile_settings WHERE profile_id = (SELECT id FROM public.profiles WHERE user_id = p_profile_user_id))
            ELSE 'true'
        END,
        'true'
    ) INTO v_visibility;

    -- Convert boolean text to visibility level
    IF v_visibility = 'true' OR v_visibility = 'public' THEN
        RETURN true;
    END IF;

    -- Check follower status for restricted visibility
    SELECT EXISTS(
        SELECT 1 FROM public.profile_follows 
        WHERE follower_id = p_viewer_id AND following_id = p_profile_user_id
    ) INTO v_is_follower;

    IF v_visibility = 'followers' OR v_visibility = 'connections' THEN
        RETURN v_is_follower;
    END IF;

    -- Check mutual for friends
    IF v_visibility = 'friends' THEN
        SELECT EXISTS(
            SELECT 1 FROM public.profile_follows f1
            JOIN public.profile_follows f2 ON f1.follower_id = f2.following_id AND f1.following_id = f2.follower_id
            WHERE f1.follower_id = p_viewer_id AND f1.following_id = p_profile_user_id
        ) INTO v_is_mutual;
        RETURN v_is_mutual;
    END IF;

    RETURN false;
END;
$$;


ALTER FUNCTION "public"."can_view_profile_section"("p_viewer_id" "uuid", "p_profile_user_id" "uuid", "p_section" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_escrow"("_escrow_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
declare
  esc record;
begin

  select * into esc
  from public.escrow_accounts
  where id = _escrow_id
  for update;

  if esc.status != 'LOCKED' then
    return false;
  end if;

  update public.escrow_accounts
  set status = 'CANCELLED'
  where id = _escrow_id;

  perform public.wallet_credit(
    esc.payer_id,
    esc.amount,
    'ESCROW_REFUND'
  );

  return true;

end;
$$;


ALTER FUNCTION "public"."cancel_escrow"("_escrow_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cancel_escrow"("_escrow_id" "uuid", "_reference" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare v record;
begin
  select * into v
  from public.escrow_accounts
  where id = _escrow_id;

  update public.escrow_accounts
  set status = 'cancelled',
      updated_at = now()
  where id = _escrow_id;

  perform public.wallet_credit(v.payer_id, v.amount, _reference);
end;
$$;


ALTER FUNCTION "public"."cancel_escrow"("_escrow_id" "uuid", "_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cash_in"("p_user" "uuid", "p_agent" "uuid", "p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        begin
          update wallets
            set available_balance = available_balance + p_amount,
                  lifetime_earned = lifetime_earned + p_amount
                    where user_id = p_user;

                      insert into transactions (
                          from_user, to_user, agent_id, amount, transaction_type, status
                            ) values (
                                p_agent, p_user, p_agent, p_amount, 'cash_in', 'completed'
                                  );
                                  end;
                                  $$;


ALTER FUNCTION "public"."cash_in"("p_user" "uuid", "p_agent" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."cash_out"("p_user" "uuid", "p_agent" "uuid", "p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        begin
          update wallets
            set available_balance = available_balance - p_amount
              where user_id = p_user and available_balance >= p_amount;

                insert into transactions (
                    from_user, to_user, agent_id, amount, transaction_type, status
                      ) values (
                          p_user, p_agent, p_agent, p_amount, 'cash_out', 'completed'
                            );
                            end;
                            $$;


ALTER FUNCTION "public"."cash_out"("p_user" "uuid", "p_agent" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_contractor_blacklist"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.contractor_id IS NOT NULL THEN
    IF EXISTS (SELECT 1 FROM civic_contractors WHERE id = NEW.contractor_id AND blacklist_status = 'blacklisted') THEN
      RAISE EXCEPTION 'Cannot assign blacklisted contractor to project';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


