CREATE OR REPLACE FUNCTION "public"."check_gofund_available"("p_wallet_id" "uuid", "p_amount" numeric) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  balance numeric;
  credit numeric;
  debt numeric;
BEGIN

  SELECT available_balance INTO balance
  FROM wallets
  WHERE id = p_wallet_id;

  SELECT credit_limit, current_debt
  INTO credit, debt
  FROM gofund_accounts
  WHERE wallet_id = p_wallet_id;

  IF balance + credit - debt >= p_amount THEN
    RETURN true;
  END IF;

  RETURN false;

END;
$$;


ALTER FUNCTION "public"."check_gofund_available"("p_wallet_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_orphaned_records"("p_parent_table" "text", "p_child_table" "text", "p_fk_column" "text") RETURNS TABLE("orphaned_count" bigint, "sample_ids" "uuid"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY EXECUTE format(
    'SELECT COUNT(*) as cnt, ARRAY_AGG(id) FILTER (WHERE rn <= 5) as samples
     FROM (SELECT id, ROW_NUMBER() OVER (ORDER BY id) as rn FROM public.%I c
     WHERE NOT EXISTS (SELECT 1 FROM public.%I p WHERE p.id = c.%I)) subq',
    p_child_table, p_parent_table, p_fk_column
  );
END;
$$;


ALTER FUNCTION "public"."check_orphaned_records"("p_parent_table" "text", "p_child_table" "text", "p_fk_column" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."check_property_availability"("p_property_id" "uuid", "p_check_in" "date", "p_check_out" "date") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_conflicting_bookings INTEGER;
BEGIN
  SELECT COUNT(*) INTO v_conflicting_bookings
  FROM property_bookings
  WHERE property_id = p_property_id
    AND booking_status IN ('confirmed', 'checked_in')
    AND check_in_date < p_check_out
    AND check_out_date > p_check_in;

  RETURN v_conflicting_bookings = 0;
END;
$$;


