CREATE OR REPLACE FUNCTION "public"."complete_profile"("p_dob" "date", "p_gender" "text", "p_tribe_code" "text", "p_interests" "text"[]) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
          declare
            v_tribe_id uuid;
            begin
              -- resolve tribe UUID
                select id into v_tribe_id
                  from public.tribes
                    where code = p_tribe_code;

                      if v_tribe_id is null then
                          raise exception 'Invalid tribe code';
                            end if;

                              -- update profile
                                update public.profiles
                                  set
                                      dob = p_dob,
                                          gender = p_gender,
                                              tribe_id = v_tribe_id,
                                                  interests = p_interests,
                                                      status = 'active'
                                                        where id = auth.uid();

                                                          -- join tribe community
                                                            insert into public.tribe_members (user_id, tribe_id)
                                                              values (auth.uid(), v_tribe_id)
                                                                on conflict do nothing;
                                                                end;
                                                                $$;


