    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
          declare
            v_tribe_id uuid;
            begin
              -- resolve tribe by code
                select id into v_tribe_id
                  from public.tribes
                    where code = p_tribe_code;

                      if v_tribe_id is null then
                          raise exception 'Invalid tribe code';
                            end if;

                              -- update profile
