CREATE OR REPLACE FUNCTION "public"."complete_ride"("p_ride_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ride RECORD;
  v_final_fare NUMERIC;
BEGIN
  SELECT * INTO v_ride FROM public.rides WHERE id = p_ride_id;
  
  IF v_ride.driver_id IS NULL THEN 
    RAISE EXCEPTION 'No driver assigned to this ride'; 
  END IF;
  
  IF v_ride.driver_id != auth.uid() THEN 
    RAISE EXCEPTION 'Only assigned driver can complete ride'; 
  END IF;
  
  v_final_fare := COALESCE(v_ride.final_fare, v_ride.estimated_fare, 0);
  
  UPDATE public.rides 
  SET status = 'completed', 
      completed_at = now(), 
      final_fare = v_final_fare
  WHERE id = p_ride_id;
  
  UPDATE public.escrow_accounts 
  SET status = 'released', 
      worker_id = v_ride.driver_id, 
      released_at = now()
  WHERE job_id = p_ride_id AND status = 'held';
  
  INSERT INTO public.driver_stats (driver_id, total_trips, accepted_trips, acceptance_rate, updated_at)
  VALUES (v_ride.driver_id, 1, 1, 1, now())
  ON CONFLICT (driver_id) 
  DO UPDATE SET 
    total_trips = public.driver_stats.total_trips + 1,
    accepted_trips = public.driver_stats.accepted_trips + 1,
    acceptance_rate = CASE 
      WHEN (public.driver_stats.total_trips + 1) > 0 
      THEN round((public.driver_stats.accepted_trips + 1)::numeric / (public.driver_stats.total_trips + 1), 2)
      ELSE 1 
    END,
    updated_at = now();
    
  UPDATE public.mtaxi_drivers 
  SET is_available = true,
      updated_at = now()
  WHERE user_id = v_ride.driver_id;
END;
$$;


ALTER FUNCTION "public"."complete_ride"("p_ride_id" "uuid") OWNER TO "postgres";


