      j record;
      begin
        select *
          into j
            from public.truck_jobs
              where id = job;

                perform wallet_transfer(
                    (select user_id from public.load_requests where id = j.load_id),
                        (select driver_id from public.trucks where id = j.truck_id),
                            j.agreed_price,
                                'truck_payment',
                                    j.id::text
                                      );

                                        update public.truck_jobs set status = 'completed' where id = job;
                                          update public.load_requests set status = 'completed' where id = j.load_id;
                                          end;
                                          $$;


