CREATE OR REPLACE FUNCTION "public"."complete_wallet_scan"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'completed' AND OLD.status <> 'completed' THEN
      -- credit / debit wallet
          UPDATE wallets
              SET token_balance =
                    CASE
                            WHEN NEW.action IN ('deposit', 'payment') THEN token_balance + NEW.amount
                                    WHEN NEW.action IN ('withdraw') THEN token_balance - NEW.amount
                                            ELSE token_balance
                                                  END
                                                      WHERE user_id = NEW.user_id;
                                                        END IF;

                                                          RETURN NEW;
                                                          END;
                                                          $$;


ALTER FUNCTION "public"."complete_wallet_scan"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."compute_gofund_limit"("wallet" "uuid") RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_volume numeric;
  v_days int;
  v_entity text;
BEGIN

  SELECT total_volume, tx_count
  INTO v_volume, v_days
  FROM gofund_activity_profile
  WHERE wallet_id = wallet;

  SELECT entity_type
  INTO v_entity
  FROM financial_profiles
  WHERE wallet_id = wallet;

  RETURN calculate_liquidity_score(v_volume, v_days, v_entity);

END;
$$;


