CREATE OR REPLACE FUNCTION "public"."compute_payroll_entry"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.gross_pay := NEW.basic_salary + COALESCE(NEW.house_allowance, 0) + COALESCE(NEW.transport_allowance, 0) + COALESCE(NEW.other_allowances, 0);
    NEW.total_deductions := COALESCE(NEW.tax_deduction, 0) + COALESCE(NEW.pension_contribution, 0) + COALESCE(NEW.loan_deduction, 0) + COALESCE(NEW.other_deductions, 0);
    NEW.net_pay := NEW.gross_pay - NEW.total_deductions;
    RETURN NEW;
END;
$$;


