CREATE OR REPLACE FUNCTION "public"."compute_ride_metrics"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                BEGIN
                                                                                                                                                                                                                                                                                                                                                                                    IF NEW.pickup_lat IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                           AND NEW.pickup_lng IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                  AND NEW.dropoff_lat IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                         AND NEW.dropoff_lng IS NOT NULL THEN

                                                                                                                                                                                                                                                                                                                                                                                                                 NEW.distance_km :=
                                                                                                                                                                                                                                                                                                                                                                                                                             public.calculate_distance_km(
                                                                                                                                                                                                                                                                                                                                                                                                                                             NEW.pickup_lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                             NEW.pickup_lng,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                             NEW.dropoff_lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             NEW.dropoff_lng
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 NEW.estimated_fare :=
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             public.calculate_fare(NEW.distance_km);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 END IF;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     RETURN NEW;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     END;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     $$;


ALTER FUNCTION "public"."compute_ride_metrics"() OWNER TO "postgres";


