    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

tx_id uuid;
wallet_account uuid;

begin

insert into pool_contributions(pool_id,user_id,wallet_id,amount)

values(
p_pool,
auth.uid(),
p_wallet,
p_amount
);

insert into ledger_transactions(reference,transaction_type)

values(gen_random_uuid()::text,'pool_contribution')

returning id into tx_id;

select id into wallet_account
from ledger_accounts
where wallet_id = p_wallet
limit 1;

insert into ledger_entries(transaction_id,account_id,entry_type,amount)

values
(tx_id,wallet_account,'debit',p_amount);

return tx_id;

end;

