CREATE OR REPLACE FUNCTION "public"."create_post"("p_media_url" "text", "p_media_type" "text", "p_caption" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        declare
          v_post_id uuid;
            v_tags uuid[];
              v_hashtags text[];
              begin
                v_tags := extract_mentions(p_caption);

                  v_hashtags := array(
                      select lower(regexp_replace(tag, '#', '', 'g'))
                          from regexp_matches(p_caption, '#([a-zA-Z0-9_]+)', 'g') as tag
                            );

                              insert into posts (
                                  creator_id,
                                      media_url,
                                          media_type,
                                              caption,
                                                  tags,
                                                      hashtags,
                                                          is_processing
                                                            )
                                                              values (
                                                                  auth.uid(),
                                                                      p_media_url,
                                                                          p_media_type,
                                                                              p_caption,
                                                                                  v_tags,
                                                                                      v_hashtags,
                                                                                          false
                                                                                            )
                                                                                              returning id into v_post_id;

                                                                                                return v_post_id;
                                                                                                end;
                                                                                                $$;


