CREATE OR REPLACE FUNCTION "public"."create_shop_order"("p_user_id" "uuid", "p_cart_id" "uuid", "p_shipping_address" "jsonb", "p_payment_method" "text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_order_id uuid;
  v_total numeric := 0;
  v_item RECORD;
  v_stock integer;
BEGIN
  FOR v_item IN 
    SELECT ci.product_id, ci.qty, ci.unit_price, p.stock_quantity, p.name
    FROM public.cart_items ci
    JOIN public.products p ON p.id = ci.product_id
    WHERE ci.cart_id = p_cart_id
  LOOP
    IF v_item.stock_quantity < v_item.qty THEN
      RAISE EXCEPTION 'Insufficient stock for %: % < %', v_item.name, v_item.stock_quantity, v_item.qty;
    END IF;
    v_total := v_total + (v_item.unit_price * v_item.qty);
  END LOOP;

  INSERT INTO public.orders (buyer_user_id, status, payment_method, subtotal, total_amount, shipping_address, created_at)
  VALUES (p_user_id, 'pending', p_payment_method, v_total, v_total, p_shipping_address, now())
  RETURNING id INTO v_order_id;

  FOR v_item IN 
    SELECT ci.product_id, ci.qty, ci.unit_price
    FROM public.cart_items ci
    WHERE ci.cart_id = p_cart_id
  LOOP
    INSERT INTO public.order_items (order_id, product_id, qty, unit_price, created_at)
    VALUES (v_order_id, v_item.product_id, v_item.qty, v_item.unit_price, now());

    UPDATE public.products 
    SET stock_quantity = stock_quantity - v_item.qty, updated_at = now()
    WHERE id = v_item.product_id;
  END LOOP;

  DELETE FROM public.cart_items WHERE cart_id = p_cart_id;

  INSERT INTO public.escrow_accounts (service_id, sender_id, amount, status, created_at, service_type)
  VALUES (v_order_id, p_user_id, v_total, 'held', now(), 'shop_order');

  RETURN v_order_id;
END;
$$;


ALTER FUNCTION "public"."create_shop_order"("p_user_id" "uuid", "p_cart_id" "uuid", "p_shipping_address" "jsonb", "p_payment_method" "text") OWNER TO "postgres";


