CREATE OR REPLACE FUNCTION "public"."dispatch_event"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
    -- WALLET EVENTS
    if new.event_type = 'wallet.updated' then
        perform public.handle_wallet_event(new.payload, new.user_id);
    end if;

    -- ESCROW EVENTS
    if new.event_type = 'escrow.updated' then
        perform public.handle_escrow_event(new.payload, new.entity_id);
    end if;

    -- JOB EVENTS
    if new.event_type = 'job.application.created' then
        perform public.handle_job_event(new.payload, new.user_id);
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."dispatch_event"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."distribute_dividends"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  pool numeric;
    total_issued bigint;
      r record;
        payout numeric;
        begin
          select balance into pool from public.dividend_pool where id = 1;
            select issued_shares into total_issued from public.platform_shares where id = 1;

              if pool <= 0 or total_issued = 0 then
                  return;
                    end if;

                      for r in select * from public.user_shares loop
                          payout := (r.shares::numeric / total_issued) * pool;

                              if payout > 0 then
                                    update public.wallets
                                          set balance = balance + payout
                                                where user_id = r.user_id;

                                                      insert into public.share_transactions (
                                                              user_id, shares, total_amount, type
                                                                    ) values (
                                                                            r.user_id, r.shares, payout, 'dividend'
                                                                                  );
                                                                                      end if;
                                                                                        end loop;

                                                                                          update public.dividend_pool set balance = 0;
                                                                                          end;
                                                                                          $$;


ALTER FUNCTION "public"."distribute_dividends"() OWNER TO "postgres";


