CREATE OR REPLACE FUNCTION "public"."ensure_rls_policies"("p_table_name" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $_$
DECLARE
  v_has_user_id boolean;
  v_has_owner_id boolean;
  v_has_created_by boolean;
BEGIN
  SELECT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_name = p_table_name AND column_name = 'user_id') INTO v_has_user_id;
  SELECT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_name = p_table_name AND column_name = 'owner_id') INTO v_has_owner_id;
  SELECT EXISTS(SELECT 1 FROM information_schema.columns WHERE table_name = p_table_name AND column_name = 'created_by') INTO v_has_created_by;

  EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', p_table_name);

  IF v_has_user_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_select') THEN
    EXECUTE format('CREATE POLICY "%1$s_select" ON public.%1$s FOR SELECT USING (user_id = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  ELSIF v_has_owner_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_select') THEN
    EXECUTE format('CREATE POLICY "%1$s_select" ON public.%1$s FOR SELECT USING (owner_id = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  ELSIF v_has_created_by AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_select') THEN
    EXECUTE format('CREATE POLICY "%1$s_select" ON public.%1$s FOR SELECT USING (created_by = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  END IF;

  IF v_has_user_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_insert') THEN
    EXECUTE format('CREATE POLICY "%1$s_insert" ON public.%1$s FOR INSERT WITH CHECK (user_id = auth.uid())', p_table_name);
  ELSIF v_has_owner_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_insert') THEN
    EXECUTE format('CREATE POLICY "%1$s_insert" ON public.%1$s FOR INSERT WITH CHECK (owner_id = auth.uid())', p_table_name);
  ELSIF v_has_created_by AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_insert') THEN
    EXECUTE format('CREATE POLICY "%1$s_insert" ON public.%1$s FOR INSERT WITH CHECK (created_by = auth.uid())', p_table_name);
  END IF;

  IF v_has_user_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_update') THEN
    EXECUTE format('CREATE POLICY "%1$s_update" ON public.%1$s FOR UPDATE USING (user_id = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  ELSIF v_has_owner_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_update') THEN
    EXECUTE format('CREATE POLICY "%1$s_update" ON public.%1$s FOR UPDATE USING (owner_id = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  ELSIF v_has_created_by AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_update') THEN
    EXECUTE format('CREATE POLICY "%1$s_update" ON public.%1$s FOR UPDATE USING (created_by = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  END IF;

  IF v_has_user_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_delete') THEN
    EXECUTE format('CREATE POLICY "%1$s_delete" ON public.%1$s FOR DELETE USING (user_id = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  ELSIF v_has_owner_id AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_delete') THEN
    EXECUTE format('CREATE POLICY "%1$s_delete" ON public.%1$s FOR DELETE USING (owner_id = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  ELSIF v_has_created_by AND NOT EXISTS(SELECT 1 FROM pg_policies WHERE tablename = p_table_name AND policyname = p_table_name || '_delete') THEN
    EXECUTE format('CREATE POLICY "%1$s_delete" ON public.%1$s FOR DELETE USING (created_by = auth.uid() OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = ''admin''))', p_table_name);
  END IF;
END;
$_$;


