CREATE OR REPLACE FUNCTION "public"."finance_transfer"("from_user" "uuid", "to_user" "uuid", "amount" numeric, "currency" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
declare
  sender_balance numeric;
begin

  -- lock sender account
  select balance into sender_balance
  from finance_accounts
  where user_id = from_user
  for update;

  if sender_balance < amount then
    raise exception 'INSUFFICIENT_FUNDS';
  end if;

  -- deduct sender
  update finance_accounts
  set balance = balance - amount,
      updated_at = now()
  where user_id = from_user;

  -- credit receiver
  insert into finance_accounts (user_id, balance, currency)
  values (to_user, amount, currency)
  on conflict (user_id)
  do update set balance = finance_accounts.balance + excluded.balance;

  -- ledger entries
  insert into finance_ledger (user_id, type, amount, currency, reference)
  values
    (from_user, 'debit', amount, currency, 'transfer_out'),
    (to_user, 'credit', amount, currency, 'transfer_in');

end;
$$;


ALTER FUNCTION "public"."finance_transfer"("from_user" "uuid", "to_user" "uuid", "amount" numeric, "currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."find_duplicates"("p_table_name" "text", "p_columns" "text"[]) RETURNS TABLE("duplicate_values" "jsonb", "occurrence_count" bigint)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_column_list text;
BEGIN
  v_column_list := array_to_string(p_columns, ', ');
  RETURN QUERY EXECUTE format(
    'SELECT to_jsonb(%s) as vals, COUNT(*) as cnt
     FROM public.%I
     GROUP BY %s
     HAVING COUNT(*) > 1',
    v_column_list, p_table_name, v_column_list
  );
END;
$$;


