CREATE OR REPLACE FUNCTION "public"."find_nearest_drivers"("p_org_id" "uuid", "p_pickup_lat" double precision, "p_pickup_lng" double precision, "p_limit" integer DEFAULT 5) RETURNS TABLE("driver_id" "uuid", "distance_km" numeric)
    LANGUAGE "sql" STABLE
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             SELECT
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                 d.id AS driver_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     public.calculate_distance_km(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             p_pickup_lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     p_pickup_lng,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             d.current_lat,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                     d.current_lng
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         ) AS distance_km
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         FROM public.drivers d
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                         WHERE d.org_id = p_org_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                           AND d.is_available = true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                             AND d.current_lat IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               AND d.current_lng IS NOT NULL
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               ORDER BY distance_km ASC
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               LIMIT p_limit;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                               $$;


ALTER FUNCTION "public"."find_nearest_drivers"("p_org_id" "uuid", "p_pickup_lat" double precision, "p_pickup_lng" double precision, "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_audit_log"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_user_id TEXT;
BEGIN
  BEGIN
    v_user_id := current_setting('request.jwt.claims', true)::json->>'sub';
  EXCEPTION WHEN OTHERS THEN
    v_user_id := NULL;
  END;

  IF (TG_OP = 'DELETE') THEN
    INSERT INTO audit_logs (table_name, record_id, action, old_data, changed_by)
    VALUES (TG_TABLE_NAME, OLD.id, 'DELETE', row_to_json(OLD), v_user_id);
    RETURN OLD;
  ELSIF (TG_OP = 'UPDATE') THEN
    INSERT INTO audit_logs (table_name, record_id, action, old_data, new_data, changed_by)
    VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', row_to_json(OLD), row_to_json(NEW), v_user_id);
    RETURN NEW;
  ELSIF (TG_OP = 'INSERT') THEN
    INSERT INTO audit_logs (table_name, record_id, action, new_data, changed_by)
    VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', row_to_json(NEW), v_user_id);
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."fn_audit_log"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."fn_auto_flag_transaction"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF NEW.amount > 1000000 THEN
    INSERT INTO regulatory_flags (transaction_id, user_id, flag_type, severity, description, risk_score, evidence)
    VALUES (NEW.id, NEW.user_id, 'amount', 'high',
      'Large transaction: ' || NEW.amount || ' ' || NEW.currency,
      LEAST(50 + (NEW.amount / 100000), 100),
      jsonb_build_object('amount', NEW.amount, 'currency', NEW.currency, 'threshold', 1000000));
  END IF;
  
  IF (SELECT COUNT(*) FROM transactions WHERE user_id = NEW.user_id AND created_at >= NOW() - INTERVAL '1 hour') > 5 THEN
    INSERT INTO regulatory_flags (transaction_id, user_id, flag_type, severity, description, risk_score, evidence)
    VALUES (NEW.id, NEW.user_id, 'velocity', 'medium',
      'High velocity: >5 transactions in 1 hour', 40,
      jsonb_build_object('hourly_count', (SELECT COUNT(*) FROM transactions WHERE user_id = NEW.user_id AND created_at >= NOW() - INTERVAL '1 hour')));
  END IF;
  
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."fn_auto_flag_transaction"() OWNER TO "postgres";


