CREATE OR REPLACE FUNCTION "public"."fund_job_escrow"("p_wallet" "uuid", "p_job" "uuid", "p_worker" "uuid", "p_amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

tx_id uuid;
wallet_account uuid;
escrow_id uuid;

begin

insert into escrow_accounts(job_id,employer_id,worker_id,amount)

values(
p_job,
auth.uid(),
p_worker,
p_amount
)

returning id into escrow_id;


insert into ledger_transactions(reference,transaction_type)

values(gen_random_uuid()::text,'escrow_funding')

returning id into tx_id;


select id into wallet_account
from ledger_accounts
where wallet_id = p_wallet
limit 1;


insert into ledger_entries(transaction_id,account_id,entry_type,amount)

values
(tx_id,wallet_account,'debit',p_amount);


return escrow_id;

end;

$$;


