    SELECT county_code INTO c_code FROM public.counties WHERE id = NEW.county_id;
    year := EXTRACT(YEAR FROM NOW());

    SELECT COUNT(*) + 1 INTO seq_num
    FROM public.county_bills
    WHERE county_id = NEW.county_id
    AND EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM NOW());

    NEW.bill_number := c_code || '-' || year || '-' || LPAD(seq_num::TEXT, 6, '0');

    RETURN NEW;
END;
$$;


