CREATE OR REPLACE FUNCTION "public"."generate_bond_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    year TEXT;
    seq_num INTEGER;
BEGIN
    year := EXTRACT(YEAR FROM NEW.created_at);
    SELECT COALESCE(MAX(CAST(SUBSTRING(bond_number FROM 'BD-(\d+)-\d+$') AS INTEGER)), 0) + 1
    INTO seq_num
    FROM police_bonds
    WHERE EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM NEW.created_at);

    NEW.bond_number := 'BD-' || year || '-' || LPAD(seq_num::TEXT, 6, '0');
    RETURN NEW;
END;
$_$;


