    seq_num INTEGER;
BEGIN
    SELECT station_code INTO station_prefix FROM police_stations WHERE id = NEW.station_id;
    year := EXTRACT(YEAR FROM NEW.created_at);
    SELECT COALESCE(MAX(CAST(SUBSTRING(case_number FROM '.*-(\d+)$') AS INTEGER)), 0) + 1
    INTO seq_num
    FROM police_cases
    WHERE station_id = NEW.station_id AND EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM NEW.created_at);

    NEW.case_number := station_prefix || '-' || year || '-' || LPAD(seq_num::TEXT, 6, '0');
