CREATE OR REPLACE FUNCTION "public"."generate_license_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    c_code TEXT;
    s_code TEXT;
    year TEXT;
    seq_num INTEGER;
BEGIN
    SELECT c.county_code, cs.service_code INTO c_code, s_code
    FROM public.counties c
    JOIN public.county_services cs ON cs.id = NEW.service_id
    WHERE c.id = NEW.county_id;

    year := EXTRACT(YEAR FROM NOW());

    SELECT COUNT(*) + 1 INTO seq_num
    FROM public.county_licenses
    WHERE county_id = NEW.county_id AND service_id = NEW.service_id
    AND EXTRACT(YEAR FROM created_at) = EXTRACT(YEAR FROM NOW());

    NEW.license_number := c_code || '-' || s_code || '-' || year || '-' || LPAD(seq_num::TEXT, 5, '0');

    RETURN NEW;
END;
$$;


