CREATE OR REPLACE FUNCTION "public"."generate_procurement_number"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $_$
DECLARE
    station_prefix TEXT;
    seq_num INTEGER;
BEGIN
    SELECT station_code INTO station_prefix FROM police_stations WHERE id = NEW.station_id;
    SELECT COALESCE(MAX(CAST(SUBSTRING(request_number FROM '.*-PR-(\d+)$') AS INTEGER)), 0) + 1
    INTO seq_num
    FROM police_procurement
    WHERE station_id = NEW.station_id;

    NEW.request_number := station_prefix || '-PR-' || LPAD(seq_num::TEXT, 4, '0');
    RETURN NEW;
END;
$_$;


