CREATE OR REPLACE FUNCTION "public"."generate_property_availability"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_date DATE;
  v_end_date DATE;
BEGIN
  v_date := CURRENT_DATE;
  v_end_date := CURRENT_DATE + INTERVAL '2 years';

  WHILE v_date <= v_end_date LOOP
    INSERT INTO property_availability (property_id, date, is_available)
    VALUES (NEW.id, v_date, TRUE)
    ON CONFLICT (property_id, date) DO NOTHING;
    v_date := v_date + INTERVAL '1 day';
  END LOOP;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_property_availability"() OWNER TO "postgres";


