    IF NEW.default_action IS NOT NULL THEN
        NEW.deep_link := NEW.deep_link || '&a=' || NEW.default_action;
    END IF;
    IF NEW.prefilled_amount IS NOT NULL THEN
        NEW.deep_link := NEW.deep_link || '&amt=' || NEW.prefilled_amount::TEXT;
    END IF;
    RETURN NEW;
END;
$$;


