CREATE OR REPLACE FUNCTION "public"."generate_tribe_code"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  if new.code is null then
      new.code :=
            lower(
                    left(regexp_replace(new.name, '[^a-zA-Z]', '', 'g'), 2)
                          )
                                || '-' ||
                                      substr(gen_random_uuid()::text, 1, 6);
                                        end if;

                                          return new;
                                          end;
                                          $$;


ALTER FUNCTION "public"."generate_tribe_code"() OWNER TO "postgres";


