CREATE OR REPLACE FUNCTION "public"."generate_wallet_tx_hash"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  NEW.tx_hash :=
    encode(
      digest(
        COALESCE(NEW.wallet_id::text,'') ||
        COALESCE(NEW.amount::text,'') ||
        COALESCE(NEW.currency,'') ||
        COALESCE(NEW.direction,'') ||
        COALESCE(NEW.created_at::text,''),
        'sha256'
      ),
      'hex'
    );

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."generate_wallet_tx_hash"() OWNER TO "postgres";


