CREATE OR REPLACE FUNCTION "public"."get_localized_announcements"("p_user_id" "uuid") RETURNS TABLE("id" "uuid", "staff_id" "uuid", "institution_id" "uuid", "title" "text", "content" "text", "media_url" "text", "media_type" "text", "priority" "text", "is_pinned" boolean, "visibility_scope" "text", "read_count" integer, "created_at" timestamp with time zone, "staff_name" "text", "institution_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    a.id, a.staff_id, a.institution_id, a.title, a.content, a.media_url, a.media_type, a.priority, a.is_pinned, a.visibility_scope, a.read_count, a.created_at,
    p.full_name as staff_name,
    i.name as institution_name
  FROM education_announcements a
  JOIN education_staff s ON a.staff_id = s.id
  JOIN user_profiles p ON s.user_id = p.user_id
  JOIN education_institutions i ON a.institution_id = i.id
  WHERE
    (a.visibility_scope = 'national')
    OR (a.visibility_scope = 'state' AND (EXISTS (SELECT 1 FROM education_staff WHERE user_id = p_user_id) OR EXISTS (SELECT 1 FROM education_students WHERE user_id = p_user_id)))
    OR (a.visibility_scope = 'county' AND (EXISTS (SELECT 1 FROM education_staff es JOIN education_institutions ei ON es.institution_id = ei.id WHERE es.user_id = p_user_id AND ei.county = i.county) OR EXISTS (SELECT 1 FROM education_students est JOIN education_institutions ei ON est.institution_id = ei.id WHERE est.user_id = p_user_id AND ei.county = i.county)))
    OR (a.visibility_scope = 'district' AND (EXISTS (SELECT 1 FROM education_staff es JOIN education_institutions ei ON es.institution_id = ei.id WHERE es.user_id = p_user_id AND ei.district = i.district) OR EXISTS (SELECT 1 FROM education_students est JOIN education_institutions ei ON est.institution_id = ei.id WHERE est.user_id = p_user_id AND ei.district = i.district)))
    OR (a.visibility_scope = 'school' AND (EXISTS (SELECT 1 FROM education_staff WHERE user_id = p_user_id AND institution_id = a.institution_id) OR EXISTS (SELECT 1 FROM education_students WHERE user_id = p_user_id AND institution_id = a.institution_id)))
  ORDER BY a.is_pinned DESC, a.created_at DESC
  LIMIT 50;
END;
$$;


