CREATE OR REPLACE FUNCTION "public"."get_nearby_carpool_requests"("p_lat" double precision, "p_lng" double precision) RETURNS TABLE("id" "uuid", "passenger_user_id" "uuid", "departure_time" timestamp with time zone, "seats_needed" integer, "distance_km" double precision)
    LANGUAGE "sql" STABLE
    AS $$
                                                                                                                                                                select
                                                                                                                                                                    r.id,
                                                                                                                                                                        r.passenger_user_id,
                                                                                                                                                                            r.departure_time,
                                                                                                                                                                                r.seats_needed,
                                                                                                                                                                                    (st_distance(
                                                                                                                                                                                          st_setsrid(st_makepoint(r.origin_lng, r.origin_lat), 4326)::geography,
                                                                                                                                                                                                st_setsrid(st_makepoint(p_lng, p_lat), 4326)::geography
                                                                                                                                                                                                    ) / 1000.0) as distance_km
                                                                                                                                                                                                      from public.carpool_requests r
                                                                                                                                                                                                        where r.status = 'open'
                                                                                                                                                                                                          order by distance_km asc, r.departure_time asc
                                                                                                                                                                                                            limit 50;
                                                                                                                                                                                                            $$;


