    LANGUAGE "plpgsql"
    AS $$
          declare 
              result uuid; 
              begin
                  select ll.user_id 
                      into result 
                          from public.live_locations ll 
                              join public.transport_operators op on op.user_id = ll.user_id 
                                  where ll.role = 'operator' 
