CREATE OR REPLACE FUNCTION "public"."get_or_create_tribe_id"("p_name" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                    DECLARE
                      v_id uuid;
                        v_code text;
                        BEGIN
                          SELECT id INTO v_id FROM public.tribes WHERE lower(name) = lower(trim(p_name));
                            IF v_id IS NOT NULL THEN
                                RETURN v_id;
                                  END IF;

                                    v_code := public.generate_tribe_code(p_name);

                                      INSERT INTO public.tribes (name, code)
                                        VALUES (trim(p_name), v_code)
                                          RETURNING id INTO v_id;

                                            RETURN v_id;
                                            END;
                                            $$;


ALTER FUNCTION "public"."get_or_create_tribe_id"("p_name" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_or_create_tribe_id"("p_name" "text", "p_country" "text" DEFAULT NULL::"text", "p_region" "text" DEFAULT NULL::"text", "p_description" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
                      DECLARE
                        v_id uuid;
                          v_code text;
                            v_try int := 0;
                            BEGIN
                              -- Find existing by name
                                SELECT id INTO v_id
                                  FROM public.tribes
                                    WHERE lower(name) = lower(trim(p_name))
                                      LIMIT 1;

                                        IF v_id IS NOT NULL THEN
                                            RETURN v_id;
                                              END IF;

                                                v_code := public.generate_tribe_code(p_name);

                                                  LOOP
                                                      BEGIN
                                                            INSERT INTO public.tribes (name, code, country, region, description)
                                                                  VALUES (trim(p_name), v_code, p_country, p_region, p_description)
                                                                        RETURNING id INTO v_id;

                                                                              RETURN v_id;
                                                                                  EXCEPTION
                                                                                        WHEN unique_violation THEN
                                                                                                v_try := v_try + 1;
                                                                                                        IF v_try > 25 THEN
                                                                                                                  RAISE EXCEPTION 'Could not generate unique tribe code for %', p_name;
                                                                                                                          END IF;
                                                                                                                                  v_code := public.generate_tribe_code(p_name) || '_' || v_try::text;
                                                                                                                                      END;
                                                                                                                                        END LOOP;
                                                                                                                                        END;
                                                                                                                                        $$;


ALTER FUNCTION "public"."get_or_create_tribe_id"("p_name" "text", "p_country" "text", "p_region" "text", "p_description" "text") OWNER TO "postgres";


