CREATE OR REPLACE FUNCTION "public"."get_profile_stats"("p_profile_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'profile_id', p.id,
        'display_name', p.display_name,
        'username', p.username,
        'avatar_url', p.avatar_url,
        'is_verified', p.is_verified,
        'follower_count', p.follower_count,
        'following_count', p.following_count,
        'trust_score', p.trust_score,
        'completion_percentage', p.completion_percentage,
        'online_status', p.online_status,
        'total_views', COALESCE((SELECT SUM(profile_views) FROM public.profile_analytics WHERE profile_id = p_profile_id), 0),
        'total_tips', COALESCE((SELECT SUM(amount) FROM public.profile_tips WHERE recipient_profile_id = p_profile_id AND status = 'completed'), 0),
        'total_subscribers', (SELECT COUNT(*) FROM public.profile_subscriptions WHERE creator_profile_id = p_profile_id AND status = 'active'),
        'total_achievements', (SELECT COUNT(*) FROM public.profile_achievements WHERE profile_id = p_profile_id),
        'is_blocked_by_me', EXISTS(SELECT 1 FROM public.profile_blocks WHERE blocker_profile_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid()) AND blocked_profile_id = p_profile_id),
        'is_following_me', EXISTS(SELECT 1 FROM public.profile_connections WHERE profile_id = p_profile_id AND connected_profile_id = (SELECT id FROM public.profiles WHERE user_id = auth.uid()) AND status = 'active')
    )
    INTO result
    FROM public.profiles p
    WHERE p.id = p_profile_id;
    
    RETURN result;
END;
$$;


ALTER FUNCTION "public"."get_profile_stats"("p_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."get_public_profile"("p_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    result JSONB;
BEGIN
    SELECT jsonb_build_object(
        'id', p.id,
        'display_name', p.display_name,
        'username', p.username,
        'avatar_url', p.avatar_url,
        'cover_photo_url', p.cover_photo_url,
        'bio', p.bio,
        'profession', p.profession,
        'city', p.city,
        'country', p.country,
        'skills', p.skills,
        'languages', p.languages,
        'is_verified', p.is_verified,
        'verification_level', p.verification_level,
        'trust_score', p.trust_score,
        'profile_completeness', p.profile_completeness,
        'availability_status', p.availability_status,
        'roles', (SELECT jsonb_agg(role_type) FROM profile_roles WHERE profile_id = p.id AND is_active = true),
        'reputation', (SELECT jsonb_build_object(
            'overall_score', overall_score,
            'trust_score', trust_score,
            'business_score', business_score,
            'community_score', community_score
        ) FROM profile_reputation WHERE profile_id = p.id),
        'portfolio_count', (SELECT count(*) FROM profile_portfolios WHERE profile_id = p.id AND is_public = true),
        'achievement_count', (SELECT count(*) FROM profile_achievements WHERE profile_id = p.id AND visibility = 'public'),
        'business_count', (SELECT count(*) FROM profile_businesses WHERE profile_id = p.id AND is_active = true),
        'connection_count', (SELECT count(*) FROM profile_connections WHERE profile_id = p.id AND status = 'active')
    ) INTO result
    FROM profiles p
    WHERE p.id = p_id AND p.is_public = true AND p.deleted_at IS NULL;
    RETURN result;
END;
$$;


