CREATE OR REPLACE FUNCTION "public"."get_regulatory_summary"("p_start_date" "date", "p_end_date" "date") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE result JSONB;
BEGIN
  SELECT jsonb_build_object(
    'total_volume', COALESCE(SUM(amount), 0),
    'total_transactions', COUNT(*),
    'active_users', COUNT(DISTINCT user_id),
    'avg_transaction_size', COALESCE(AVG(amount), 0),
    'period_start', p_start_date,
    'period_end', p_end_date
  ) INTO result
  FROM transactions
  WHERE created_at >= p_start_date AND created_at < (p_end_date + INTERVAL '1 day');
  RETURN result;
EXCEPTION WHEN OTHERS THEN
  RETURN '{}'::jsonb;
END;
$$;


