CREATE OR REPLACE FUNCTION "public"."get_teacher_earnings"("p_staff_id" "uuid") RETURNS TABLE("total_earnings" numeric, "current_balance" numeric, "total_views" bigint, "total_unique_views" bigint, "total_purchases" bigint, "top_lesson" "uuid", "top_lesson_earnings" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.total_earnings,
    s.earnings_balance,
    COALESCE(SUM(l.views_count), 0)::bigint,
    COALESCE(SUM(l.unique_views_count), 0)::bigint,
    COALESCE((SELECT COUNT(*) FROM education_purchases p JOIN education_lessons ls ON p.lesson_id = ls.id WHERE ls.staff_id = p_staff_id), 0)::bigint,
    (SELECT id FROM education_lessons WHERE staff_id = p_staff_id ORDER BY earnings_total DESC LIMIT 1),
    COALESCE((SELECT earnings_total FROM education_lessons WHERE staff_id = p_staff_id ORDER BY earnings_total DESC LIMIT 1), 0)
  FROM education_staff s
  LEFT JOIN education_lessons l ON l.staff_id = s.id
  WHERE s.id = p_staff_id
  GROUP BY s.total_earnings, s.earnings_balance;
END;
$$;


