CREATE OR REPLACE FUNCTION "public"."get_user_feed"("user_lat" double precision, "user_lng" double precision, "limit_count" integer) RETURNS TABLE("post_id" "uuid", "content" "text", "weighted_score" numeric)
    LANGUAGE "plpgsql"
    AS $$
                             BEGIN
                                 RETURN QUERY
                                     SELECT
                                             p.id,
                                                     p.content,
                                                             COALESCE(fs.score,0) * COALESCE(r.score,1) AS weighted_score
                                                                 FROM posts p
                                                                     LEFT JOIN (
                                                                             SELECT post_id, SUM(weight) AS score
                                                                                     FROM feed_events
                                                                                             GROUP BY post_id
                                                                                                 ) fs ON fs.post_id = p.id
                                                                                                     LEFT JOIN reputation_scores r ON r.user_id = p.user_id
                                                                                                         WHERE ST_DWithin(p.origin, ST_MakePoint(user_lng, user_lat)::geography, 10000)
                                                                                                             ORDER BY weighted_score DESC
                                                                                                                 LIMIT limit_count;
                                                                                                                 END;
                                                                                                                 $$;


