CREATE OR REPLACE FUNCTION "public"."gofund_assess"("p_wallet_id" "uuid") RETURNS "jsonb"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_volume numeric := 0;
  v_count int := 0;
  v_available numeric := 0;
  v_pending numeric := 0;
  v_reserved numeric := 0;
  v_score numeric := 0;
  v_limit numeric := 0;
begin

  -- 1. GET TRANSACTION VOLUME (last 30 days)
  select
    coalesce(sum(amount), 0),
    count(*)
  into v_volume, v_count
  from wallet_transactions
  where wallet_id = p_wallet_id
    and created_at >= now() - interval '30 days';

  -- 2. GET WALLET BALANCE (FROM VIEW)
  select
    available_balance,
    pending_balance,
    reserved_balance
  into v_available, v_pending, v_reserved
  from wallet_balances
  where wallet_id = p_wallet_id;

  -- 3. BASIC RISK SCORE (SAFE + SIMPLE)
  v_score :=
    (v_volume * 0.6) +
    (v_count * 10) +
    (v_available * 0.4)
    - (v_reserved * 0.5);

  -- 4. LIMIT CALCULATION (GOFUND CREDIT)
  v_limit := greatest(v_score * 0.1, 0);

  -- 5. RETURN STRUCTURED RESULT
  return jsonb_build_object(
    'wallet_id', p_wallet_id,
    'volume_30d', v_volume,
    'transactions_30d', v_count,
    'available_balance', v_available,
    'risk_score', v_score,
    'gofund_limit', v_limit,
    'approved', v_score > 500
  );

end;
$$;


ALTER FUNCTION "public"."gofund_assess"("p_wallet_id" "uuid") OWNER TO "postgres";


