CREATE OR REPLACE FUNCTION "public"."handle_user_content_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.profiles
    SET content_count = content_count + 1,
        updated_at = NOW()
    WHERE user_id = NEW.user_id;
    RETURN NEW;
  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.profiles
    SET content_count = GREATEST(content_count - 1, 0),
        total_views = GREATEST(total_views - OLD.views, 0),
        total_likes = GREATEST(total_likes - OLD.likes, 0),
        total_comments = GREATEST(total_comments - OLD.comments, 0),
        total_shares = GREATEST(total_shares - OLD.shares, 0),
        updated_at = NOW()
    WHERE user_id = OLD.user_id;
    RETURN OLD;
  ELSIF TG_OP = 'UPDATE' THEN
    UPDATE public.profiles
    SET total_views = total_views - OLD.views + NEW.views,
        total_likes = total_likes - OLD.likes + NEW.likes,
        total_comments = total_comments - OLD.comments + NEW.comments,
        total_shares = total_shares - OLD.shares + NEW.shares,
        updated_at = NOW()
    WHERE user_id = NEW.user_id;
    RETURN NEW;
  END IF;
  RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."handle_user_content_change"() OWNER TO "postgres";


