CREATE OR REPLACE FUNCTION "public"."handle_view_monetization"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
declare
  rule record;
    payable_views integer := 0;
    begin
      -- Fetch active monetization rule for feed
        select *
          into rule
            from monetization_rules
              where module = 'feed'
                  and active = true
                    limit 1;

                      -- If no rule, do nothing
                        if rule is null then
                            return new;
                              end if;

                                -- Calculate newly payable views
                                  payable_views :=
                                      (new.view_count / rule.views_required)
                                          - (coalesce(old.view_count, 0) / rule.views_required);

                                            -- If no new payable views, exit
                                              if payable_views <= 0 then
                                                  return new;
                                                    end if;

                                                      -- Credit earnings
                                                        insert into earnings (
                                                            user_id,
                                                                source,
                                                                    amount,
                                                                        status,
                                                                            created_at
                                                                              )
                                                                                values (
                                                                                    new.user_id,
                                                                                        'feed_views',
                                                                                            payable_views * rule.amount_per_view,
                                                                                                'pending',
                                                                                                    now()
                                                                                                      );

                                                                                                        return new;
                                                                                                        end;
                                                                                                        $$;


ALTER FUNCTION "public"."handle_view_monetization"() OWNER TO "postgres";


