CREATE OR REPLACE FUNCTION "public"."health_clock_in"("p_user_id" "uuid", "p_facility_id" "uuid", "p_method" "text" DEFAULT 'manual'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_staff_id UUID;
  v_record_id UUID;
BEGIN
  SELECT id INTO v_staff_id
  FROM health_staff
  WHERE user_id = p_user_id AND facility_id = p_facility_id
  LIMIT 1;
  
  IF v_staff_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Staff record not found');
  END IF;
  
  UPDATE health_staff 
  SET last_clock_in = NOW(),
      is_on_duty = true,
      current_shift_start = NOW()
  WHERE id = v_staff_id;
  
  INSERT INTO health_attendance (staff_id, facility_id, user_id, clock_in_at, clock_in_method, status)
  VALUES (v_staff_id, p_facility_id, p_user_id, NOW(), p_method, 'active')
  RETURNING id INTO v_record_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'record_id', v_record_id,
    'clock_in', NOW(),
    'staff_id', v_staff_id
  );
END;
$$;


ALTER FUNCTION "public"."health_clock_in"("p_user_id" "uuid", "p_facility_id" "uuid", "p_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."health_clock_out"("p_user_id" "uuid", "p_facility_id" "uuid", "p_method" "text" DEFAULT 'manual'::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_staff_id UUID;
  v_record_id UUID;
  v_clock_in TIMESTAMPTZ;
  v_hours NUMERIC;
BEGIN
  SELECT id INTO v_staff_id
  FROM health_staff
  WHERE user_id = p_user_id AND facility_id = p_facility_id
  LIMIT 1;
  
  IF v_staff_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Staff record not found');
  END IF;
  
  SELECT id, clock_in_at INTO v_record_id, v_clock_in
  FROM health_attendance
  WHERE staff_id = v_staff_id AND facility_id = p_facility_id AND status = 'active'
  ORDER BY clock_in_at DESC
  LIMIT 1;
  
  IF v_record_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active clock-in found');
  END IF;
  
  v_hours := EXTRACT(EPOCH FROM (NOW() - v_clock_in)) / 3600;
  
  UPDATE health_attendance
  SET clock_out_at = NOW(),
      clock_out_method = p_method,
      hours_worked = v_hours,
      status = 'completed'
  WHERE id = v_record_id;
  
  UPDATE health_staff 
  SET last_clock_out = NOW(),
      is_on_duty = false,
      current_shift_end = NOW()
  WHERE id = v_staff_id;
  
  RETURN jsonb_build_object(
    'success', true,
    'record_id', v_record_id,
    'clock_out', NOW(),
    'hours_worked', ROUND(v_hours, 2),
    'staff_id', v_staff_id
  );
END;
$$;


ALTER FUNCTION "public"."health_clock_out"("p_user_id" "uuid", "p_facility_id" "uuid", "p_method" "text") OWNER TO "postgres";


