CREATE OR REPLACE FUNCTION "public"."health_get_all_staff_for_admin"("p_status_filter" "text" DEFAULT NULL::"text", "p_role_filter" "text" DEFAULT NULL::"text", "p_search_query" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "user_id" "uuid", "facility_id" "uuid", "role" "text", "department" "text", "specialization" "text", "status" "text", "onboarding_status" "text", "is_on_duty" boolean, "years_of_experience" integer, "consultation_fee" numeric, "license_number" "text", "license_body" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "user_email" "text", "user_full_name" "text", "facility_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    hs.id,
    hs.user_id,
    hs.facility_id,
    hs.role,
    hs.department,
    hs.specialization,
    hs.status,
    hs.onboarding_status,
    hs.is_on_duty,
    hs.years_of_experience,
    hs.consultation_fee,
    hs.license_number,
    hs.license_body,
    hs.created_at,
    hs.updated_at,
    COALESCE(up.email, au.email) AS user_email,
    COALESCE(up.full_name, au.raw_user_meta_data->>'full_name') AS user_full_name,
    hf.name AS facility_name
  FROM health_staff hs
  LEFT JOIN user_profiles up ON hs.user_id = up.id
  LEFT JOIN auth.users au ON hs.user_id = au.id
  LEFT JOIN health_facilities hf ON hs.facility_id = hf.id
  WHERE 
    (p_status_filter IS NULL OR p_status_filter = 'All' OR hs.status = p_status_filter)
    AND (p_role_filter IS NULL OR p_role_filter = 'All Roles' OR hs.role = p_role_filter)
    AND (
      p_search_query IS NULL 
      OR p_search_query = '' 
      OR au.email ILIKE '%' || p_search_query || '%'
      OR up.full_name ILIKE '%' || p_search_query || '%'
      OR hf.name ILIKE '%' || p_search_query || '%'
    )
  ORDER BY hs.created_at DESC;
END;
$$;


ALTER FUNCTION "public"."health_get_all_staff_for_admin"("p_status_filter" "text", "p_role_filter" "text", "p_search_query" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."health_get_all_staff_for_system_admin"("p_status_filter" "text" DEFAULT 'All'::"text", "p_role_filter" "text" DEFAULT 'All Roles'::"text", "p_search_query" "text" DEFAULT ''::"text") RETURNS TABLE("id" "uuid", "user_id" "uuid", "facility_id" "uuid", "role" "text", "department" "text", "specialization" "text", "status" "text", "onboarding_status" "text", "is_on_duty" boolean, "years_of_experience" integer, "consultation_fee" numeric, "license_number" "text", "license_body" "text", "created_at" timestamp with time zone, "updated_at" timestamp with time zone, "user_email" "text", "user_full_name" "text", "facility_name" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT hs.id, hs.user_id, hs.facility_id, hs.role,
         hs.department, hs.specialization, hs.status,
         hs.onboarding_status, hs.is_on_duty,
         hs.years_of_experience, hs.consultation_fee,
         hs.license_number, hs.license_body,
         hs.created_at, hs.updated_at,
         au.email as user_email,
         COALESCE(up.full_name, au.email) as user_full_name,
         hf.name as facility_name
  FROM health_staff hs
  LEFT JOIN auth.users au ON hs.user_id = au.id
  LEFT JOIN user_profiles up ON hs.user_id = up.id
  LEFT JOIN health_facilities hf ON hs.facility_id = hf.id
  WHERE (p_status_filter = 'All' OR hs.status = p_status_filter)
    AND (p_role_filter = 'All Roles' OR hs.role = p_role_filter)
    AND (p_search_query = '' OR au.email ILIKE '%' || p_search_query || '%'
         OR COALESCE(up.full_name, '') ILIKE '%' || p_search_query || '%'
         OR COALESCE(hf.name, '') ILIKE '%' || p_search_query || '%')
  ORDER BY hs.created_at DESC;
END;
$$;


