    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    v.id AS vehicle_id,
    v.vehicle_number,
    v.vehicle_type,
    v.status,
    v.current_fuel_level,
    v.odometer_km,
    v.crew_capacity,
    v.assigned_station,
    v.latitude,
    v.longitude,
    v.last_location_update,
    d.id AS active_dispatch_id,
    d.status AS active_dispatch_status
  FROM public.health_ambulance_vehicles v
  LEFT JOIN public.health_ambulance_dispatches d
    ON d.vehicle_id = v.id AND d.status NOT IN ('completed', 'cancelled')
  WHERE p_facility_id IS NULL OR v.facility_id = p_facility_id
  ORDER BY v.vehicle_number;
END;
