CREATE OR REPLACE FUNCTION "public"."health_get_primary_staff_record"("p_user_id" "uuid") RETURNS TABLE("id" "uuid", "user_id" "uuid", "facility_id" "uuid", "role" "text", "department" "text", "license_number" "text", "verified" boolean, "specialization" "text", "shift_pattern" "text", "biometric_enrolled" boolean, "last_clock_in" timestamp with time zone, "last_clock_out" timestamp with time zone, "is_on_duty" boolean, "status" "text", "onboarding_status" "text")
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    hs.id,
    hs.user_id,
    hs.facility_id,
    hs.role,
    hs.department,
    hs.license_number,
    hs.status = 'active' as verified,
    hs.specialization,
    hs.shift_pattern,
    hs.biometric_enrolled,
    hs.last_clock_in,
    hs.last_clock_out,
    hs.is_on_duty,
    hs.status,
    hs.onboarding_status
  FROM health_staff hs
  WHERE hs.user_id = p_user_id
  ORDER BY 
    CASE hs.role
      WHEN 'system_admin' THEN 1
      WHEN 'facility_admin' THEN 2
      WHEN 'hospital_admin' THEN 3
      WHEN 'doctor' THEN 4
      WHEN 'nurse' THEN 5
      WHEN 'pharmacist' THEN 6
      WHEN 'lab_technician' THEN 7
      WHEN 'radiologist' THEN 8
      WHEN 'receptionist' THEN 9
      WHEN 'cashier' THEN 10
      WHEN 'accountant' THEN 11
      WHEN 'hr_manager' THEN 12
      WHEN 'ambulance_dispatcher' THEN 13
      WHEN 'emergency_responder' THEN 14
      WHEN 'insurance_officer' THEN 15
      WHEN 'pharmacy_manager' THEN 16
      WHEN 'data_analyst' THEN 17
      ELSE 99
    END,
    hs.created_at DESC
  LIMIT 1;
END;
$$;


