CREATE OR REPLACE FUNCTION "public"."health_get_today_queue"("p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_department" "text" DEFAULT NULL::"text") RETURNS TABLE("id" "uuid", "patient_name" "text", "mrn" "text", "visit_type" "text", "department" "text", "priority" "text", "queue_number" "text", "status" "text", "checked_in_at" timestamp with time zone, "assigned_doctor_name" "text", "wait_minutes" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    ci.id,
    CONCAT(p.first_name, ' ', p.last_name) AS patient_name,
    p.patient_code AS mrn,
    ci.visit_type,
    ci.department,
    ci.priority,
    ci.queue_number,
    ci.status,
    ci.checked_in_at,
    CONCAT(d.first_name, ' ', d.last_name) AS assigned_doctor_name,
    EXTRACT(MINUTE FROM (now() - ci.checked_in_at))::INTEGER AS wait_minutes
  FROM public.health_check_ins ci
  JOIN public.health_patients p ON p.id = ci.patient_id
  LEFT JOIN public.user_profiles d ON d.id = ci.assigned_doctor_id
  WHERE ci.status NOT IN ('discharged', 'transferred')
    AND DATE(ci.checked_in_at) = CURRENT_DATE
    AND (p_facility_id IS NULL OR ci.facility_id = p_facility_id)
    AND (p_department IS NULL OR ci.department = p_department)
  ORDER BY
    CASE ci.priority
      WHEN 'critical' THEN 1
      WHEN 'high' THEN 2
      WHEN 'normal' THEN 3
      WHEN 'low' THEN 4
    END,
    ci.checked_in_at ASC;
END;
$$;


