CREATE OR REPLACE FUNCTION "public"."health_staff_clock_in"("p_staff_id" "uuid", "p_facility_id" "uuid" DEFAULT NULL::"uuid", "p_method" "text" DEFAULT 'biometric'::"text", "p_biometric_confirmed" boolean DEFAULT false, "p_pin_confirmed" boolean DEFAULT false, "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_attendance_id UUID;
  v_existing UUID;
BEGIN
  SELECT id INTO v_existing
  FROM public.health_attendance
  WHERE staff_id = p_staff_id AND clock_out_at IS NULL
  ORDER BY clock_in_at DESC
  LIMIT 1;

  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Already clocked in. Clock out first.',
      'attendance_id', v_existing
    );
  END IF;

  INSERT INTO public.health_attendance (
    staff_id, facility_id, clock_in_method, biometric_confirmed,
    pin_confirmed, latitude, longitude, notes, status
  ) VALUES (
    p_staff_id, p_facility_id, p_method, p_biometric_confirmed,
    p_pin_confirmed, p_latitude, p_longitude, p_notes,
    CASE WHEN p_biometric_confirmed OR p_pin_confirmed THEN 'present' ELSE 'late' END
  )
  RETURNING id INTO v_attendance_id;

  RETURN jsonb_build_object(
    'success', true,
    'attendance_id', v_attendance_id,
    'clocked_in_at', now(),
    'method', p_method
  );
END;
$$;


ALTER FUNCTION "public"."health_staff_clock_in"("p_staff_id" "uuid", "p_facility_id" "uuid", "p_method" "text", "p_biometric_confirmed" boolean, "p_pin_confirmed" boolean, "p_latitude" numeric, "p_longitude" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."health_staff_clock_out"("p_staff_id" "uuid", "p_method" "text" DEFAULT 'biometric'::"text", "p_biometric_confirmed" boolean DEFAULT false, "p_pin_confirmed" boolean DEFAULT false, "p_latitude" numeric DEFAULT NULL::numeric, "p_longitude" numeric DEFAULT NULL::numeric, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_attendance_id UUID;
  v_clock_in TIMESTAMPTZ;
  v_duration INTERVAL;
BEGIN
  SELECT id, clock_in_at INTO v_attendance_id, v_clock_in
  FROM public.health_attendance
  WHERE staff_id = p_staff_id AND clock_out_at IS NULL
  ORDER BY clock_in_at DESC
  LIMIT 1;

  IF v_attendance_id IS NULL THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'No active clock-in found. Clock in first.'
    );
  END IF;

  v_duration := now() - v_clock_in;

  UPDATE public.health_attendance
  SET clock_out_at = now(),
      clock_out_method = p_method,
      biometric_confirmed = biometric_confirmed OR p_biometric_confirmed,
      pin_confirmed = pin_confirmed OR p_pin_confirmed,
      latitude = COALESCE(p_latitude, latitude),
      longitude = COALESCE(p_longitude, longitude),
      notes = COALESCE(notes || E'\n' || p_notes, p_notes),
      status = CASE
        WHEN EXTRACT(EPOCH FROM v_duration) < 3600 THEN 'early_leave'
        ELSE 'present'
      END,
      updated_at = now()
  WHERE id = v_attendance_id;

  RETURN jsonb_build_object(
    'success', true,
    'attendance_id', v_attendance_id,
    'clocked_out_at', now(),
    'duration_seconds', EXTRACT(EPOCH FROM v_duration),
    'method', p_method
  );
END;
$$;


ALTER FUNCTION "public"."health_staff_clock_out"("p_staff_id" "uuid", "p_method" "text", "p_biometric_confirmed" boolean, "p_pin_confirmed" boolean, "p_latitude" numeric, "p_longitude" numeric, "p_notes" "text") OWNER TO "postgres";


