CREATE OR REPLACE FUNCTION "public"."increment_tribe_member_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'INSERT' THEN
        UPDATE tribes SET member_count = member_count + 1 WHERE id = NEW.tribe_id;
    ELSIF TG_OP = 'DELETE' THEN
        UPDATE tribes SET member_count = member_count - 1 WHERE id = OLD.tribe_id;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."increment_tribe_member_count"() OWNER TO "postgres";


