    LANGUAGE "plpgsql"
    AS $$
        begin
          insert into public.installed_apps (
              user_id,
                  app_id,
                      name,
                          icon,
                              installed
                                )
                                  values (
                                      p_user_id,
                                          p_app_id,
                                              p_name,
                                                  p_icon,
                                                      true
                                                        )
                                                          on conflict (user_id, app_id)
                                                            do update set
                                                                installed = true,
                                                                    name = excluded.name,
                                                                        icon = excluded.icon;
                                                                        end;
                                                                        $$;


