CREATE OR REPLACE FUNCTION "public"."job_match_score"("_job_id" "uuid", "_user_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    job record;
    score numeric := 0;
begin
    select * into job from public.jobs where id = _job_id;

    if job is null then
        return 0;
    end if;

    -- core scoring (SAFE ONLY - no assumed columns)
    if job.status is not null then
        score := score + 40;
    end if;

    if job.created_at is not null then
        score := score + 20;
    end if;

    -- lightweight randomness for ranking diversity
    score := score + floor(random() * 40);

    return score;
end;
$$;


ALTER FUNCTION "public"."job_match_score"("_job_id" "uuid", "_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."join_live_room"("room" "uuid", "participant" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                 DECLARE
                                                                                                                                                                                                     room_price numeric;
                                                                                                                                                                                                         host_id uuid;
                                                                                                                                                                                                         BEGIN
                                                                                                                                                                                                             SELECT price, host_id INTO room_price, host_id FROM live_rooms WHERE id = room;

                                                                                                                                                                                                                 IF room_price > 0 THEN
                                                                                                                                                                                                                         PERFORM add_transaction(participant, -room_price, 'ppv', room);
                                                                                                                                                                                                                                 PERFORM add_transaction(host_id, room_price, 'ppv', room);
                                                                                                                                                                                                                                     END IF;

                                                                                                                                                                                                                                         INSERT INTO live_participants (room_id, user_id, joined_at)
                                                                                                                                                                                                                                             VALUES (room, participant, now());
                                                                                                                                                                                                                                             END;
                                                                                                                                                                                                                                             $$;


ALTER FUNCTION "public"."join_live_room"("room" "uuid", "participant" "uuid") OWNER TO "postgres";


