    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

member_id uuid;

begin

insert into pool_members(pool_id,user_id)

values(p_pool,auth.uid())

returning id into member_id;

return member_id;

end;

$$;


