CREATE OR REPLACE FUNCTION "public"."join_tribe_community"("p_user_id" "uuid", "p_tribe_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
      declare
        v_community_id uuid;
          v_room_id uuid;
          begin
            v_community_id := public.ensure_tribe_community(p_tribe_id);

              insert into public.tribe_community_members (community_id, user_id)
                values (v_community_id, p_user_id)
                  on conflict do nothing;

                    select chat_room_id into v_room_id
                      from public.tribe_communities
                        where id = v_community_id;

                          insert into public.chat_participants (room_id, user_id)
                            values (v_room_id, p_user_id)
                              on conflict do nothing;
                              end;
                              $$;


