CREATE OR REPLACE FUNCTION "public"."join_user_to_tribe"("p_user_id" "uuid", "p_tribe_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public', 'pg_temp'
    AS $$
                                                                                                                                                        DECLARE
                                                                                                                                                          v_comm_id uuid;
                                                                                                                                                            v_group_id uuid;
                                                                                                                                                            BEGIN
                                                                                                                                                              PERFORM public.ensure_tribe_structures(p_tribe_id);

                                                                                                                                                                SELECT id INTO v_comm_id FROM public.tribe_communities WHERE tribe_id = p_tribe_id LIMIT 1;
                                                                                                                                                                  IF v_comm_id IS NOT NULL THEN
                                                                                                                                                                      INSERT INTO public.tribe_community_members (community_id, user_id)
                                                                                                                                                                          VALUES (v_comm_id, p_user_id)
                                                                                                                                                                              ON CONFLICT (community_id, user_id) DO NOTHING;
                                                                                                                                                                                END IF;

                                                                                                                                                                                  SELECT id INTO v_group_id FROM public.tribe_groups WHERE tribe_id = p_tribe_id LIMIT 1;
                                                                                                                                                                                    IF v_group_id IS NOT NULL THEN
                                                                                                                                                                                        INSERT INTO public.user_tribe_groups (user_id, tribe_group_id)
                                                                                                                                                                                            VALUES (p_user_id, v_group_id)
                                                                                                                                                                                                ON CONFLICT DO NOTHING;
                                                                                                                                                                                                  END IF;
                                                                                                                                                                                                  END;
                                                                                                                                                                                                  $$;


