CREATE OR REPLACE FUNCTION "public"."lock_wallet_funds"("p_wallet" "uuid", "p_amount" numeric, "p_name" "text", "p_lock_until" timestamp with time zone) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

vault_id uuid;
wallet_account uuid;

begin

insert into wallet_vaults(
user_id,
wallet_id,
vault_name,
amount,
lock_until
)

values(
auth.uid(),
p_wallet,
p_name,
p_amount,
p_lock_until
)

returning id into vault_id;


select id into wallet_account
from ledger_accounts
where wallet_id = p_wallet
limit 1;


insert into ledger_transactions(reference,transaction_type)

values(gen_random_uuid()::text,'vault_lock');

insert into ledger_entries(transaction_id,account_id,entry_type,amount)

values
(
currval('ledger_transactions_id_seq'),
wallet_account,
'debit',
p_amount
);


return vault_id;

end;

$$;


