CREATE OR REPLACE FUNCTION "public"."lock_wallet_investment"("p_user" "uuid", "p_pool" "uuid", "p_amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                                                                    DECLARE
                                                                      v_wallet uuid;
                                                                        v_lock_days integer;
                                                                          v_unlock timestamptz;
                                                                            v_position uuid;
                                                                            BEGIN

                                                                              SELECT id INTO v_wallet
                                                                                FROM public.wallet
                                                                                  WHERE user_id = p_user;

                                                                                    IF v_wallet IS NULL THEN
                                                                                        RAISE EXCEPTION 'Wallet not found';
                                                                                          END IF;

                                                                                            SELECT lock_days INTO v_lock_days
                                                                                              FROM public.investment_pools
                                                                                                WHERE id = p_pool;

                                                                                                  v_unlock := now() + (v_lock_days || ' days')::interval;

                                                                                                    INSERT INTO public.investment_positions(
                                                                                                        user_id,
                                                                                                            wallet_id,
                                                                                                                pool_id,
                                                                                                                    amount,
                                                                                                                        unlock_date
                                                                                                                          )
                                                                                                                            VALUES(
                                                                                                                                p_user,
                                                                                                                                    v_wallet,
                                                                                                                                        p_pool,
                                                                                                                                            p_amount,
                                                                                                                                                v_unlock
                                                                                                                                                  )
                                                                                                                                                    RETURNING id INTO v_position;

                                                                                                                                                      INSERT INTO public.wallet_transactions(
                                                                                                                                                          user_id,
                                                                                                                                                              amount,
                                                                                                                                                                  type
                                                                                                                                                                    )
                                                                                                                                                                      VALUES(
                                                                                                                                                                          p_user,
                                                                                                                                                                              -p_amount,
                                                                                                                                                                                  'investment_lock'
                                                                                                                                                                                    );

                                                                                                                                                                                      INSERT INTO public.investment_transactions(
                                                                                                                                                                                          position_id,
                                                                                                                                                                                              user_id,
                                                                                                                                                                                                  amount,
                                                                                                                                                                                                      type
                                                                                                                                                                                                        )
                                                                                                                                                                                                          VALUES(
                                                                                                                                                                                                              v_position,
                                                                                                                                                                                                                  p_user,
                                                                                                                                                                                                                      p_amount,
                                                                                                                                                                                                                          'deposit'
                                                                                                                                                                                                                            );

                                                                                                                                                                                                                              RETURN v_position;

                                                                                                                                                                                                                              END;
                                                                                                                                                                                                                              $$;


ALTER FUNCTION "public"."lock_wallet_investment"("p_user" "uuid", "p_pool" "uuid", "p_amount" numeric) OWNER TO "postgres";


