CREATE OR REPLACE FUNCTION "public"."log_transaction_change"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    INSERT INTO public.civic_ai_audit_log (
      action_type, entity_type, entity_id, previous_state, new_state, change_summary, created_at
    ) VALUES (
      CASE 
        WHEN NEW.status = 'ai_hold' AND OLD.status != 'ai_hold' THEN 'transaction_held'
        WHEN NEW.status = 'rejected' AND OLD.status != 'rejected' THEN 'transaction_rejected'
        WHEN NEW.presidential_override = true AND OLD.presidential_override = false THEN 'presidential_override'
        ELSE 'transaction_scored'
      END,
      'transaction', NEW.id, to_jsonb(OLD), to_jsonb(NEW),
      format('Transaction %s changed from %s to %s', NEW.transaction_code, OLD.status, NEW.status)
    );
  END IF;
  RETURN NEW;
END;
$$;


