CREATE OR REPLACE FUNCTION "public"."match_carpool_routes"("lat_input" numeric, "lng_input" numeric) RETURNS TABLE("trip_id" "uuid", "distance" numeric)
    LANGUAGE "sql"
    AS $$
          select
            ct.id,
              calculate_distance_km(lat_input, lng_input,
                  (ct.origin->>'lat')::numeric,
                      (ct.origin->>'lng')::numeric
                        ) as distance
                        from carpool_trips ct
                        where ct.status = 'open'
                        order by distance asc
                        limit 10;
                        $$;


ALTER FUNCTION "public"."match_carpool_routes"("lat_input" numeric, "lng_input" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_carpool_routes"("lat_input" numeric, "lng_input" numeric, "time_input" timestamp without time zone) RETURNS TABLE("trip_id" "uuid", "distance" numeric)
    LANGUAGE "sql"
    AS $$
            select
              ct.id,
                calculate_distance_km(
                    lat_input,
                        lng_input,
                            (ct.origin->>'lat')::numeric,
                                (ct.origin->>'lng')::numeric
                                  ) as distance
                                  from carpool_trips ct
                                  where ct.status = 'open'
                                  and abs(extract(epoch from (ct.departure_time - time_input))) < 1800
                                  order by distance asc
                                  limit 10;
                                  $$;


