    LANGUAGE "plpgsql"
    AS $$
BEGIN
  INSERT INTO job_matches (job_id, user_id, match_score)
  SELECT j.id, u.user_id, random() * 100
  FROM jobs j, user_professional_profiles u;
END;
$$;


