CREATE OR REPLACE FUNCTION "public"."match_jobs_ai"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  job RECORD;
  candidate RECORD;
  score NUMERIC;
BEGIN
  FOR job IN SELECT * FROM jobs WHERE status = 'open' LOOP

    FOR candidate IN SELECT * FROM job_candidates WHERE job_id = job.id LOOP

      -- SIMPLE AI SCORING ENGINE (EXTENDABLE)
      SELECT 
        CASE 
          WHEN candidate.skills && job.skills THEN 80
          ELSE 40
        END INTO score;

      UPDATE job_candidates
      SET match_score = score
      WHERE id = candidate.id;

    END LOOP;

  END LOOP;
END;
$$;


ALTER FUNCTION "public"."match_jobs_ai"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."match_jobs_for_user"("p_user_id" "uuid", "p_limit" integer DEFAULT 10) RETURNS TABLE("job_id" "uuid", "title" "text", "match_score" numeric, "required_skills" "text"[], "user_skills" "text"[])
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  WITH user_skills_list AS (
    SELECT array_agg(skill) as skills
    FROM public.worker_skills
    WHERE user_id = p_user_id
  ),
  job_matches AS (
    SELECT 
      j.id,
      j.title,
      j.skills_required,
      us.skills as user_skills,
      CASE 
        WHEN j.skills_required && us.skills THEN
          (array_length(array(select unnest(j.skills_required) intersect select unnest(us.skills)), 1)::numeric / 
           GREATEST(array_length(j.skills_required, 1), 1)::numeric) * 100
        ELSE 0
      END as score
    FROM public.jobs j
    CROSS JOIN user_skills_list us
    WHERE j.status = 'open'
  )
  SELECT 
    job_matches.id,
    job_matches.title,
    round(job_matches.score, 2),
    job_matches.skills_required,
    job_matches.user_skills
  FROM job_matches
  WHERE job_matches.score > 0
  ORDER BY job_matches.score DESC
  LIMIT p_limit;
END;
$$;


ALTER FUNCTION "public"."match_jobs_for_user"("p_user_id" "uuid", "p_limit" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_accept_ride"("p_ride_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                            begin
                              if auth.uid() is null then
                                  raise exception 'Auth required';
                                    end if;

                                      if not public.mtaa_has_verified_vehicle() then
                                          raise exception 'Vehicle verification required to accept rides';
                                            end if;

                                              update public.rides
                                                set driver_id = auth.uid(),
                                                      status = 'accepted',
                                                            updated_at = now()
                                                              where id = p_ride_id
                                                                  and (driver_id is null)
                                                                      and status in ('requested','pending');

                                                                        if not found then
                                                                            raise exception 'Ride not available';
                                                                              end if;
                                                                              end;
                                                                              $$;


