CREATE OR REPLACE FUNCTION "public"."mtaa_accept_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract accepted'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        begin
          update public.service_contracts
            set
                status = case
                      when escrow_account_id is not null then 'pending_funding'
                            else 'active'
                                end,
                                    metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                                        updated_at = now()
                                          where id = p_contract_id;

                                            perform public.mtaa_add_service_contract_event(
                                                p_contract_id,
                                                    'contract_accepted',
                                                        p_actor_user_id,
                                                            p_note,
                                                                coalesce(p_metadata, '{}'::jsonb)
                                                                  );

                                                                    return p_contract_id;
                                                                    end;
                                                                    $$;


ALTER FUNCTION "public"."mtaa_accept_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_accept_truck_order"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                        begin
                                                          if auth.uid() is null then
                                                              raise exception 'Auth required';
                                                                end if;

                                                                  if not public.mtaa_has_verified_truck_vehicle() then
                                                                      raise exception 'Truck vehicle verification required to accept truck orders';
                                                                        end if;

                                                                          update public.truck_orders
                                                                            set driver_id = auth.uid(),
                                                                                  status = 'accepted',
                                                                                        updated_at = now()
                                                                                          where id = p_order_id
                                                                                              and (driver_id is null)
                                                                                                  and status in ('requested');

                                                                                                    if not found then
                                                                                                        raise exception 'Order not available';
