CREATE OR REPLACE FUNCTION "public"."mtaa_add_wallet_transaction"("p_user_id" "uuid", "p_amount" numeric, "p_transaction_type" "text", "p_currency" "text" DEFAULT 'KES'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_wallet_id uuid;
  v_current_balance numeric(18,2);
  v_new_balance numeric(18,2);
  v_tx_id uuid;
begin
  -- current schema uses wallets.owner_id, not wallets.user_id
  select id, balance
  into v_wallet_id, v_current_balance
  from public.wallets
  where owner_id = p_user_id
  limit 1;

  if v_wallet_id is null then
    insert into public.wallets (owner_id, currency, balance)
    values (p_user_id, p_currency, 0)
    returning id, balance into v_wallet_id, v_current_balance;
  end if;

  v_new_balance := coalesce(v_current_balance, 0) + p_amount;

  -- current schema wallet_transactions only supports:
  -- id, user_id, amount, type, created_at
  insert into public.wallet_transactions (
    user_id,
    amount,
    type,
    created_at
  ) values (
    p_user_id,
    p_amount,
    p_transaction_type,
    now()
  )
  returning id into v_tx_id;

  update public.wallets
  set balance = v_new_balance,
      updated_at = now()
  where id = v_wallet_id;

  perform public.mtaa_emit_event(
    p_user_id,
    'WALLET_' || upper(coalesce(p_transaction_type, 'UNKNOWN')),
    'wallet',
    'wallet_transactions',
    v_tx_id,
    p_amount,
    p_currency,
    coalesce(p_metadata, '{}'::jsonb)
  );

  return v_tx_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_add_wallet_transaction"("p_user_id" "uuid", "p_amount" numeric, "p_transaction_type" "text", "p_currency" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_add_wallet_transaction"("p_user_id" "uuid", "p_amount" numeric, "p_transaction_type" "text", "p_status" "text" DEFAULT 'completed'::"text", "p_currency" "text" DEFAULT 'KES'::"text", "p_description" "text" DEFAULT NULL::"text", "p_reference_type" "text" DEFAULT NULL::"text", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_provider" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_wallet_id uuid;
  v_current_balance numeric(18,2);
  v_new_balance numeric(18,2);
  v_tx_id uuid;
begin
  select id, balance
  into v_wallet_id, v_current_balance
  from public.wallets
  where owner_id = p_user_id
  limit 1;

  if v_wallet_id is null then
    insert into public.wallets (
      owner_id,
      currency,
      balance,
      updated_at
    )
    values (
      p_user_id,
      p_currency,
      0,
      now()
    )
    returning id, balance into v_wallet_id, v_current_balance;
  end if;

  v_new_balance := coalesce(v_current_balance, 0) + p_amount;

  insert into public.wallet_transactions (
    wallet_id,
    user_id,
    profile_id,
    amount,
    type,
    transaction_type,
    status,
    currency,
    description,
    reference_type,
    reference_id,
    provider,
    metadata,
    balance_after,
    created_at,
    completed_at,
    updated_at
  ) values (
    v_wallet_id,
    p_user_id,
    p_user_id,
    p_amount,
    p_transaction_type,
    p_transaction_type,
    p_status,
    p_currency,
    p_description,
    p_reference_type,
    p_reference_id,
    p_provider,
    coalesce(p_metadata, '{}'::jsonb),
    case
      when p_status = 'completed' then v_new_balance
      else coalesce(v_current_balance, 0)
    end,
    now(),
    case when p_status = 'completed' then now() else null end,
    now()
  )
  returning id into v_tx_id;

  if p_status = 'completed' then
    update public.wallets
    set balance = v_new_balance,
        currency = p_currency,
        updated_at = now()
    where id = v_wallet_id;
  end if;

  perform public.mtaa_emit_event(
    p_user_id,
    'WALLET_' || upper(coalesce(p_transaction_type, 'UNKNOWN')) || '_' || upper(coalesce(p_status, 'UNKNOWN')),
    'wallet',
    'wallet_transactions',
    v_tx_id,
    p_amount,
    p_currency,
    jsonb_build_object(
      'provider', p_provider,
      'description', p_description,
      'reference_type', p_reference_type,
      'reference_id', p_reference_id
    ) || coalesce(p_metadata, '{}'::jsonb)
  );

  return v_tx_id;
end;
$$;


