CREATE OR REPLACE FUNCTION "public"."mtaa_apply_post_tags"("p_post_id" "uuid", "p_tags" "text"[], "p_confidence" numeric DEFAULT 0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
      declare
        v_user_id uuid;
          v_clean text[];
          begin
            select user_id into v_user_id from public.posts where id = p_post_id;
              if v_user_id is null then
                  raise exception 'Post not found or has no user_id';
                    end if;

                      -- ownership check
                        if auth.uid() is distinct from v_user_id then
                            raise exception 'Not allowed';
                              end if;

                                -- normalize tags: lowercase, strip '#', trim, remove empties, unique
                                  select coalesce(array_agg(distinct t), '{}') into v_clean
                                    from (
                                        select nullif(trim(both ' ' from regexp_replace(lower(x), '^#', '')), '') as t
                                            from unnest(coalesce(p_tags, '{}'::text[])) as x
                                              ) s
                                                where t is not null;

                                                  -- upsert into hashtags table
                                                    insert into public.hashtags(tag)
                                                      select t from unnest(v_clean) as t
                                                        on conflict (tag) do nothing;

                                                          -- replace mappings (keep it deterministic)
                                                            delete from public.post_tags where post_id = p_post_id;

                                                              insert into public.post_tags(post_id, tag, confidence)
                                                                select p_post_id, t, coalesce(p_confidence, 0)
                                                                  from unnest(v_clean) as t;

                                                                    -- update cached hashtags array on posts (your schema has posts.hashtags)
                                                                      update public.posts
                                                                        set hashtags = v_clean
                                                                          where id = p_post_id;
                                                                          end;
                                                                          $$;


ALTER FUNCTION "public"."mtaa_apply_post_tags"("p_post_id" "uuid", "p_tags" "text"[], "p_confidence" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_assign_task"("p_task" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
    declare
      v_worker uuid;
      begin

        select user_id
          into v_worker
            from public.mtaxi_driver_status
              where online=true
                order by random()
                  limit 1;

                    update public.mtaa_tasks
                      set assigned_worker=v_worker,
                            status='assigned'
                              where id=p_task;

                                return v_worker;

                                end;
                                $$;


ALTER FUNCTION "public"."mtaa_assign_task"("p_task" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_attach_contract_escrow_account"("p_contract_id" "uuid", "p_escrow_account_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        begin
          update public.service_contracts
            set
                escrow_account_id = p_escrow_account_id,
                    status = case when status = 'draft' then 'pending_funding' else status end,
                        metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                            updated_at = now()
                              where id = p_contract_id;

                                perform public.mtaa_add_service_contract_event(
                                    p_contract_id,
                                        'contract_updated',
                                            p_actor_user_id,
                                                'Escrow account attached to contract',
                                                    jsonb_build_object(
                                                          'escrow_account_id', p_escrow_account_id
                                                              ) || coalesce(p_metadata, '{}'::jsonb)
                                                                );

                                                                  return p_contract_id;
                                                                  end;
                                                                  $$;


ALTER FUNCTION "public"."mtaa_attach_contract_escrow_account"("p_contract_id" "uuid", "p_escrow_account_id" "uuid", "p_actor_user_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_attach_skill_to_work_profile"("p_work_profile_id" "uuid", "p_skill_id" "uuid", "p_proficiency_level" "text" DEFAULT 'intermediate'::"text", "p_years_used" integer DEFAULT 0, "p_is_primary" boolean DEFAULT false, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                        begin
                                                                                          insert into public.work_profile_skills (
                                                                                              work_profile_id,
                                                                                                  skill_id,
                                                                                                      proficiency_level,
                                                                                                          years_used,
                                                                                                              is_primary,
                                                                                                                  metadata
                                                                                                                    ) values (
                                                                                                                        p_work_profile_id,
                                                                                                                            p_skill_id,
                                                                                                                                p_proficiency_level,
                                                                                                                                    greatest(coalesce(p_years_used, 0), 0),
                                                                                                                                        coalesce(p_is_primary, false),
                                                                                                                                            coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                              )
                                                                                                                                                on conflict (work_profile_id, skill_id)
                                                                                                                                                  do update set
                                                                                                                                                      proficiency_level = excluded.proficiency_level,
                                                                                                                                                          years_used = excluded.years_used,
                                                                                                                                                              is_primary = excluded.is_primary,
                                                                                                                                                                  metadata = public.work_profile_skills.metadata || excluded.metadata;

                                                                                                                                                                    return p_work_profile_id;
                                                                                                                                                                    end;
                                                                                                                                                                    $$;


ALTER FUNCTION "public"."mtaa_attach_skill_to_work_profile"("p_work_profile_id" "uuid", "p_skill_id" "uuid", "p_proficiency_level" "text", "p_years_used" integer, "p_is_primary" boolean, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_attach_track_to_content"("p_content_id" "uuid", "p_track_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                              begin
                                                                                                                                                                perform public.mtaa_ensure_music_stats(p_track_id);

                                                                                                                                                                  insert into public.content_music_usage(content_id, track_id)
                                                                                                                                                                    values (p_content_id, p_track_id)
                                                                                                                                                                      on conflict (content_id, track_id) do nothing;

                                                                                                                                                                        update public.music_stats
                                                                                                                                                                            set plays = coalesce(plays,0) + 1
                                                                                                                                                                              where track_id = p_track_id;
                                                                                                                                                                              end $$;


ALTER FUNCTION "public"."mtaa_attach_track_to_content"("p_content_id" "uuid", "p_track_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_attach_track_to_post"("p_post_id" "uuid", "p_track_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
                          BEGIN
                            PERFORM public.mtaa_ensure_post_stats(p_post_id);
                              PERFORM public.mtaa_ensure_music_stats(p_track_id);

                                INSERT INTO public.content_music_usage(content_id, track_id)
                                  VALUES (p_post_id, p_track_id)
                                    ON CONFLICT (content_id, track_id) DO NOTHING;
                                    END;
                                    $$;


ALTER FUNCTION "public"."mtaa_attach_track_to_post"("p_post_id" "uuid", "p_track_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_bill_ad_impression"("p_impression_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Ad impression billed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_campaign_id uuid;
  v_viewer_user_id uuid;
  v_creator_user_id uuid;
  v_cost numeric(18,4);
  v_cost_2 numeric(18,2);
  v_currency text;
  v_advertiser_user_id uuid;
  v_reserved_amount numeric(18,2);
  v_creator_share_rate numeric(8,4);
  v_creator_share numeric(18,2);
  v_wallet_tx_id uuid;
  v_creator_earning_id uuid;
begin
  select
    ai.campaign_id,
    ai.viewer_user_id,
    ai.creator_user_id,
    ai.cost,
    c.currency,
    c.advertiser_user_id,
    c.reserved_amount,
    c.creator_share_rate
  into
    v_campaign_id,
    v_viewer_user_id,
    v_creator_user_id,
    v_cost,
    v_currency,
    v_advertiser_user_id,
    v_reserved_amount,
    v_creator_share_rate
  from public.ad_impressions_v2 ai
  join public.ad_campaigns c on c.id = ai.campaign_id
  where ai.id = p_impression_id
    and coalesce(ai.billed, false) = false
  limit 1;

  if v_campaign_id is null then
    raise exception 'Impression not found or already billed';
  end if;

  v_cost_2 := round(coalesce(v_cost,0)::numeric,2);

  if v_cost_2 <= 0 then
    raise exception 'Impression cost must be greater than zero';
  end if;

  if coalesce(v_reserved_amount,0) < v_cost_2 then
    update public.ad_campaigns
    set billing_status='depleted',
        status=case when status='active' then 'paused' else status end,
        paused_at=now(),
        stopped_reason='Insufficient reserved budget',
        updated_at=now()
    where id=v_campaign_id;

    raise exception 'Insufficient reserved campaign budget';
  end if;

  update public.ad_campaigns
  set
    amount_spent = coalesce(amount_spent,0) + v_cost_2,
    reserved_amount = coalesce(reserved_amount,0) - v_cost_2,
    last_billed_at = now(),
    updated_at = now()
  where id = v_campaign_id;

  v_wallet_tx_id := public.mtaa_add_wallet_transaction(
    v_advertiser_user_id,
    0,
    'ad_spend',
    'completed',
    v_currency,
    'Ad impression billed',
    'ad_impression',
    p_impression_id,
    'internal',
    jsonb_build_object(
      'campaign_id', v_campaign_id,
      'cost', v_cost_2
    ) || coalesce(p_metadata,'{}'::jsonb)
  );

  v_creator_share := round((v_cost_2 * coalesce(v_creator_share_rate,0))::numeric,2);

  if v_creator_user_id is not null and v_creator_share > 0 then
    v_creator_earning_id := public.mtaa_credit_creator_earning(
      v_creator_user_id,
      v_creator_share,
      0,
      'ad_revenue',
      'advertise',
      'ad_impressions_v2',
      p_impression_id,
      v_currency,
      jsonb_build_object(
        'campaign_id', v_campaign_id,
        'viewer_user_id', v_viewer_user_id
      ) || coalesce(p_metadata,'{}'::jsonb)
    );
  end if;

  update public.ad_impressions_v2
  set billed=true,
      billed_at=now(),
      advertiser_wallet_transaction_id=v_wallet_tx_id,
      creator_earning_id=v_creator_earning_id
  where id=p_impression_id;

  return p_impression_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_bill_ad_impression"("p_impression_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_buy_product"("p_product_id" "uuid") RETURNS json
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        DECLARE
          v_product RECORD;
            v_wallet RECORD;
            BEGIN

              SELECT * INTO v_product
                FROM public.shop_items
                  WHERE id = p_product_id
                    FOR UPDATE;

                      IF v_product.available = false THEN
                          RAISE EXCEPTION 'Product unavailable';
                            END IF;

                              SELECT * INTO v_wallet
                                FROM public.wallets
                                  WHERE owner_id = auth.uid();

                                    IF v_wallet.balance < v_product.price THEN
                                        RAISE EXCEPTION 'Insufficient balance';
                                          END IF;

                                            INSERT INTO public.escrow_accounts(
                                                employer_id,
                                                    worker_id,
                                                        amount,
                                                            status,
                                                                meta
                                                                  )
                                                                    VALUES (
                                                                        auth.uid(),
                                                                            v_product.user_id,
                                                                                v_product.price,
                                                                                    'funded',
                                                                                        jsonb_build_object(
                                                                                              'type','shop_purchase',
                                                                                                    'product_id',v_product.id
                                                                                                        )
                                                                                                          );

                                                                                                            UPDATE public.shop_items
                                                                                                              SET available = false
                                                                                                                WHERE id = v_product.id;

                                                                                                                  RETURN json_build_object(
                                                                                                                      'success', true,
                                                                                                                          'product', v_product.id
                                                                                                                            );

                                                                                                                            END;
                                                                                                                            $$;


ALTER FUNCTION "public"."mtaa_buy_product"("p_product_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_cancel_cash_point_transaction"("p_transaction_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
begin
  update public.cash_point_transactions
  set status='cancelled',
      cancelled_at=now(),
      updated_at=now()
  where id=p_transaction_id;

  return p_transaction_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_cancel_cash_point_transaction"("p_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_cancel_deposit"("p_deposit_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text" DEFAULT 'Deposit cancelled'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_amount numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        update public.wallet_deposits
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          set status = 'cancelled',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                cancelled_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      cancelled_by = p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            failure_reason = coalesce(failure_reason, 'Cancelled by user'),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    where id = p_deposit_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        and user_id = p_actor_user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            and status in ('requested','pending')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              returning user_id, currency, amount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                into v_user_id, v_currency, v_amount;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      raise exception 'Deposit not found, not cancelable, or not owned by actor';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          perform public.mtaa_add_deposit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'cancelled',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'WALLET_DEPOSIT_CANCELLED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'wallet_deposits',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return p_deposit_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $$;


ALTER FUNCTION "public"."mtaa_cancel_deposit"("p_deposit_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_cancel_escrow_account"("p_escrow_account_id" "uuid", "p_employer_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Escrow cancelled'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
          declare
            v_employer_id uuid;
              v_worker_id uuid;
                v_currency text;
                  v_refund_amount numeric(18,2);
                  begin
                    select
                        ea.employer_id,
                            ea.worker_id,
                                ea.currency,
                                    coalesce(sum(em.amount), 0)
                                      into
                                          v_employer_id,
                                              v_worker_id,
                                                  v_currency,
                                                      v_refund_amount
                                                        from public.escrow_accounts ea
                                                          left join public.escrow_milestones em
                                                              on em.escrow_account_id = ea.id
                                                                 and em.status in ('locked', 'submitted', 'disputed', 'pending')
                                                                   where ea.id = p_escrow_account_id
                                                                     group by ea.id, ea.employer_id, ea.worker_id, ea.currency
                                                                       limit 1;

                                                                         if v_employer_id is null then
                                                                             raise exception 'Escrow account not found';
                                                                               end if;

                                                                                 update public.escrow_milestones
                                                                                   set
                                                                                       status = case
                                                                                             when status = 'released' then status
                                                                                                   else 'cancelled'
                                                                                                       end,
                                                                                                           cancelled_at = case
                                                                                                                 when status = 'released' then cancelled_at
                                                                                                                       else now()
                                                                                                                           end,
                                                                                                                               updated_at = now(),
                                                                                                                                   metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                     where escrow_account_id = p_escrow_account_id
                                                                                                                                         and status <> 'released';

                                                                                                                                           update public.escrow_accounts
                                                                                                                                             set
                                                                                                                                                 status = 'cancelled',
                                                                                                                                                     cancelled_at = now(),
                                                                                                                                                         refunded_amount = coalesce(refunded_amount, 0) + coalesce(v_refund_amount, 0),
                                                                                                                                                             updated_at = now()
                                                                                                                                                               where id = p_escrow_account_id;

                                                                                                                                                                 if coalesce(v_refund_amount, 0) > 0 then
                                                                                                                                                                     insert into public.escrow_transactions (
                                                                                                                                                                           escrow_account_id,
                                                                                                                                                                                 milestone_id,
                                                                                                                                                                                       employer_id,
                                                                                                                                                                                             worker_id,
                                                                                                                                                                                                   wallet_transaction_id,
                                                                                                                                                                                                         transaction_type,
                                                                                                                                                                                                               status,
                                                                                                                                                                                                                     amount,
                                                                                                                                                                                                                           currency,
                                                                                                                                                                                                                                 note,
                                                                                                                                                                                                                                       metadata
                                                                                                                                                                                                                                           ) values (
                                                                                                                                                                                                                                                 p_escrow_account_id,
                                                                                                                                                                                                                                                       null,
                                                                                                                                                                                                                                                             v_employer_id,
                                                                                                                                                                                                                                                                   v_worker_id,
                                                                                                                                                                                                                                                                         p_employer_wallet_transaction_id,
                                                                                                                                                                                                                                                                               'refund',
                                                                                                                                                                                                                                                                                     'completed',
                                                                                                                                                                                                                                                                                           coalesce(v_refund_amount, 0),
                                                                                                                                                                                                                                                                                                 v_currency,
                                                                                                                                                                                                                                                                                                       'Escrow cancellation refund',
                                                                                                                                                                                                                                                                                                             jsonb_build_object(
                                                                                                                                                                                                                                                                                                                     'refund_target', 'employer'
                                                                                                                                                                                                                                                                                                                           ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                               );
                                                                                                                                                                                                                                                                                                                                 end if;

                                                                                                                                                                                                                                                                                                                                   perform public.mtaa_add_escrow_event(
                                                                                                                                                                                                                                                                                                                                       p_escrow_account_id,
                                                                                                                                                                                                                                                                                                                                           'escrow_cancelled',
                                                                                                                                                                                                                                                                                                                                               p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                   null,
                                                                                                                                                                                                                                                                                                                                                       p_note,
                                                                                                                                                                                                                                                                                                                                                           jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                 'refund_amount', coalesce(v_refund_amount, 0),
                                                                                                                                                                                                                                                                                                                                                                       'wallet_transaction_id', p_employer_wallet_transaction_id
                                                                                                                                                                                                                                                                                                                                                                           ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                             );

                                                                                                                                                                                                                                                                                                                                                                               return p_escrow_account_id;
                                                                                                                                                                                                                                                                                                                                                                               end;
                                                                                                                                                                                                                                                                                                                                                                               $$;


ALTER FUNCTION "public"."mtaa_cancel_escrow_account"("p_escrow_account_id" "uuid", "p_employer_wallet_transaction_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_cancel_escrow_account_and_refresh"("p_escrow_account_id" "uuid", "p_employer_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Escrow cancelled'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                        begin
                                                                                                          perform public.mtaa_cancel_escrow_account(
                                                                                                              p_escrow_account_id,
                                                                                                                  p_employer_wallet_transaction_id,
                                                                                                                      p_actor_user_id,
                                                                                                                          p_note,
                                                                                                                              p_metadata
                                                                                                                                );

                                                                                                                                  perform public.mtaa_refresh_escrow_account_status(p_escrow_account_id);

                                                                                                                                    return p_escrow_account_id;
                                                                                                                                    end;
                                                                                                                                    $$;


ALTER FUNCTION "public"."mtaa_cancel_escrow_account_and_refresh"("p_escrow_account_id" "uuid", "p_employer_wallet_transaction_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_cancel_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text" DEFAULT 'Payout cancelled'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_amount numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_channel_fee numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_platform_fee numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_total_restore numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_restore_tx uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                update public.wallet_payouts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  set status = 'cancelled',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        cancelled_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              cancelled_by = p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    failure_reason = coalesce(failure_reason, 'Cancelled by user')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      where id = p_payout_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          and user_id = p_actor_user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              and status in ('requested','queued')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                returning user_id, currency, amount, channel_fee, platform_fee
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  into v_user_id, v_currency, v_amount, v_channel_fee, v_platform_fee;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        raise exception 'Payout not found, not cancelable, or not owned by actor';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_total_restore := coalesce(v_amount, 0) + coalesce(v_channel_fee, 0) + coalesce(v_platform_fee, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_restore_tx := public.mtaa_add_wallet_transaction(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_total_restore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'payout_reversal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'Payout cancellation reversal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'wallet_payout',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'internal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'restored_amount', v_total_restore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'stage', 'cancelled'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          perform public.mtaa_add_payout_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'cancelled',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'restore_transaction_id', v_restore_tx,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'restored_amount', v_total_restore
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'WALLET_PAYOUT_CANCELLED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'wallet_payouts',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'restore_transaction_id', v_restore_tx,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'restored_amount', v_total_restore
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      return p_payout_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $$;


ALTER FUNCTION "public"."mtaa_cancel_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_cancel_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract cancelled'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                            begin
                                                              update public.service_contracts
                                                                set
                                                                    status = 'cancelled',
                                                                        metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                                                                            updated_at = now()
                                                                              where id = p_contract_id;

                                                                                perform public.mtaa_add_service_contract_event(
                                                                                    p_contract_id,
                                                                                        'contract_cancelled',
                                                                                            p_actor_user_id,
                                                                                                p_note,
                                                                                                    coalesce(p_metadata, '{}'::jsonb)
                                                                                                      );

                                                                                                        return p_contract_id;
                                                                                                        end;
                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_cancel_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_cancel_truck_order"("p_order_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                                                                                                                                                                                                declare v_user uuid;
                                                                                                                                                                                                                                                                                declare v_status text;
                                                                                                                                                                                                                                                                                begin
                                                                                                                                                                                                                                                                                  if auth.uid() is null then raise exception 'Auth required'; end if;

                                                                                                                                                                                                                                                                                    select user_id, status into v_user, v_status
                                                                                                                                                                                                                                                                                      from public.truck_orders
                                                                                                                                                                                                                                                                                        where id = p_order_id
                                                                                                                                                                                                                                                                                          for update;

                                                                                                                                                                                                                                                                                            if v_user is null then raise exception 'Order not found'; end if;
                                                                                                                                                                                                                                                                                              if v_user <> auth.uid() then raise exception 'Only the customer can cancel'; end if;
                                                                                                                                                                                                                                                                                                if v_status in ('completed','cancelled') then raise exception 'Order already closed'; end if;

                                                                                                                                                                                                                                                                                                  update public.truck_orders
                                                                                                                                                                                                                                                                                                    set status='cancelled', updated_at=now()
                                                                                                                                                                                                                                                                                                      where id = p_order_id;
                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                      $$;


ALTER FUNCTION "public"."mtaa_cancel_truck_order"("p_order_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_claim_carpool"("p_driver_vehicle_id" "uuid", "p_selected_request_ids" "uuid"[], "p_total_fare" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                                                                                                                                  declare
                                                                                                                                                                                                                    v_ride_id uuid;
                                                                                                                                                                                                                    begin
                                                                                                                                                                                                                      if p_total_fare is null or p_total_fare <= 0 then
                                                                                                                                                                                                                          raise exception 'Invalid total fare';
                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                              insert into public.carpool_rides (id, driver_vehicle_id, departure_time, total_fare, status, created_at)
                                                                                                                                                                                                                                values (gen_random_uuid(), p_driver_vehicle_id, now(), p_total_fare, 'active', now())
                                                                                                                                                                                                                                  returning id into v_ride_id;

                                                                                                                                                                                                                                    insert into public.carpool_ride_passengers (id, carpool_ride_id, carpool_request_id, assigned_pickup_lat, assigned_dropoff_lat, share_fare, joined_at)
                                                                                                                                                                                                                                      select
                                                                                                                                                                                                                                          gen_random_uuid(),
                                                                                                                                                                                                                                              v_ride_id,
                                                                                                                                                                                                                                                  r.id,
                                                                                                                                                                                                                                                      r.origin_lat,
                                                                                                                                                                                                                                                          r.dropoff_lat,
                                                                                                                                                                                                                                                              round(p_total_fare / greatest(array_length(p_selected_request_ids, 1), 1), 2),
                                                                                                                                                                                                                                                                  now()
                                                                                                                                                                                                                                                                    from public.carpool_requests r
                                                                                                                                                                                                                                                                      where r.id = any(p_selected_request_ids)
                                                                                                                                                                                                                                                                          and r.status = 'open';

                                                                                                                                                                                                                                                                            update public.carpool_requests
                                                                                                                                                                                                                                                                                set status = 'pooled'
                                                                                                                                                                                                                                                                                  where id = any(p_selected_request_ids);

                                                                                                                                                                                                                                                                                    return v_ride_id;
                                                                                                                                                                                                                                                                                    end;
                                                                                                                                                                                                                                                                                    $$;


ALTER FUNCTION "public"."mtaa_claim_carpool"("p_driver_vehicle_id" "uuid", "p_selected_request_ids" "uuid"[], "p_total_fare" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_clear_app_badge_count"("p_app_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                          declare
                                                                                                                            v_user_id uuid := auth.uid();
                                                                                                                            begin
                                                                                                                              update public.app_installations
                                                                                                                                set badge_count = 0
                                                                                                                                  where user_id = v_user_id
                                                                                                                                      and app_id = p_app_id;

                                                                                                                                        return true;
                                                                                                                                        end;
                                                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_clear_app_badge_count"("p_app_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_complete_cash_point_transaction"("p_transaction_id" "uuid", "p_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  update public.cash_point_transactions
  set status='completed',
      wallet_transaction_id=coalesce(p_wallet_transaction_id,wallet_transaction_id),
      completed_at=now(),
      updated_at=now()
  where id=p_transaction_id;

  return p_transaction_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_complete_cash_point_transaction"("p_transaction_id" "uuid", "p_wallet_transaction_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_complete_deposit"("p_deposit_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_external_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT 'Deposit completed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_wallet_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_amount numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_provider_name text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_tx_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            update public.wallet_deposits
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              set status = 'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    completed_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          completed_by = coalesce(p_actor_user_id, completed_by),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                external_reference = coalesce(p_external_reference, external_reference),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where id = p_deposit_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            and status in ('requested','pending','processing')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              returning user_id, wallet_id, amount, currency, provider_name
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                into v_user_id, v_wallet_id, v_amount, v_currency, v_provider_name;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      raise exception 'Deposit not found or not completable';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_tx_id := public.mtaa_add_wallet_transaction(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'deposit',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'Wallet deposit completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'wallet_deposit',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_provider_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'stage', 'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'deposit_id', p_deposit_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      update public.wallet_deposits
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        set related_wallet_transaction_id = v_tx_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                where id = p_deposit_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  perform public.mtaa_add_deposit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'wallet_transaction_id', v_tx_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'external_reference', p_external_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'WALLET_DEPOSIT_COMPLETED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'wallet_deposits',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'wallet_transaction_id', v_tx_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'external_reference', p_external_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return p_deposit_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $$;


ALTER FUNCTION "public"."mtaa_complete_deposit"("p_deposit_id" "uuid", "p_actor_user_id" "uuid", "p_external_reference" "text", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_complete_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_external_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT 'Payout completed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_amount numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                update public.wallet_payouts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  set status = 'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        completed_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              approved_at = coalesce(approved_at, now()),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    approved_by = coalesce(approved_by, p_actor_user_id),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          processed_by = coalesce(processed_by, p_actor_user_id),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                external_reference = coalesce(p_external_reference, external_reference)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  where id = p_payout_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      and status in ('requested','queued','processing')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        returning user_id, currency, amount into v_user_id, v_currency, v_amount;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              raise exception 'Payout not found or not completable';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  perform public.mtaa_add_payout_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'external_reference', p_external_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'WALLET_PAYOUT_COMPLETED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'wallet_payouts',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'external_reference', p_external_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return p_payout_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $$;


ALTER FUNCTION "public"."mtaa_complete_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid", "p_external_reference" "text", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_complete_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract completed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        begin
          update public.service_contracts
            set
                status = 'completed',
                    metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                        updated_at = now()
                          where id = p_contract_id;

                            perform public.mtaa_add_service_contract_event(
                                p_contract_id,
                                    'contract_completed',
                                        p_actor_user_id,
                                            p_note,
                                                coalesce(p_metadata, '{}'::jsonb)
                                                  );

                                                    return p_contract_id;
                                                    end;
                                                    $$;


ALTER FUNCTION "public"."mtaa_complete_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_create_cash_point_transaction"("p_cash_point_id" "uuid", "p_agent_user_id" "uuid", "p_transaction_type" "text", "p_amount" numeric, "p_fee_amount" numeric DEFAULT 0, "p_customer_user_id" "uuid" DEFAULT NULL::"uuid", "p_currency" "text" DEFAULT 'KES'::"text", "p_reference_code" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_tx_id uuid;
begin
  insert into public.cash_point_transactions (
    cash_point_id,
    agent_user_id,
    customer_user_id,
    transaction_type,
    status,
    amount,
    fee_amount,
    currency,
    reference_code,
    note,
    metadata
  ) values (
    p_cash_point_id,
    p_agent_user_id,
    p_customer_user_id,
    p_transaction_type,
    'pending',
    round(p_amount::numeric,2),
    round(coalesce(p_fee_amount,0)::numeric,2),
    p_currency,
    p_reference_code,
    p_note,
    coalesce(p_metadata,'{}'::jsonb)
  )
  returning id into v_tx_id;

  return v_tx_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_create_cash_point_transaction"("p_cash_point_id" "uuid", "p_agent_user_id" "uuid", "p_transaction_type" "text", "p_amount" numeric, "p_fee_amount" numeric, "p_customer_user_id" "uuid", "p_currency" "text", "p_reference_code" "text", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_create_service_contract"("p_module_name" "text", "p_employer_id" "uuid", "p_title" "text", "p_contract_amount" numeric, "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_reference_id" "uuid" DEFAULT NULL::"uuid", "p_worker_id" "uuid" DEFAULT NULL::"uuid", "p_description" "text" DEFAULT NULL::"text", "p_currency" "text" DEFAULT 'KES'::"text", "p_starts_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_ends_at" timestamp with time zone DEFAULT NULL::timestamp with time zone, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                        declare
                          v_contract_id uuid;
                          begin
                            if coalesce(p_title, '') = '' then
                                raise exception 'Contract title is required';
                                  end if;

                                    if coalesce(p_contract_amount, 0) < 0 then
                                        raise exception 'Contract amount cannot be negative';
                                          end if;

                                            insert into public.service_contracts (
                                                module_name,
                                                    reference_id,
                                                        employer_id,
                                                            worker_id,
                                                                title,
                                                                    description,
                                                                        contract_amount,
                                                                            currency,
                                                                                status,
                                                                                    starts_at,
                                                                                        ends_at,
                                                                                            metadata
                                                                                              ) values (
                                                                                                  p_module_name,
                                                                                                      p_reference_id,
                                                                                                          p_employer_id,
                                                                                                              p_worker_id,
                                                                                                                  p_title,
                                                                                                                      p_description,
                                                                                                                          round(coalesce(p_contract_amount, 0)::numeric, 2),
                                                                                                                              p_currency,
                                                                                                                                  'draft',
                                                                                                                                      p_starts_at,
                                                                                                                                          p_ends_at,
                                                                                                                                              coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                )
                                                                                                                                                  returning id into v_contract_id;

                                                                                                                                                    insert into public.service_contract_participants (
                                                                                                                                                        contract_id,
                                                                                                                                                            user_id,
                                                                                                                                                                role,
                                                                                                                                                                    is_active,
                                                                                                                                                                        metadata
                                                                                                                                                                          ) values (
                                                                                                                                                                              v_contract_id,
                                                                                                                                                                                  p_employer_id,
                                                                                                                                                                                      'employer',
                                                                                                                                                                                          true,
                                                                                                                                                                                              '{}'::jsonb
                                                                                                                                                                                                )
                                                                                                                                                                                                  on conflict do nothing;

                                                                                                                                                                                                    if p_worker_id is not null then
                                                                                                                                                                                                        insert into public.service_contract_participants (
                                                                                                                                                                                                              contract_id,
                                                                                                                                                                                                                    user_id,
                                                                                                                                                                                                                          role,
                                                                                                                                                                                                                                is_active,
                                                                                                                                                                                                                                      metadata
                                                                                                                                                                                                                                          ) values (
                                                                                                                                                                                                                                                v_contract_id,
                                                                                                                                                                                                                                                      p_worker_id,
                                                                                                                                                                                                                                                            'worker',
                                                                                                                                                                                                                                                                  true,
                                                                                                                                                                                                                                                                        '{}'::jsonb
                                                                                                                                                                                                                                                                            )
                                                                                                                                                                                                                                                                                on conflict do nothing;
                                                                                                                                                                                                                                                                                  end if;

                                                                                                                                                                                                                                                                                    perform public.mtaa_add_service_contract_event(
                                                                                                                                                                                                                                                                                        v_contract_id,
                                                                                                                                                                                                                                                                                            'contract_created',
                                                                                                                                                                                                                                                                                                coalesce(p_actor_user_id, p_employer_id),
                                                                                                                                                                                                                                                                                                    'Service contract created',
                                                                                                                                                                                                                                                                                                        jsonb_build_object(
                                                                                                                                                                                                                                                                                                              'module_name', p_module_name,
                                                                                                                                                                                                                                                                                                                    'contract_amount', round(coalesce(p_contract_amount, 0)::numeric, 2),
                                                                                                                                                                                                                                                                                                                          'currency', p_currency
                                                                                                                                                                                                                                                                                                                              ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                  return v_contract_id;
                                                                                                                                                                                                                                                                                                                                  end;
                                                                                                                                                                                                                                                                                                                                  $$;


ALTER FUNCTION "public"."mtaa_create_service_contract"("p_module_name" "text", "p_employer_id" "uuid", "p_title" "text", "p_contract_amount" numeric, "p_actor_user_id" "uuid", "p_reference_id" "uuid", "p_worker_id" "uuid", "p_description" "text", "p_currency" "text", "p_starts_at" timestamp with time zone, "p_ends_at" timestamp with time zone, "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_create_transfer"("p_sender_user_id" "uuid", "p_receiver_user_id" "uuid", "p_amount" numeric, "p_currency" "text" DEFAULT 'KES'::"text", "p_note" "text" DEFAULT NULL::"text", "p_channel" "text" DEFAULT 'wallet'::"text", "p_transfer_ref" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_sender_wallet_id uuid;
  v_receiver_wallet_id uuid;
  v_transfer_id uuid;
  v_sender_tx uuid;
  v_receiver_tx uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'Transfer amount must be greater than zero';
  end if;

  if p_sender_user_id = p_receiver_user_id then
    raise exception 'Sender and receiver cannot be the same';
  end if;

  if p_channel not in ('wallet','scan_pay','cash_point','internal') then
    raise exception 'Unsupported transfer channel: %', p_channel;
  end if;

  v_sender_wallet_id := public.mtaa_get_or_create_wallet(p_sender_user_id, p_currency);
  v_receiver_wallet_id := public.mtaa_get_or_create_wallet(p_receiver_user_id, p_currency);

  v_sender_tx := public.mtaa_add_wallet_transaction(
    p_sender_user_id, -p_amount, 'transfer_out', 'completed', p_currency,
    coalesce(p_note, 'Wallet transfer sent'), 'wallet_transfer', null, 'internal',
    jsonb_build_object('receiver_user_id', p_receiver_user_id, 'channel', p_channel, 'transfer_ref', p_transfer_ref, 'stage', 'completed') || coalesce(p_metadata, '{}'::jsonb)
  );

  v_receiver_tx := public.mtaa_add_wallet_transaction(
    p_receiver_user_id, p_amount, 'transfer_in', 'completed', p_currency,
    coalesce(p_note, 'Wallet transfer received'), 'wallet_transfer', null, 'internal',
    jsonb_build_object('sender_user_id', p_sender_user_id, 'channel', p_channel, 'transfer_ref', p_transfer_ref, 'stage', 'completed') || coalesce(p_metadata, '{}'::jsonb)
  );

  insert into public.wallet_transfers (
    sender_user_id, receiver_user_id, sender_wallet_id, receiver_wallet_id,
    amount, currency, status, sender_wallet_transaction_id, receiver_wallet_transaction_id,
    transfer_ref, note, channel, metadata, created_at, completed_at
  ) values (
    p_sender_user_id, p_receiver_user_id, v_sender_wallet_id, v_receiver_wallet_id,
    p_amount, p_currency, 'completed', v_sender_tx, v_receiver_tx,
    p_transfer_ref, p_note, p_channel, coalesce(p_metadata, '{}'::jsonb), now(), now()
  )
  returning id into v_transfer_id;

  update public.wallet_transactions
  set reference_id = v_transfer_id,
      updated_at = now(),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('transfer_id', v_transfer_id)
  where id in (v_sender_tx, v_receiver_tx);

  perform public.mtaa_add_transfer_event(
    v_transfer_id, p_sender_user_id, 'completed', coalesce(p_note, 'Transfer completed'),
    jsonb_build_object('sender_transaction_id', v_sender_tx, 'receiver_transaction_id', v_receiver_tx) || coalesce(p_metadata, '{}'::jsonb)
  );

  perform public.mtaa_emit_event(
    p_sender_user_id, 'WALLET_TRANSFER_SENT', 'wallet', 'wallet_transfers', v_transfer_id, p_amount, p_currency,
    jsonb_build_object('receiver_user_id', p_receiver_user_id, 'sender_transaction_id', v_sender_tx) || coalesce(p_metadata, '{}'::jsonb)
  );

  perform public.mtaa_emit_event(
    p_receiver_user_id, 'WALLET_TRANSFER_RECEIVED', 'wallet', 'wallet_transfers', v_transfer_id, p_amount, p_currency,
    jsonb_build_object('sender_user_id', p_sender_user_id, 'receiver_transaction_id', v_receiver_tx) || coalesce(p_metadata, '{}'::jsonb)
  );

  return v_transfer_id;
end;
$$;


