CREATE OR REPLACE FUNCTION "public"."mtaa_create_wallet_qr"("expires_in_minutes" integer DEFAULT 60) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                                                                                                                                                                                                                                                  declare
                                                                                                                                                                                                                                                                                                                                    v_uid uuid := auth.uid();
                                                                                                                                                                                                                                                                                                                                      v_qr_id uuid;
                                                                                                                                                                                                                                                                                                                                        v_expires timestamp := now() + make_interval(mins => greatest(expires_in_minutes, 1));
                                                                                                                                                                                                                                                                                                                                        begin
                                                                                                                                                                                                                                                                                                                                          if v_uid is null then
                                                                                                                                                                                                                                                                                                                                              raise exception 'Not authenticated';
                                                                                                                                                                                                                                                                                                                                                end if;

                                                                                                                                                                                                                                                                                                                                                  insert into public.qr_codes (owner_id, qr_type, reference_id, expires_at, active, created_at)
                                                                                                                                                                                                                                                                                                                                                    values (v_uid, 'wallet_pay', v_uid, v_expires, true, now())
                                                                                                                                                                                                                                                                                                                                                      returning id into v_qr_id;

                                                                                                                                                                                                                                                                                                                                                        return v_qr_id;
                                                                                                                                                                                                                                                                                                                                                        end;
                                                                                                                                                                                                                                                                                                                                                        $$;


