CREATE OR REPLACE FUNCTION "public"."mtaa_credit_creator_earning"("p_creator_user_id" "uuid", "p_gross_amount" numeric, "p_platform_fee" numeric, "p_earning_type" "text", "p_source_module" "text", "p_source_table" "text" DEFAULT NULL::"text", "p_source_id" "uuid" DEFAULT NULL::"uuid", "p_currency" "text" DEFAULT 'KES'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_net_amount numeric(18,2);
  v_earning_id uuid;
  v_tx_id uuid;
begin

  if p_gross_amount <= 0 then
    raise exception 'Invalid earning amount';
  end if;

  v_net_amount := p_gross_amount - coalesce(p_platform_fee,0);

  insert into public.creator_earnings (
    creator_user_id,
    source_module,
    source_table,
    source_id,
    earning_type,
    gross_amount,
    platform_fee,
    net_amount,
    currency,
    metadata
  )
  values (
    p_creator_user_id,
    p_source_module,
    p_source_table,
    p_source_id,
    p_earning_type,
    p_gross_amount,
    p_platform_fee,
    v_net_amount,
    p_currency,
    p_metadata
  )
  returning id into v_earning_id;

  v_tx_id := public.mtaa_add_wallet_transaction(
    p_creator_user_id,
    v_net_amount,
    'revenue_credit',
    'completed',
    p_currency,
    'Creator earning',
    'creator_earning',
    v_earning_id,
    'internal',
    p_metadata
  );

  update public.creator_earnings
  set wallet_transaction_id = v_tx_id,
      status = 'credited',
      credited_at = now()
  where id = v_earning_id;

  perform public.mtaa_emit_event(
    p_creator_user_id,
    'CREATOR_EARNING_CREDITED',
    'creator_earnings',
    'creator_earnings',
    v_earning_id,
    v_net_amount,
    p_currency,
    p_metadata
  );

  return v_earning_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_credit_creator_earning"("p_creator_user_id" "uuid", "p_gross_amount" numeric, "p_platform_fee" numeric, "p_earning_type" "text", "p_source_module" "text", "p_source_table" "text", "p_source_id" "uuid", "p_currency" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_credit_wallet"("p_owner_id" "uuid", "p_amount" numeric, "p_description" "text", "p_reference" "text" DEFAULT NULL::"text", "p_topup_method" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
          begin
            -- ensure wallet exists
              insert into public.wallets (id, owner_id, balance, currency, created_at, updated_at)
                values (gen_random_uuid(), p_owner_id, 0, 'KES', now(), now())
                  on conflict (owner_id) do nothing;

                    update public.wallets
                        set balance = balance + p_amount,
                                updated_at = now()
                                  where owner_id = p_owner_id;

                                    insert into public.transactions (from_user, to_user, amount, tx_type, reference, topup_method, external_reference, created_at)
                                      values (null, p_owner_id, p_amount, 'topup', p_reference, p_topup_method, p_reference, now());
                                      end;
                                      $$;


ALTER FUNCTION "public"."mtaa_credit_wallet"("p_owner_id" "uuid", "p_amount" numeric, "p_description" "text", "p_reference" "text", "p_topup_method" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_detect_spoof"("p_user" "uuid", "p_lat" numeric, "p_lng" numeric) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
                  declare
                    last_lat numeric;
                      last_lng numeric;
                        last_time timestamptz;
                          distance numeric;
                            seconds_passed numeric;
                              speed_kmh numeric;
                              begin

                                select lat,lng,recorded_at
                                  into last_lat,last_lng,last_time
                                    from public.mtaa_location_history
                                      where user_id=p_user
                                        order by recorded_at desc
                                          limit 1;

                                            if last_time is null then
                                                return false;
                                                  end if;

                                                    distance := sqrt(power(p_lat-last_lat,2)+power(p_lng-last_lng,2))*111;
                                                      seconds_passed := extract(epoch from (now()-last_time));

                                                        if seconds_passed=0 then
                                                            return false;
                                                              end if;

                                                                speed_kmh := (distance/seconds_passed)*3600;

                                                                  if speed_kmh>180 then
                                                                      update public.mtaxi_driver_status
                                                                          set online=false
                                                                              where user_id=p_user;

                                                                                  return true;
                                                                                    end if;

                                                                                      return false;

                                                                                      end;
                                                                                      $$;


ALTER FUNCTION "public"."mtaa_detect_spoof"("p_user" "uuid", "p_lat" numeric, "p_lng" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_dispute_escrow_milestone"("p_milestone_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Milestone disputed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        declare
          v_escrow_account_id uuid;
            v_status text;
            begin
              select
                  em.escrow_account_id,
                      em.status
                        into
                            v_escrow_account_id,
                                v_status
                                  from public.escrow_milestones em
                                    where em.id = p_milestone_id
                                      limit 1;

                                        if v_escrow_account_id is null then
                                            raise exception 'Escrow milestone not found';
                                              end if;

                                                if v_status not in ('locked', 'submitted', 'approved') then
                                                    raise exception 'Only locked, submitted, or approved milestones can be disputed';
                                                      end if;

                                                        update public.escrow_milestones
                                                          set
                                                              status = 'disputed',
                                                                  disputed_at = now(),
                                                                      updated_at = now(),
                                                                          metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb)
                                                                            where id = p_milestone_id;

                                                                              update public.escrow_accounts
                                                                                set
                                                                                    status = 'disputed',
                                                                                        disputed_at = now(),
                                                                                            updated_at = now()
                                                                                              where id = v_escrow_account_id;

                                                                                                perform public.mtaa_add_escrow_event(
                                                                                                    v_escrow_account_id,
                                                                                                        'milestone_disputed',
                                                                                                            p_actor_user_id,
                                                                                                                p_milestone_id,
                                                                                                                    p_note,
                                                                                                                        coalesce(p_metadata, '{}'::jsonb)
                                                                                                                          );

                                                                                                                            return p_milestone_id;
                                                                                                                            end;
                                                                                                                            $$;


ALTER FUNCTION "public"."mtaa_dispute_escrow_milestone"("p_milestone_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_dispute_escrow_milestone_and_refresh"("p_milestone_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Milestone disputed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                          declare
                                                            v_escrow_account_id uuid;
                                                            begin
                                                              select escrow_account_id
                                                                into v_escrow_account_id
                                                                  from public.escrow_milestones
                                                                    where id = p_milestone_id
                                                                      limit 1;

                                                                        perform public.mtaa_dispute_escrow_milestone(
                                                                            p_milestone_id,
                                                                                p_actor_user_id,
                                                                                    p_note,
                                                                                        p_metadata
                                                                                          );

                                                                                            perform public.mtaa_refresh_escrow_account_status(v_escrow_account_id);

                                                                                              return p_milestone_id;
                                                                                              end;
                                                                                              $$;


ALTER FUNCTION "public"."mtaa_dispute_escrow_milestone_and_refresh"("p_milestone_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_dispute_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract disputed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
