CREATE OR REPLACE FUNCTION "public"."mtaa_fail_deposit"("p_deposit_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_failure_reason" "text" DEFAULT 'Deposit failed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_amount numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              update public.wallet_deposits
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                set status = 'failed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      failed_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            failed_by = coalesce(p_actor_user_id, failed_by),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  failure_reason = p_failure_reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          where id = p_deposit_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              and status in ('requested','pending','processing')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                returning user_id, currency, amount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  into v_user_id, v_currency, v_amount;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        raise exception 'Deposit not found or not fail-able';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            perform public.mtaa_add_deposit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'failed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p_failure_reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'WALLET_DEPOSIT_FAILED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'wallet_deposits',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    jsonb_build_object('reason', p_failure_reason) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return p_deposit_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_fail_deposit"("p_deposit_id" "uuid", "p_actor_user_id" "uuid", "p_failure_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_fail_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_failure_reason" "text" DEFAULT 'Payout failed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_amount numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_channel_fee numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_platform_fee numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_total_restore numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_restore_tx uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          update public.wallet_payouts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            set status = 'failed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  failed_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        failure_reason = p_failure_reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              processed_by = coalesce(processed_by, p_actor_user_id)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                where id = p_payout_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    and status in ('requested','queued','processing')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      returning user_id, currency, amount, channel_fee, platform_fee
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        into v_user_id, v_currency, v_amount, v_channel_fee, v_platform_fee;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              raise exception 'Payout not found or not fail-able';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_total_restore := coalesce(v_amount, 0) + coalesce(v_channel_fee, 0) + coalesce(v_platform_fee, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_restore_tx := public.mtaa_add_wallet_transaction(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_total_restore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'payout_reversal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'Payout failure reversal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'wallet_payout',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'internal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'reason', p_failure_reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'restored_amount', v_total_restore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'stage', 'failed'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      perform public.mtaa_add_payout_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'failed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_failure_reason,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'restore_transaction_id', v_restore_tx,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'restored_amount', v_total_restore
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'WALLET_PAYOUT_FAILED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'wallet_payouts',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'restore_transaction_id', v_restore_tx,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'restored_amount', v_total_restore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'reason', p_failure_reason
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return p_payout_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_fail_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid", "p_failure_reason" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_find_cluster_driver"("p_zone" "text") RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
    declare
      v_driver uuid;
      begin

        select cm.user_id
          into v_driver
            from public.mtaa_cluster_members cm
              join public.mtaxi_driver_status ds
                on ds.user_id = cm.user_id
                  join public.mtaa_driver_clusters c
                    on c.id = cm.cluster_id
                      where ds.online = true
                        and c.zone = p_zone
                          limit 1;

                            return v_driver;

                            end;
                            $$;


ALTER FUNCTION "public"."mtaa_find_cluster_driver"("p_zone" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_find_nearby_drivers"("pickup_lat" numeric, "pickup_lng" numeric, "radius_km" numeric DEFAULT 5) RETURNS TABLE("driver_user_id" "uuid", "lat" numeric, "lng" numeric, "distance_km" numeric)
    LANGUAGE "sql" STABLE
    AS $$

                            select

                                dl.user_id as driver_user_id,

                                    dl.lat,
                                        dl.lng,

                                            (
                                                    6371 *
                                                            acos(
                                                                        cos(radians(pickup_lat)) *
                                                                                    cos(radians(dl.lat)) *
                                                                                                cos(radians(dl.lng) - radians(pickup_lng)) +
                                                                                                            sin(radians(pickup_lat)) *
                                                                                                                        sin(radians(dl.lat))
                                                                                                                                )
                                                                                                                                    ) as distance_km

                                                                                                                                    from driver_locations dl

                                                                                                                                    join worker_status ws
                                                                                                                                    on ws.user_id = dl.user_id

                                                                                                                                    where ws.status = 'available'

                                                                                                                                    and (

                                                                                                                                            6371 *
                                                                                                                                                    acos(
                                                                                                                                                                cos(radians(pickup_lat)) *
                                                                                                                                                                            cos(radians(dl.lat)) *
                                                                                                                                                                                        cos(radians(dl.lng) - radians(pickup_lng)) +
                                                                                                                                                                                                    sin(radians(pickup_lat)) *
                                                                                                                                                                                                                sin(radians(dl.lat))
                                                                                                                                                                                                                        )

                                                                                                                                                                                                                        ) < radius_km

                                                                                                                                                                                                                        order by distance_km asc

                                                                                                                                                                                                                        limit 20;

                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_find_nearby_drivers"("pickup_lat" numeric, "pickup_lng" numeric, "radius_km" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_find_nearest_worker"("p_lat" numeric, "p_lng" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
                                    declare
                                      v_worker uuid;
                                      begin

                                        select user_id
                                          into v_worker
                                            from public.mtaxi_driver_status
                                              where online = true
                                                order by random()
                                                  limit 1;

                                                    return v_worker;

                                                    end;
                                                    $$;


ALTER FUNCTION "public"."mtaa_find_nearest_worker"("p_lat" numeric, "p_lng" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_fund_ad_campaign"("p_campaign_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Campaign funded'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_user_id uuid;
  v_budget_total numeric(18,2);
  v_currency text;
  v_status text;
  v_wallet_id uuid;
  v_tx_id uuid;
begin
  select
    advertiser_user_id,
    budget_total,
    currency,
    status,
    wallet_id
  into
    v_user_id,
    v_budget_total,
    v_currency,
    v_status,
    v_wallet_id
  from public.ad_campaigns
  where id = p_campaign_id
  limit 1;

  if v_user_id is null then
    raise exception 'Campaign not found';
  end if;

  if coalesce(v_budget_total, 0) <= 0 then
    raise exception 'Campaign budget must be greater than zero';
  end if;

  if v_status not in ('draft','pending_review','active','paused') then
    raise exception 'Campaign not fundable from current status';
  end if;

  if v_wallet_id is null then
    v_wallet_id := public.mtaa_get_or_create_wallet(v_user_id, v_currency);
    update public.ad_campaigns
    set wallet_id = v_wallet_id
    where id = p_campaign_id;
  end if;

  if exists (
    select 1
    from public.ad_campaigns
    where id = p_campaign_id
      and reserved_amount > 0
  ) then
    raise exception 'Campaign already funded/reserved';
  end if;

  v_tx_id := public.mtaa_add_wallet_transaction(
    v_user_id,
    -v_budget_total,
    'ad_reserve',
    'completed',
    v_currency,
    'Ad campaign budget reserved',
    'ad_campaign',
    p_campaign_id,
    'internal',
    jsonb_build_object(
      'stage', 'funded',
      'campaign_id', p_campaign_id
    ) || coalesce(p_metadata, '{}'::jsonb)
  );

  update public.ad_campaigns
  set
    reserved_amount = v_budget_total,
    funded_at = now(),
    billing_status = 'funded',
    updated_at = now()
  where id = p_campaign_id;

  perform public.mtaa_add_ad_billing_event(
    p_campaign_id,
    'campaign_funded',
    p_actor_user_id,
    v_budget_total,
    v_currency,
    p_note,
    null,
    jsonb_build_object(
      'wallet_transaction_id', v_tx_id
    ) || coalesce(p_metadata, '{}'::jsonb)
  );

  perform public.mtaa_emit_event(
    v_user_id,
    'AD_CAMPAIGN_FUNDED',
    'advertise',
    'ad_campaigns',
    p_campaign_id,
    v_budget_total,
    v_currency,
    jsonb_build_object(
      'wallet_transaction_id', v_tx_id
    ) || coalesce(p_metadata, '{}'::jsonb)
  );

  return p_campaign_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_fund_ad_campaign"("p_campaign_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_fund_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract funded'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        declare
          v_escrow_account_id uuid;
          begin
            select escrow_account_id
              into v_escrow_account_id
                from public.service_contracts
                  where id = p_contract_id
                    limit 1;

                      if v_escrow_account_id is null then
                          raise exception 'Contract has no escrow account attached';
                            end if;

                              update public.service_contracts
                                set
                                    status = 'active',
                                        metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                                            updated_at = now()
                                              where id = p_contract_id;

                                                perform public.mtaa_add_service_contract_event(
                                                    p_contract_id,
                                                        'contract_funded',
                                                            p_actor_user_id,
                                                                p_note,
                                                                    jsonb_build_object(
                                                                          'escrow_account_id', v_escrow_account_id
                                                                              ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                );

                                                                                  return p_contract_id;
                                                                                  end;
                                                                                  $$;


ALTER FUNCTION "public"."mtaa_fund_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_generate_work_profile_qr_value"("p_work_profile_id" "uuid") RETURNS "text"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
  declare
    v_user_id uuid;
      v_qr_value text;
      begin
        select user_id
          into v_user_id
            from public.work_profiles
              where id = p_work_profile_id
                limit 1;

                  if v_user_id is null then
                      raise exception 'Work profile not found';
                        end if;

                          v_qr_value := 'mtaa://work-profile/' || p_work_profile_id::text || '?user=' || v_user_id::text;

                            update public.work_profiles
                              set
                                  qr_code_value = v_qr_value,
                                      updated_at = now()
                                        where id = p_work_profile_id;

                                          return v_qr_value;
                                          end;
                                          $$;


ALTER FUNCTION "public"."mtaa_generate_work_profile_qr_value"("p_work_profile_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_get_or_create_direct_room"("other_user_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        DECLARE
          me uuid := auth.uid();
            existing_room uuid;
              new_room uuid;
              BEGIN
                IF me IS NULL THEN
                    RAISE EXCEPTION 'Not authenticated';
                      END IF;

                        IF other_user_id IS NULL OR other_user_id = me THEN
                            RAISE EXCEPTION 'Invalid other_user_id';
                              END IF;

                                -- Find existing direct room where both users are participants
                                  SELECT cp1.room_id INTO existing_room
                                    FROM public.chat_participants cp1
                                      JOIN public.chat_participants cp2
                                          ON cp2.room_id = cp1.room_id
                                            JOIN public.chat_rooms cr
                                                ON cr.id = cp1.room_id
                                                  WHERE cp1.user_id = me
                                                      AND cp2.user_id = other_user_id
                                                          AND cr.type = 'direct'
                                                            LIMIT 1;

                                                              IF existing_room IS NOT NULL THEN
                                                                  RETURN existing_room;
                                                                    END IF;

                                                                      -- Create new direct room
                                                                        INSERT INTO public.chat_rooms (type, created_by)
                                                                          VALUES ('direct', me)
                                                                            RETURNING id INTO new_room;

                                                                              -- Add both users as participants
                                                                                INSERT INTO public.chat_participants (room_id, user_id)
                                                                                  VALUES
                                                                                      (new_room, me),
                                                                                          (new_room, other_user_id)
                                                                                            ON CONFLICT DO NOTHING;

                                                                                              RETURN new_room;
                                                                                              END;
                                                                                              $$;


ALTER FUNCTION "public"."mtaa_get_or_create_direct_room"("other_user_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_get_or_create_wallet"("p_user_id" "uuid", "p_currency" "text" DEFAULT 'KES'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_wallet_id uuid;
begin
  select id into v_wallet_id
  from public.wallets
  where owner_id = p_user_id
  limit 1;

  if v_wallet_id is null then
    insert into public.wallets (owner_id, currency, balance, updated_at)
    values (p_user_id, p_currency, 0, now())
    returning id into v_wallet_id;
  end if;

  return v_wallet_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_get_or_create_wallet"("p_user_id" "uuid", "p_currency" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_grant_app_permission"("p_app_id" "uuid", "p_permission" "text", "p_granted" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
      declare
        v_user_id uuid := auth.uid();
        begin
          insert into public.app_permission_grants (
              user_id,
                  app_id,
                      permission,
                          granted,
                              granted_at,
                                  revoked_at
                                    )
                                      values (
                                          v_user_id,
                                              p_app_id,
                                                  p_permission,
                                                      p_granted,
                                                          case when p_granted then now() else null end,
                                                              case when p_granted then null else now() end
                                                                )
                                                                  on conflict (user_id, app_id, permission)
                                                                    do update set
                                                                        granted = excluded.granted,
                                                                            granted_at = case when excluded.granted then now() else public.app_permission_grants.granted_at end,
                                                                                revoked_at = case when excluded.granted then null else now() end;

                                                                                  insert into public.app_audit_logs (user_id, app_id, event_type, event)
                                                                                    values (
                                                                                        v_user_id,
                                                                                            p_app_id,
                                                                                                case when p_granted then 'permission_granted' else 'permission_revoked' end,
                                                                                                    jsonb_build_object('permission', p_permission, 'granted', p_granted)
                                                                                                      );

                                                                                                        return true;
                                                                                                        end;
                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_grant_app_permission"("p_app_id" "uuid", "p_permission" "text", "p_granted" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_has_verified_truck_vehicle"() RETURNS boolean
    LANGUAGE "sql" STABLE SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
  select exists (
      select 1
          from public.vehicles v
              where v.owner_id = auth.uid()
                    and coalesce(v.verified,false) = true
                          and coalesce(v.status,'pending') = 'approved'
                                and (
                                        lower(coalesce(v.type,'')) = 'truck'
                                                or position('truck' in lower(coalesce(v.type,''))) > 0
                                                      )
                                                        );
                                                        $$;


