CREATE OR REPLACE FUNCTION "public"."mtaa_on_post_view"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                    begin
                                                                                                                                                                                                      if new.post_id is null then
                                                                                                                                                                                                          return new;
                                                                                                                                                                                                            end if;

                                                                                                                                                                                                              perform public.mtaa_ensure_post_stats(new.post_id);

                                                                                                                                                                                                                update public.post_stats
                                                                                                                                                                                                                    set views = coalesce(views,0) + 1
                                                                                                                                                                                                                      where post_id = new.post_id;

                                                                                                                                                                                                                        return new;
                                                                                                                                                                                                                        end $$;


ALTER FUNCTION "public"."mtaa_on_post_view"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_on_post_view_increment_music"() RETURNS "trigger"
