    AS $$
                                              DECLARE
                                                v_track uuid;
                                                BEGIN
                                                  SELECT track_id INTO v_track
                                                    FROM public.content_music_usage
                                                      WHERE content_id = NEW.post_id
                                                        LIMIT 1;

                                                          IF v_track IS NOT NULL THEN
                                                              PERFORM public.mtaa_ensure_music_stats(v_track);

                                                                  UPDATE public.music_stats
                                                                      SET plays = COALESCE(plays,0) + 1
                                                                          WHERE track_id = v_track;
                                                                            END IF;

                                                                              RETURN NEW;
                                                                              END;
                                                                              $$;


ALTER FUNCTION "public"."mtaa_on_post_view_increment_music"() OWNER TO "postgres";


