CREATE OR REPLACE FUNCTION "public"."mtaa_process_payment"("p_from_owner_id" "uuid", "p_to_owner_id" "uuid", "p_total_amount" numeric, "p_type" "text", "p_reference" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                declare
                                                  v_commission numeric := round(p_total_amount * 0.17, 2);
                                                    v_net numeric := p_total_amount - v_commission;
                                                      v_platform_id uuid := '00000000-0000-0000-0000-000000000000';
                                                      begin
                                                        -- ensure wallets exist
                                                          insert into public.wallets (id, owner_id, balance, currency, created_at, updated_at)
                                                            values (gen_random_uuid(), p_from_owner_id, 0, 'KES', now(), now())
                                                              on conflict (owner_id) do nothing;

                                                                insert into public.wallets (id, owner_id, balance, currency, created_at, updated_at)
                                                                  values (gen_random_uuid(), p_to_owner_id, 0, 'KES', now(), now())
                                                                    on conflict (owner_id) do nothing;

                                                                      -- debit payer
                                                                        update public.wallets
                                                                            set balance = balance - p_total_amount,
                                                                                    updated_at = now()
                                                                                      where owner_id = p_from_owner_id
                                                                                          and balance >= p_total_amount;

                                                                                            if not found then
                                                                                                raise exception 'Insufficient balance';
                                                                                                  end if;

                                                                                                    -- credit receiver net
                                                                                                      update public.wallets
                                                                                                          set balance = balance + v_net,
                                                                                                                  updated_at = now()
                                                                                                                    where owner_id = p_to_owner_id;

                                                                                                                      -- credit platform commission
                                                                                                                        update public.wallets
                                                                                                                            set balance = balance + v_commission,
                                                                                                                                    updated_at = now()
                                                                                                                                      where owner_id = v_platform_id;

                                                                                                                                        -- audit
                                                                                                                                          insert into public.transactions (from_user, to_user, amount, tx_type, reference, created_at)
                                                                                                                                            values (p_from_owner_id, p_to_owner_id, v_net, p_type, p_reference, now());

                                                                                                                                              insert into public.transactions (from_user, to_user, amount, tx_type, reference, created_at)
                                                                                                                                                values (p_from_owner_id, v_platform_id, v_commission, 'commission', p_reference, now());
                                                                                                                                                end;
                                                                                                                                                $$;


ALTER FUNCTION "public"."mtaa_process_payment"("p_from_owner_id" "uuid", "p_to_owner_id" "uuid", "p_total_amount" numeric, "p_type" "text", "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_queue_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Payout queued'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              update public.wallet_payouts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                set status = 'queued',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      queued_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where id = p_payout_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            and status = 'requested'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              returning user_id, currency into v_user_id, v_currency;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    raise exception 'Payout not found or not in requested status';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        perform public.mtaa_add_payout_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'queued',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'WALLET_PAYOUT_QUEUED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'wallet_payouts',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return p_payout_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $$;


ALTER FUNCTION "public"."mtaa_queue_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_record_cash_agent_commission"("p_agent_user_id" "uuid", "p_amount" numeric, "p_source_id" "uuid", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_tx_id uuid;
begin
  v_tx_id := public.mtaa_add_wallet_transaction(
    p_agent_user_id,
    p_amount,
    'commission',
    'completed',
    'KES',
    'Cash Point commission',
    'cash_point_transaction',
    p_source_id,
    'internal',
    coalesce(p_metadata, '{}'::jsonb)
  );

  perform public.mtaa_emit_event(
    p_agent_user_id,
    'WALLET_CASH_AGENT_COMMISSION_COMPLETED',
    'cash_points',
    'wallet_transactions',
    v_tx_id,
    p_amount,
    'KES',
    jsonb_build_object(
      'source_id', p_source_id
    ) || coalesce(p_metadata, '{}'::jsonb)
  );

  return v_tx_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_record_cash_agent_commission"("p_agent_user_id" "uuid", "p_amount" numeric, "p_source_id" "uuid", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_record_post_view"("p_post_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                begin
                                                                                  perform public.mtaa_ensure_post_stats(p_post_id);

                                                                                    insert into public.post_views(post_id, viewer_id)
                                                                                      values (p_post_id, auth.uid());

                                                                                        update public.post_stats
                                                                                          set views = coalesce(views, 0) + 1
                                                                                            where post_id = p_post_id;
                                                                                            end;
                                                                                            $$;


ALTER FUNCTION "public"."mtaa_record_post_view"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_record_view_with_music"("p_post_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                                                                                                                                                            declare
                                                                                                                                                                                                                                              v_track_id uuid;
                                                                                                                                                                                                                                                v_musician_id uuid;
                                                                                                                                                                                                                                                  v_pay_per_unit numeric := 0;
                                                                                                                                                                                                                                                    v_views_required int := 0;
                                                                                                                                                                                                                                                      v_is_monetized boolean := false;
                                                                                                                                                                                                                                                      begin
                                                                                                                                                                                                                                                        if auth.uid() is null then
                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                              end if;

                                                                                                                                                                                                                                                                -- always log a raw view row (you already have post_views in schema)
                                                                                                                                                                                                                                                                  insert into public.post_views(post_id, viewer_id)
                                                                                                                                                                                                                                                                    values (p_post_id, auth.uid());

                                                                                                                                                                                                                                                                      -- update post_stats if present
                                                                                                                                                                                                                                                                        insert into public.post_stats(post_id, views)
                                                                                                                                                                                                                                                                          values (p_post_id, 1)
                                                                                                                                                                                                                                                                            on conflict (post_id) do update set views = coalesce(public.post_stats.views,0) + 1;

                                                                                                                                                                                                                                                                              -- check if post has attached track
                                                                                                                                                                                                                                                                                select track_id into v_track_id
                                                                                                                                                                                                                                                                                  from public.post_tracks_usage
                                                                                                                                                                                                                                                                                    where post_id = p_post_id;

                                                                                                                                                                                                                                                                                      if v_track_id is null then
                                                                                                                                                                                                                                                                                          return;
                                                                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                                                                              perform public.mtaa_ensure_music_stats(v_track_id);

                                                                                                                                                                                                                                                                                                update public.music_stats
                                                                                                                                                                                                                                                                                                    set plays = coalesce(plays,0) + 1
                                                                                                                                                                                                                                                                                                      where track_id = v_track_id;

                                                                                                                                                                                                                                                                                                        -- monetization rule for module='music'
                                                                                                                                                                                                                                                                                                          select views_required, pay_per_unit
                                                                                                                                                                                                                                                                                                            into v_views_required, v_pay_per_unit
                                                                                                                                                                                                                                                                                                              from public.monetization_rules
                                                                                                                                                                                                                                                                                                                where module = 'music' and active = true
                                                                                                                                                                                                                                                                                                                  order by views_required desc
                                                                                                                                                                                                                                                                                                                    limit 1;

                                                                                                                                                                                                                                                                                                                      select monetized into v_is_monetized
                                                                                                                                                                                                                                                                                                                        from public.music_stats
                                                                                                                                                                                                                                                                                                                          where track_id = v_track_id;

                                                                                                                                                                                                                                                                                                                            -- If not monetized yet, monetize after threshold
                                                                                                                                                                                                                                                                                                                              if v_is_monetized is false then
                                                                                                                                                                                                                                                                                                                                  if (select plays from public.music_stats where track_id = v_track_id) >= coalesce(v_views_required,0)
                                                                                                                                                                                                                                                                                                                                      then
                                                                                                                                                                                                                                                                                                                                            update public.music_stats
                                                                                                                                                                                                                                                                                                                                                    set monetized = true, monetized_at = now()
                                                                                                                                                                                                                                                                                                                                                          where track_id = v_track_id;
                                                                                                                                                                                                                                                                                                                                                                v_is_monetized := true;
                                                                                                                                                                                                                                                                                                                                                                    end if;
                                                                                                                                                                                                                                                                                                                                                                      end if;

                                                                                                                                                                                                                                                                                                                                                                        if v_is_monetized is not true then
                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                              end if;

                                                                                                                                                                                                                                                                                                                                                                                if coalesce(v_pay_per_unit,0) <= 0 then
                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                      end if;

                                                                                                                                                                                                                                                                                                                                                                                        -- musician is the music_tracks.user_id
                                                                                                                                                                                                                                                                                                                                                                                          select user_id into v_musician_id
                                                                                                                                                                                                                                                                                                                                                                                            from public.music_tracks
                                                                                                                                                                                                                                                                                                                                                                                              where id = v_track_id;

                                                                                                                                                                                                                                                                                                                                                                                                if v_musician_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                      end if;

                                                                                                                                                                                                                                                                                                                                                                                                        -- record earnings
                                                                                                                                                                                                                                                                                                                                                                                                          insert into public.music_earnings(musician_id, source, amount, status)
                                                                                                                                                                                                                                                                                                                                                                                                            values (v_musician_id, 'post_view', v_pay_per_unit, 'pending');

                                                                                                                                                                                                                                                                                                                                                                                                              -- credit musician wallet (token model: 1 token = 1 KES)
                                                                                                                                                                                                                                                                                                                                                                                                                insert into public.wallet_accounts(user_id, balance)
                                                                                                                                                                                                                                                                                                                                                                                                                  values (v_musician_id, 0)
                                                                                                                                                                                                                                                                                                                                                                                                                    on conflict (user_id) do nothing;

                                                                                                                                                                                                                                                                                                                                                                                                                      update public.wallet_accounts
                                                                                                                                                                                                                                                                                                                                                                                                                          set balance = coalesce(balance,0) + v_pay_per_unit
                                                                                                                                                                                                                                                                                                                                                                                                                            where user_id = v_musician_id;

                                                                                                                                                                                                                                                                                                                                                                                                                              insert into public.wallet_transactions(user_id, amount, type)
                                                                                                                                                                                                                                                                                                                                                                                                                                values (v_musician_id, v_pay_per_unit, 'music_payout');

                                                                                                                                                                                                                                                                                                                                                                                                                                  -- reflect on music_stats.earnings
                                                                                                                                                                                                                                                                                                                                                                                                                                    update public.music_stats
                                                                                                                                                                                                                                                                                                                                                                                                                                        set earnings = coalesce(earnings,0) + v_pay_per_unit
                                                                                                                                                                                                                                                                                                                                                                                                                                          where track_id = v_track_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                          end;
                                                                                                                                                                                                                                                                                                                                                                                                                                          $$;


ALTER FUNCTION "public"."mtaa_record_view_with_music"("p_post_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_refresh_escrow_account_status"("p_escrow_account_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
  declare
    v_total_count integer;
      v_released_count integer;
        v_refunded_count integer;
          v_disputed_count integer;
          begin
            select count(*)
              into v_total_count
                from public.escrow_milestones
                  where escrow_account_id = p_escrow_account_id;

                    select count(*)
                      into v_released_count
                        from public.escrow_milestones
                          where escrow_account_id = p_escrow_account_id
                              and status = 'released';

                                select count(*)
                                  into v_refunded_count
                                    from public.escrow_milestones
                                      where escrow_account_id = p_escrow_account_id
                                          and status = 'refunded';

                                            select count(*)
                                              into v_disputed_count
                                                from public.escrow_milestones
                                                  where escrow_account_id = p_escrow_account_id
                                                      and status = 'disputed';

                                                        update public.escrow_accounts
                                                          set
                                                              status = case
                                                                    when v_disputed_count > 0 then 'disputed'
                                                                          when v_total_count > 0 and v_total_count = v_released_count then 'completed'
                                                                                when v_total_count > 0 and v_total_count = v_refunded_count then 'refunded'
                                                                                      when v_released_count > 0 then 'partially_released'
                                                                                            when funded_amount > 0 then 'funded'
                                                                                                  else 'pending'
                                                                                                      end,
                                                                                                          completed_at = case
                                                                                                                when v_total_count > 0 and v_total_count = v_released_count then now()
                                                                                                                      else completed_at
                                                                                                                          end,
                                                                                                                              updated_at = now()
                                                                                                                                where id = p_escrow_account_id;

                                                                                                                                  return p_escrow_account_id;
                                                                                                                                  end;
                                                                                                                                  $$;


ALTER FUNCTION "public"."mtaa_refresh_escrow_account_status"("p_escrow_account_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_refresh_service_contract_status_from_escrow"("p_contract_id" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
  declare
    v_escrow_account_id uuid;
      v_escrow_status text;
      begin
        select sc.escrow_account_id
          into v_escrow_account_id
            from public.service_contracts sc
              where sc.id = p_contract_id
                limit 1;

                  if v_escrow_account_id is null then
                      return p_contract_id;
                        end if;

                          select ea.status
                            into v_escrow_status
                              from public.escrow_accounts ea
                                where ea.id = v_escrow_account_id
                                  limit 1;

                                    update public.service_contracts
                                      set
                                          status = case
                                                when v_escrow_status = 'completed' then 'completed'
                                                      when v_escrow_status = 'disputed' then 'disputed'
                                                            when v_escrow_status in ('funded', 'partially_released') then 'active'
                                                                  when v_escrow_status in ('cancelled', 'refunded') then 'cancelled'
                                                                        else status
                                                                            end,
                                                                                updated_at = now()
                                                                                  where id = p_contract_id;

                                                                                    return p_contract_id;
                                                                                    end;
                                                                                    $$;


ALTER FUNCTION "public"."mtaa_refresh_service_contract_status_from_escrow"("p_contract_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_refund_ad_campaign_balance"("p_campaign_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Unused campaign balance refunded'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_user_id uuid;
  v_currency text;
  v_reserved_amount numeric(18,2);
  v_tx_id uuid;
begin
  update public.ad_campaigns
  set
    reserved_amount = 0,
    billing_status = case when status='cancelled' then 'cancelled' else 'completed' end,
    updated_at = now()
  where id=p_campaign_id
    and status in ('paused','completed','cancelled','rejected')
    and coalesce(reserved_amount,0) > 0
  returning advertiser_user_id, currency, reserved_amount
  into v_user_id, v_currency, v_reserved_amount;

  if v_user_id is null then
    raise exception 'Campaign not refundable or no reserved amount exists';
  end if;

  v_tx_id := public.mtaa_add_wallet_transaction(
    v_user_id,
    v_reserved_amount,
    'ad_refund',
    'completed',
    v_currency,
    'Unused ad campaign balance refunded',
    'ad_campaign',
    p_campaign_id,
    'internal',
    jsonb_build_object(
      'stage','refund',
      'campaign_id',p_campaign_id
    ) || coalesce(p_metadata,'{}'::jsonb)
  );

  return p_campaign_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_refund_ad_campaign_balance"("p_campaign_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_refund_escrow_milestone"("p_milestone_id" "uuid", "p_employer_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Milestone refunded'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
          declare
            v_escrow_account_id uuid;
              v_employer_id uuid;
                v_worker_id uuid;
                  v_status text;
                    v_amount numeric(18,2);
                      v_currency text;
                      begin
                        select
                            em.escrow_account_id,
                                em.status,
                                    em.amount,
                                        em.currency,
                                            ea.employer_id,
                                                ea.worker_id
                                                  into
                                                      v_escrow_account_id,
                                                          v_status,
                                                              v_amount,
                                                                  v_currency,
                                                                      v_employer_id,
                                                                          v_worker_id
                                                                            from public.escrow_milestones em
                                                                              join public.escrow_accounts ea on ea.id = em.escrow_account_id
                                                                                where em.id = p_milestone_id
                                                                                  limit 1;

                                                                                    if v_escrow_account_id is null then
                                                                                        raise exception 'Escrow milestone not found';
                                                                                          end if;

                                                                                            if v_status not in ('locked', 'submitted', 'disputed') then
                                                                                                raise exception 'Only locked, submitted, or disputed milestones can be refunded';
                                                                                                  end if;

                                                                                                    update public.escrow_milestones
                                                                                                      set
                                                                                                          status = 'refunded',
                                                                                                              cancelled_at = now(),
                                                                                                                  updated_at = now(),
                                                                                                                      metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                        where id = p_milestone_id;

                                                                                                                          insert into public.escrow_transactions (
                                                                                                                              escrow_account_id,
                                                                                                                                  milestone_id,
                                                                                                                                      employer_id,
                                                                                                                                          worker_id,
                                                                                                                                              wallet_transaction_id,
                                                                                                                                                  transaction_type,
                                                                                                                                                      status,
                                                                                                                                                          amount,
                                                                                                                                                              currency,
                                                                                                                                                                  note,
                                                                                                                                                                      metadata
                                                                                                                                                                        ) values (
                                                                                                                                                                            v_escrow_account_id,
                                                                                                                                                                                p_milestone_id,
                                                                                                                                                                                    v_employer_id,
                                                                                                                                                                                        v_worker_id,
                                                                                                                                                                                            p_employer_wallet_transaction_id,
                                                                                                                                                                                                'refund',
                                                                                                                                                                                                    'completed',
                                                                                                                                                                                                        coalesce(v_amount, 0),
                                                                                                                                                                                                            v_currency,
                                                                                                                                                                                                                p_note,
                                                                                                                                                                                                                    jsonb_build_object(
                                                                                                                                                                                                                          'refund_target', 'employer'
                                                                                                                                                                                                                              ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                  update public.escrow_accounts
                                                                                                                                                                                                                                    set
                                                                                                                                                                                                                                        refunded_amount = coalesce(refunded_amount, 0) + coalesce(v_amount, 0),
                                                                                                                                                                                                                                            updated_at = now()
                                                                                                                                                                                                                                              where id = v_escrow_account_id;

                                                                                                                                                                                                                                                perform public.mtaa_add_escrow_event(
                                                                                                                                                                                                                                                    v_escrow_account_id,
                                                                                                                                                                                                                                                        'milestone_refunded',
                                                                                                                                                                                                                                                            p_actor_user_id,
                                                                                                                                                                                                                                                                p_milestone_id,
                                                                                                                                                                                                                                                                    p_note,
                                                                                                                                                                                                                                                                        jsonb_build_object(
                                                                                                                                                                                                                                                                              'amount', coalesce(v_amount, 0),
                                                                                                                                                                                                                                                                                    'wallet_transaction_id', p_employer_wallet_transaction_id
                                                                                                                                                                                                                                                                                        ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                            return p_milestone_id;
                                                                                                                                                                                                                                                                                            end;
                                                                                                                                                                                                                                                                                            $$;


ALTER FUNCTION "public"."mtaa_refund_escrow_milestone"("p_milestone_id" "uuid", "p_employer_wallet_transaction_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_refund_escrow_milestone_and_refresh"("p_milestone_id" "uuid", "p_employer_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Milestone refunded'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
          declare
            v_escrow_account_id uuid;
            begin
              select escrow_account_id
                into v_escrow_account_id
                  from public.escrow_milestones
                    where id = p_milestone_id
                      limit 1;

                        perform public.mtaa_refund_escrow_milestone(
                            p_milestone_id,
                                p_employer_wallet_transaction_id,
                                    p_actor_user_id,
                                        p_note,
                                            p_metadata
                                              );

                                                perform public.mtaa_refresh_escrow_account_status(v_escrow_account_id);

                                                  return p_milestone_id;
                                                  end;
                                                  $$;


ALTER FUNCTION "public"."mtaa_refund_escrow_milestone_and_refresh"("p_milestone_id" "uuid", "p_employer_wallet_transaction_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_reject_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract rejected'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                            begin
                                                                              update public.service_contracts
                                                                                set
                                                                                    status = 'cancelled',
                                                                                        metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                                                                                            updated_at = now()
                                                                                              where id = p_contract_id;

                                                                                                perform public.mtaa_add_service_contract_event(
                                                                                                    p_contract_id,
                                                                                                        'contract_rejected',
                                                                                                            p_actor_user_id,
                                                                                                                p_note,
                                                                                                                    coalesce(p_metadata, '{}'::jsonb)
                                                                                                                      );

                                                                                                                        return p_contract_id;
                                                                                                                        end;
                                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_reject_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_release_milestone"("p_job_id" "uuid", "p_milestone_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_employer_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_worker_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_amount numeric;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_prev_status text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_remaining int;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if auth.uid() is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              raise exception 'Auth required';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  -- employer is jobs.user_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    select j.user_id into v_employer_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      from public.jobs j
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where j.id = p_job_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if v_employer_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              raise exception 'Job not found';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  if auth.uid() <> v_employer_id then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      raise exception 'Only employer can release milestones';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- lock milestone row
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            select m.user_id, m.amount, m.status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                into v_worker_id, v_amount, v_prev_status
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  from public.milestones m
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    where m.id = p_milestone_id and m.job_id = p_job_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      for update;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if v_worker_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            raise exception 'Milestone not found for job';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if v_prev_status = 'completed' then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    raise exception 'Milestone already completed';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if v_amount is null or v_amount <= 0 then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            raise exception 'Invalid milestone amount';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ensure worker wallet exists
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.wallets (id, owner_id, balance, currency, created_at, updated_at)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    values (gen_random_uuid(), v_worker_id, 0, 'KES', now(), now())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      on conflict (owner_id) do nothing;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- credit wallet
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          update public.wallets
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              set balance = balance + v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where owner_id = v_worker_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- log transaction
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            insert into public.wallet_transactions (user_id, amount, type)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              values (v_worker_id, v_amount, 'milestone_release');

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- mark milestone complete
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  update public.milestones
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      set status = 'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              released_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where id = p_milestone_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- update escrow status if escrow exists
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            select count(*) into v_remaining
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              from public.milestones
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                where job_id = p_job_id and status <> 'completed';

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  update public.escrow_accounts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      set status = case when v_remaining > 0 then 'partially_released' else 'completed' end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where job_id = p_job_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_release_milestone"("p_job_id" "uuid", "p_milestone_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_remove_user_widget"("p_user_widget_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                              declare
                                                                                                                                                                                                                                                                v_user_id uuid := auth.uid();
                                                                                                                                                                                                                                                                begin
                                                                                                                                                                                                                                                                  delete from public.user_widgets
                                                                                                                                                                                                                                                                    where id = p_user_widget_id
                                                                                                                                                                                                                                                                        and user_id = v_user_id;

                                                                                                                                                                                                                                                                          return true;
                                                                                                                                                                                                                                                                          end;
                                                                                                                                                                                                                                                                          $$;


ALTER FUNCTION "public"."mtaa_remove_user_widget"("p_user_widget_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_request_deposit"("p_user_id" "uuid", "p_amount" numeric, "p_channel" "text", "p_wallet_id" "uuid" DEFAULT NULL::"uuid", "p_currency" "text" DEFAULT 'KES'::"text", "p_provider_name" "text" DEFAULT NULL::"text", "p_external_reference" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_wallet_id uuid;
  v_deposit_id uuid;
begin
  if p_amount is null or p_amount <= 0 then
    raise exception 'Deposit amount must be greater than zero';
  end if;

  if p_channel not in ('manual','mpesa','bank','cash_point','internal','card') then
    raise exception 'Unsupported deposit channel: %', p_channel;
  end if;

  v_wallet_id := coalesce(p_wallet_id, public.mtaa_get_or_create_wallet(p_user_id, p_currency));

  insert into public.wallet_deposits (
    user_id, wallet_id, amount, currency, provider_name, channel, status,
    external_reference, requested_by, requested_at, metadata, updated_at
  ) values (
    p_user_id, v_wallet_id, p_amount, p_currency, p_provider_name, p_channel,
    case when p_channel = 'internal' then 'processing' else 'requested' end,
    p_external_reference, p_user_id, now(), coalesce(p_metadata, '{}'::jsonb), now()
  )
  returning id into v_deposit_id;

  perform public.mtaa_add_deposit_event(
    v_deposit_id, p_user_id, 'requested', 'Deposit requested',
    jsonb_build_object('amount', p_amount, 'currency', p_currency, 'channel', p_channel) || coalesce(p_metadata, '{}'::jsonb)
  );

  perform public.mtaa_emit_event(
    p_user_id, 'WALLET_DEPOSIT_REQUESTED', 'wallet', 'wallet_deposits', v_deposit_id, p_amount, p_currency,
    jsonb_build_object('wallet_id', v_wallet_id, 'channel', p_channel, 'provider_name', p_provider_name, 'external_reference', p_external_reference) || coalesce(p_metadata, '{}'::jsonb)
  );

  return v_deposit_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_request_deposit"("p_user_id" "uuid", "p_amount" numeric, "p_channel" "text", "p_wallet_id" "uuid", "p_currency" "text", "p_provider_name" "text", "p_external_reference" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_request_payout"("p_user_id" "uuid", "p_amount" numeric, "p_destination_type" "text", "p_wallet_id" "uuid" DEFAULT NULL::"uuid", "p_destination" "jsonb" DEFAULT '{}'::"jsonb", "p_currency" "text" DEFAULT 'KES'::"text", "p_provider_name" "text" DEFAULT NULL::"text", "p_channel_fee" numeric DEFAULT 0, "p_platform_fee" numeric DEFAULT 0, "p_external_reference" "text" DEFAULT NULL::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                    declare
                                                                                      v_wallet_id uuid;
                                                                                        v_wallet_balance numeric(18,2);
                                                                                          v_total_debit numeric(18,2);
                                                                                            v_payout_id uuid;
                                                                                              v_tx_id uuid;
                                                                                              begin
                                                                                                if p_amount is null or p_amount <= 0 then
                                                                                                    raise exception 'Payout amount must be greater than zero';
                                                                                                      end if;

                                                                                                        if p_destination_type not in ('mpesa','bank_transfer','mobile_money','internal') then
                                                                                                            raise exception 'Unsupported payout destination_type: %', p_destination_type;
                                                                                                              end if;

                                                                                                                if coalesce(p_channel_fee, 0) < 0 or coalesce(p_platform_fee, 0) < 0 then
                                                                                                                    raise exception 'Fees cannot be negative';
                                                                                                                      end if;

                                                                                                                        v_total_debit := p_amount + coalesce(p_channel_fee, 0) + coalesce(p_platform_fee, 0);

                                                                                                                          select w.id, w.balance
                                                                                                                            into v_wallet_id, v_wallet_balance
                                                                                                                              from public.wallets w
                                                                                                                                where w.owner_id = p_user_id
                                                                                                                                    and (p_wallet_id is null or w.id = p_wallet_id)
                                                                                                                                      limit 1;

                                                                                                                                        if v_wallet_id is null then
                                                                                                                                            raise exception 'Wallet not found for user';
                                                                                                                                              end if;

                                                                                                                                                if coalesce(v_wallet_balance, 0) < v_total_debit then
                                                                                                                                                    raise exception 'Insufficient wallet balance';
                                                                                                                                                      end if;

                                                                                                                                                        v_tx_id := public.mtaa_add_wallet_transaction(
                                                                                                                                                            p_user_id,
                                                                                                                                                                -v_total_debit,
                                                                                                                                                                    'withdrawal',
                                                                                                                                                                        'completed',
                                                                                                                                                                            p_currency,
                                                                                                                                                                                'Wallet payout request',
                                                                                                                                                                                    'wallet_payout',
                                                                                                                                                                                        null,
                                                                                                                                                                                            p_provider_name,
                                                                                                                                                                                                jsonb_build_object(
                                                                                                                                                                                                      'destination_type', p_destination_type,
                                                                                                                                                                                                            'destination', coalesce(p_destination, '{}'::jsonb),
                                                                                                                                                                                                                  'amount', p_amount,
                                                                                                                                                                                                                        'channel_fee', coalesce(p_channel_fee, 0),
                                                                                                                                                                                                                              'platform_fee', coalesce(p_platform_fee, 0),
                                                                                                                                                                                                                                    'stage', 'requested'
                                                                                                                                                                                                                                        ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                            insert into public.wallet_payouts (
                                                                                                                                                                                                                                                user_id,
                                                                                                                                                                                                                                                    wallet_id,
                                                                                                                                                                                                                                                        destination_type,
                                                                                                                                                                                                                                                            destination,
                                                                                                                                                                                                                                                                amount,
                                                                                                                                                                                                                                                                    currency,
                                                                                                                                                                                                                                                                        status,
                                                                                                                                                                                                                                                                            related_wallet_transaction_id,
                                                                                                                                                                                                                                                                                external_reference,
                                                                                                                                                                                                                                                                                    requested_at,
                                                                                                                                                                                                                                                                                        requested_by,
                                                                                                                                                                                                                                                                                            provider_name,
                                                                                                                                                                                                                                                                                                channel_fee,
                                                                                                                                                                                                                                                                                                    platform_fee
                                                                                                                                                                                                                                                                                                      ) values (
                                                                                                                                                                                                                                                                                                          p_user_id,
                                                                                                                                                                                                                                                                                                              v_wallet_id,
                                                                                                                                                                                                                                                                                                                  p_destination_type,
                                                                                                                                                                                                                                                                                                                      coalesce(p_destination, '{}'::jsonb),
                                                                                                                                                                                                                                                                                                                          p_amount,
                                                                                                                                                                                                                                                                                                                              p_currency,
                                                                                                                                                                                                                                                                                                                                  'requested',
                                                                                                                                                                                                                                                                                                                                      v_tx_id,
                                                                                                                                                                                                                                                                                                                                          p_external_reference,
                                                                                                                                                                                                                                                                                                                                              now(),
                                                                                                                                                                                                                                                                                                                                                  p_user_id,
                                                                                                                                                                                                                                                                                                                                                      p_provider_name,
                                                                                                                                                                                                                                                                                                                                                          coalesce(p_channel_fee, 0),
                                                                                                                                                                                                                                                                                                                                                              coalesce(p_platform_fee, 0)
                                                                                                                                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                                                                                                                                  returning id into v_payout_id;

                                                                                                                                                                                                                                                                                                                                                                    update public.wallet_transactions
                                                                                                                                                                                                                                                                                                                                                                      set reference_id = v_payout_id,
                                                                                                                                                                                                                                                                                                                                                                            updated_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                  metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object('payout_id', v_payout_id)
                                                                                                                                                                                                                                                                                                                                                                                    where id = v_tx_id;

                                                                                                                                                                                                                                                                                                                                                                                      perform public.mtaa_add_payout_event(
                                                                                                                                                                                                                                                                                                                                                                                          v_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                              p_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                  'requested',
                                                                                                                                                                                                                                                                                                                                                                                                      'Payout requested',
                                                                                                                                                                                                                                                                                                                                                                                                          jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                'amount', p_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                      'currency', p_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                            'total_debit', v_total_debit,
                                                                                                                                                                                                                                                                                                                                                                                                                                  'destination_type', p_destination_type
                                                                                                                                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                          perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                              p_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                  'WALLET_PAYOUT_REQUESTED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                      'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                          'wallet_payouts',
                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'wallet_id', v_wallet_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'related_wallet_transaction_id', v_tx_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'destination_type', p_destination_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'channel_fee', coalesce(p_channel_fee, 0),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'platform_fee', coalesce(p_platform_fee, 0)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return v_payout_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                $$;


ALTER FUNCTION "public"."mtaa_request_payout"("p_user_id" "uuid", "p_amount" numeric, "p_destination_type" "text", "p_wallet_id" "uuid", "p_destination" "jsonb", "p_currency" "text", "p_provider_name" "text", "p_channel_fee" numeric, "p_platform_fee" numeric, "p_external_reference" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_resolve_escrow_dispute_to_employer"("p_milestone_id" "uuid", "p_employer_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Dispute resolved in favor of employer'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
          begin
            perform public.mtaa_refund_escrow_milestone(
                p_milestone_id,
                    p_employer_wallet_transaction_id,
                        p_actor_user_id,
                            p_note,
                                coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('dispute_resolution', 'employer')
                                  );

                                    return p_milestone_id;
                                    end;
                                    $$;


ALTER FUNCTION "public"."mtaa_resolve_escrow_dispute_to_employer"("p_milestone_id" "uuid", "p_employer_wallet_transaction_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_resolve_escrow_dispute_to_worker"("p_milestone_id" "uuid", "p_worker_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid", "p_platform_fee_wallet_transaction_id" "uuid" DEFAULT NULL::"uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Dispute resolved in favor of worker'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
            begin
              perform public.mtaa_approve_and_release_escrow_milestone(
                  p_milestone_id,
                      p_worker_wallet_transaction_id,
                          p_platform_fee_wallet_transaction_id,
                              p_actor_user_id,
                                  p_note,
                                      coalesce(p_metadata, '{}'::jsonb) || jsonb_build_object('dispute_resolution', 'worker')
                                        );

                                          return p_milestone_id;
                                          end;
                                          $$;


ALTER FUNCTION "public"."mtaa_resolve_escrow_dispute_to_worker"("p_milestone_id" "uuid", "p_worker_wallet_transaction_id" "uuid", "p_platform_fee_wallet_transaction_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_reverse_payout"("p_payout_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Completed payout reversed'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_amount numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_channel_fee numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_platform_fee numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          v_total_restore numeric(18,2);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_restore_tx uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              update public.wallet_payouts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                set status = 'reversed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      reversed_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            reversed_by = p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  failure_reason = coalesce(failure_reason, 'Completed payout reversed')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    where id = p_payout_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        and status = 'completed'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          returning user_id, currency, amount, channel_fee, platform_fee
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            into v_user_id, v_currency, v_amount, v_channel_fee, v_platform_fee;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  raise exception 'Payout not found or not reversible';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_total_restore := coalesce(v_amount, 0) + coalesce(v_channel_fee, 0) + coalesce(v_platform_fee, 0);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_restore_tx := public.mtaa_add_wallet_transaction(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_total_restore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'payout_reversal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'Completed payout reversal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'wallet_payout',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'internal',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'restored_amount', v_total_restore,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'stage', 'reversed'
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    perform public.mtaa_add_payout_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'reversed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'restore_transaction_id', v_restore_tx,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'restored_amount', v_total_restore
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'WALLET_PAYOUT_REVERSED',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'wallet_payouts',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_amount,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_currency,
