ALTER FUNCTION "public"."mtaa_reverse_transfer"("p_transfer_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_review_app_verification"("p_request_id" "uuid", "p_decision" "text", "p_note" "text" DEFAULT NULL::"text", "p_checklist_patch" "jsonb" DEFAULT '{}'::"jsonb") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                      declare
                                                                                                                                                                                                                                                                                                                                                                        v_user_id uuid := auth.uid();
                                                                                                                                                                                                                                                                                                                                                                          v_request record;
                                                                                                                                                                                                                                                                                                                                                                          begin
                                                                                                                                                                                                                                                                                                                                                                            if v_user_id <> '8e41ee2e-ae74-43a5-a550-a1d02a5591a3'::uuid then
                                                                                                                                                                                                                                                                                                                                                                                raise exception 'Admin only';
                                                                                                                                                                                                                                                                                                                                                                                  end if;

                                                                                                                                                                                                                                                                                                                                                                                    if p_decision not in (
                                                                                                                                                                                                                                                                                                                                                                                        'in_review',
                                                                                                                                                                                                                                                                                                                                                                                            'changes_requested',
                                                                                                                                                                                                                                                                                                                                                                                                'approved',
                                                                                                                                                                                                                                                                                                                                                                                                    'published',
                                                                                                                                                                                                                                                                                                                                                                                                        'rejected',
                                                                                                                                                                                                                                                                                                                                                                                                            'suspended'
                                                                                                                                                                                                                                                                                                                                                                                                              ) then
                                                                                                                                                                                                                                                                                                                                                                                                                  raise exception 'Invalid decision';
                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                      select *
                                                                                                                                                                                                                                                                                                                                                                                                                        into v_request
                                                                                                                                                                                                                                                                                                                                                                                                                          from public.app_verification_requests
                                                                                                                                                                                                                                                                                                                                                                                                                            where id = p_request_id;

                                                                                                                                                                                                                                                                                                                                                                                                                              if not found then
                                                                                                                                                                                                                                                                                                                                                                                                                                  raise exception 'Verification request not found';
                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                      update public.app_verification_requests
                                                                                                                                                                                                                                                                                                                                                                                                                                        set
                                                                                                                                                                                                                                                                                                                                                                                                                                            status = p_decision,
                                                                                                                                                                                                                                                                                                                                                                                                                                                reviewer_user_id = v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                    reviewer_notes = p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                        checklist = coalesce(checklist, '{}'::jsonb) || coalesce(p_checklist_patch, '{}'::jsonb),
                                                                                                                                                                                                                                                                                                                                                                                                                                                            reviewed_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                published_at = case when p_decision = 'published' then now() else published_at end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                      where id = p_request_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        update public.app_store_apps
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          set
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              status = p_decision,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  enabled = case
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        when p_decision = 'published' then true
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              when p_decision in ('changes_requested', 'rejected', 'suspended') then false
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    else enabled
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        end,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            review_notes = p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                published_at = case when p_decision = 'published' then now() else published_at end
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  where id = v_request.app_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    insert into public.app_verification_events (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        request_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            app_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    event_type,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            payload
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                values (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_request_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        v_request.app_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p_decision,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        jsonb_build_object('checklist_patch', p_checklist_patch)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            insert into public.app_audit_logs (user_id, app_id, event_type, event)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              values (
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_request.app_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'verification_' || p_decision,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              jsonb_build_object('request_id', p_request_id, 'note', p_note)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  return true;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  $$;


ALTER FUNCTION "public"."mtaa_review_app_verification"("p_request_id" "uuid", "p_decision" "text", "p_note" "text", "p_checklist_patch" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_safe_exec"("sql" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  EXECUTE sql;
EXCEPTION WHEN undefined_table THEN
  RAISE NOTICE 'Skipping missing table operation: %', sql;
END;
$$;


ALTER FUNCTION "public"."mtaa_safe_exec"("sql" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_scan_pay"("p_qr_id" "uuid", "p_amount" numeric, "p_module" "text" DEFAULT 'wallet'::"text", "p_payload" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                                                                                                                                                                                                                                                                                declare
                                                                                                                                                                                                                                                                                                                                                                  v_payer uuid := auth.uid();
                                                                                                                                                                                                                                                                                                                                                                    v_receiver uuid;
                                                                                                                                                                                                                                                                                                                                                                      v_qr record;
                                                                                                                                                                                                                                                                                                                                                                        v_amount numeric := coalesce(p_amount, 0);
                                                                                                                                                                                                                                                                                                                                                                          v_scan_id uuid;
                                                                                                                                                                                                                                                                                                                                                                            v_now timestamptz := now();
                                                                                                                                                                                                                                                                                                                                                                              v_payer_balance numeric;
                                                                                                                                                                                                                                                                                                                                                                              begin
                                                                                                                                                                                                                                                                                                                                                                                if v_payer is null then
                                                                                                                                                                                                                                                                                                                                                                                    raise exception 'Not authenticated';
                                                                                                                                                                                                                                                                                                                                                                                      end if;

                                                                                                                                                                                                                                                                                                                                                                                        if v_amount <= 0 then
                                                                                                                                                                                                                                                                                                                                                                                            raise exception 'Amount must be > 0';
                                                                                                                                                                                                                                                                                                                                                                                              end if;

                                                                                                                                                                                                                                                                                                                                                                                                -- lock qr row
                                                                                                                                                                                                                                                                                                                                                                                                  select *
                                                                                                                                                                                                                                                                                                                                                                                                      into v_qr
                                                                                                                                                                                                                                                                                                                                                                                                        from public.qr_codes
                                                                                                                                                                                                                                                                                                                                                                                                          where id = p_qr_id
                                                                                                                                                                                                                                                                                                                                                                                                            for update;

                                                                                                                                                                                                                                                                                                                                                                                                              if v_qr.id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                  raise exception 'Invalid QR';
                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                      if v_qr.active is not true then
                                                                                                                                                                                                                                                                                                                                                                                                                          raise exception 'QR inactive';
                                                                                                                                                                                                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                                                                                                                                                                                                              if v_qr.expires_at is not null and v_qr.expires_at < now() then
                                                                                                                                                                                                                                                                                                                                                                                                                                  raise exception 'QR expired';
                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                      -- receiver is qr owner
                                                                                                                                                                                                                                                                                                                                                                                                                                        v_receiver := v_qr.owner_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                          if v_receiver is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                              -- fallback: reference_id as receiver uid
                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_receiver := v_qr.reference_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                      if v_receiver is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                          raise exception 'QR has no receiver';
                                                                                                                                                                                                                                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                              if v_receiver = v_payer then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                  raise exception 'Cannot pay yourself';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                      -- ensure wallet accounts exist for both sides
                                                                                                                                                                                                                                                                                                                                                                                                                                                                        perform public.mtaa_ensure_wallet_account();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                          -- receiver
                                                                                                                                                                                                                                                                                                                                                                                                                                                                            insert into public.profiles (id, created_at, updated_at)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                              values (v_receiver, now(), now())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                on conflict (id) do nothing;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.wallet_accounts (user_id, balance, updated_at)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    values (v_receiver, 0, now())
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      on conflict (user_id) do nothing;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        -- lock payer account row
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          select balance
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              into v_payer_balance
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                from public.wallet_accounts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  where user_id = v_payer
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    for update;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      if v_payer_balance is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          raise exception 'Wallet account missing';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              if v_payer_balance < v_amount then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  raise exception 'Insufficient balance';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      -- create scan record first (pending)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        insert into public.wallet_scans (user_id, module, action, amount, reference_id, payload, status, created_at)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          values (v_payer, coalesce(p_module,'wallet'), 'scan_pay', v_amount, v_receiver, p_payload, 'pending', v_now)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            returning id into v_scan_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -- update balances
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                update public.wallet_accounts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    set balance = balance - v_amount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      where user_id = v_payer;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        update public.wallet_accounts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            set balance = balance + v_amount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              where user_id = v_receiver;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                -- ledger transactions (for audit + notifications)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  insert into public.wallet_transactions (user_id, amount, type, created_at)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    values
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (v_payer,    v_amount, 'scan_pay_debit',  v_now),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            (v_receiver, v_amount, 'scan_pay_credit', v_now);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              -- mark scan completed
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                update public.wallet_scans
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    set status = 'completed',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            completed_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              where id = v_scan_id;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'ok', true,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'scan_id', v_scan_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'payer_id', v_payer,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'receiver_id', v_receiver,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'amount', v_amount
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      $$;


ALTER FUNCTION "public"."mtaa_scan_pay"("p_qr_id" "uuid", "p_amount" numeric, "p_module" "text", "p_payload" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_send_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract sent'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                          begin
                                                                            update public.service_contracts
                                                                              set
                                                                                  status = case
                                                                                        when escrow_account_id is not null then 'pending_funding'
                                                                                              else 'draft'
                                                                                                  end,
                                                                                                      metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                                                                                                          updated_at = now()
                                                                                                            where id = p_contract_id;

                                                                                                              perform public.mtaa_add_service_contract_event(
                                                                                                                  p_contract_id,
                                                                                                                      'contract_sent',
                                                                                                                          p_actor_user_id,
                                                                                                                              p_note,
                                                                                                                                  coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                    );

                                                                                                                                      return p_contract_id;
                                                                                                                                      end;
                                                                                                                                      $$;


ALTER FUNCTION "public"."mtaa_send_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_set_app_badge_count"("p_app_id" "uuid", "p_badge_count" integer) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                          declare
                                                                                                            v_user_id uuid := auth.uid();
                                                                                                            begin
                                                                                                              update public.app_installations
                                                                                                                set badge_count = greatest(coalesce(p_badge_count, 0), 0)
                                                                                                                  where user_id = v_user_id
                                                                                                                      and app_id = p_app_id;

                                                                                                                        return true;
                                                                                                                        end;
                                                                                                                        $$;


ALTER FUNCTION "public"."mtaa_set_app_badge_count"("p_app_id" "uuid", "p_badge_count" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_set_app_hidden"("p_app_id" "uuid", "p_hidden" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                  declare
                                                                                                                                                                                                                    v_user_id uuid := auth.uid();
                                                                                                                                                                                                                    begin
                                                                                                                                                                                                                      update public.app_installations
                                                                                                                                                                                                                        set is_hidden = p_hidden
                                                                                                                                                                                                                          where user_id = v_user_id and app_id = p_app_id;

                                                                                                                                                                                                                            return true;
                                                                                                                                                                                                                            end;
                                                                                                                                                                                                                            $$;


ALTER FUNCTION "public"."mtaa_set_app_hidden"("p_app_id" "uuid", "p_hidden" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_set_app_pin"("p_app_id" "uuid", "p_pinned" boolean) RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                    declare
                                                                                                                                                                                                      v_user_id uuid := auth.uid();
                                                                                                                                                                                                      begin
                                                                                                                                                                                                        update public.app_installations
                                                                                                                                                                                                          set pinned = p_pinned
                                                                                                                                                                                                            where user_id = v_user_id and app_id = p_app_id;

                                                                                                                                                                                                              return true;
                                                                                                                                                                                                              end;
                                                                                                                                                                                                              $$;


ALTER FUNCTION "public"."mtaa_set_app_pin"("p_app_id" "uuid", "p_pinned" boolean) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_set_post_music"("p_post_id" "uuid", "p_track_id" "uuid", "p_start_second" integer DEFAULT 0, "p_end_second" integer DEFAULT NULL::integer, "p_volume_music" numeric DEFAULT 1.0, "p_volume_video" numeric DEFAULT 1.0) RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                          declare
                                                            v_owner uuid;
                                                              v_music jsonb;
                                                              begin
                                                                select user_id into v_owner from public.posts where id = p_post_id;
                                                                  if v_owner is null then
                                                                      raise exception 'post not found';
                                                                        end if;

                                                                          if auth.uid() is distinct from v_owner then
                                                                              raise exception 'not allowed';
                                                                                end if;

                                                                                  perform public.mtaa_ensure_music_stats(p_track_id);

                                                                                    insert into public.post_tracks_usage(post_id, track_id, start_second, end_second, volume_music, volume_video)
                                                                                      values (p_post_id, p_track_id, greatest(coalesce(p_start_second,0),0), p_end_second, coalesce(p_volume_music,1.0), coalesce(p_volume_video,1.0))
                                                                                        on conflict (post_id) do update set
                                                                                            track_id = excluded.track_id,
                                                                                                start_second = excluded.start_second,
                                                                                                    end_second = excluded.end_second,
                                                                                                        volume_music = excluded.volume_music,
                                                                                                            volume_video = excluded.volume_video,
                                                                                                                created_at = now();

                                                                                                                  v_music := jsonb_build_object(
                                                                                                                      'trackId', p_track_id,
                                                                                                                          'startSecond', greatest(coalesce(p_start_second,0),0),
                                                                                                                              'endSecond', p_end_second,
                                                                                                                                  'volumeMusic', coalesce(p_volume_music,1.0),
                                                                                                                                      'volumeVideo', coalesce(p_volume_video,1.0)
                                                                                                                                        );

                                                                                                                                          update public.posts
                                                                                                                                            set edits_json = jsonb_set(coalesce(edits_json, '{}'::jsonb), '{music}', v_music, true)
                                                                                                                                              where id = p_post_id;
                                                                                                                                              end;
                                                                                                                                              $$;


ALTER FUNCTION "public"."mtaa_set_post_music"("p_post_id" "uuid", "p_track_id" "uuid", "p_start_second" integer, "p_end_second" integer, "p_volume_music" numeric, "p_volume_video" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_set_updated_at"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin
  new.updated_at = now();
    return new;
    end;
    $$;


ALTER FUNCTION "public"."mtaa_set_updated_at"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_shop_wallet_checkout"("p_order_id" "uuid", "p_shop_id" "uuid", "p_amount" numeric) RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                        declare
                                          v_buyer_id uuid;
                                            v_seller_id uuid;
                                              v_buyer_wallet_id uuid;
                                                v_seller_wallet_id uuid;
                                                  v_buyer_balance numeric;
                                                    v_seller_balance numeric;
                                                    begin
                                                      -- caller must be authenticated
                                                        v_buyer_id := auth.uid();
                                                          if v_buyer_id is null then
                                                              raise exception 'Not authenticated';
                                                                end if;

                                                                  if p_amount is null or p_amount <= 0 then
                                                                      raise exception 'Invalid amount';
                                                                        end if;

                                                                          -- find seller (shop owner)
                                                                            select s.user_id into v_seller_id
                                                                              from public.shops s
                                                                                where s.id = p_shop_id;

                                                                                  if v_seller_id is null then
                                                                                      raise exception 'Shop owner not set (shops.user_id is null) for shop %', p_shop_id;
                                                                                        end if;

                                                                                          -- lock buyer wallet row
                                                                                            select w.id, w.balance
                                                                                              into v_buyer_wallet_id, v_buyer_balance
                                                                                                from public.wallets w
                                                                                                  where w.owner_id = v_buyer_id
                                                                                                    for update;

                                                                                                      if v_buyer_wallet_id is null then
                                                                                                          raise exception 'Buyer wallet not found (wallets.owner_id=%)', v_buyer_id;
                                                                                                            end if;

                                                                                                              if v_buyer_balance < p_amount then
                                                                                                                  raise exception 'Insufficient balance';
                                                                                                                    end if;

                                                                                                                      -- lock seller wallet row
                                                                                                                        select w.id, w.balance
                                                                                                                          into v_seller_wallet_id, v_seller_balance
                                                                                                                            from public.wallets w
                                                                                                                              where w.owner_id = v_seller_id
                                                                                                                                for update;

                                                                                                                                  if v_seller_wallet_id is null then
                                                                                                                                      raise exception 'Seller wallet not found (wallets.owner_id=%)', v_seller_id;
                                                                                                                                        end if;

                                                                                                                                          -- apply balances
                                                                                                                                            update public.wallets
                                                                                                                                                set balance = balance - p_amount,
                                                                                                                                                        updated_at = now()
                                                                                                                                                          where id = v_buyer_wallet_id;

                                                                                                                                                            update public.wallets
                                                                                                                                                                set balance = balance + p_amount,
                                                                                                                                                                        updated_at = now()
                                                                                                                                                                          where id = v_seller_wallet_id;

                                                                                                                                                                            -- record simplified transactions (schema only supports user_id/amount/type)
                                                                                                                                                                              insert into public.wallet_transactions(user_id, amount, type)
                                                                                                                                                                                values (v_buyer_id, -p_amount, 'transfer_out');  -- allowed by CHECK :contentReference[oaicite:8]{index=8}

                                                                                                                                                                                  insert into public.wallet_transactions(user_id, amount, type)
                                                                                                                                                                                    values (v_seller_id,  p_amount, 'transfer_in');  -- allowed by CHECK :contentReference[oaicite:9]{index=9}

                                                                                                                                                                                      -- record order-linked scan logs (reference_id exists here)
                                                                                                                                                                                        insert into public.wallet_scans(user_id, module, action, amount, reference_id, payload, status, completed_at)
                                                                                                                                                                                          values (
                                                                                                                                                                                              v_buyer_id,
                                                                                                                                                                                                  'shop',
                                                                                                                                                                                                      'order_pay',
                                                                                                                                                                                                          p_amount,
                                                                                                                                                                                                              p_order_id,
                                                                                                                                                                                                                  jsonb_build_object('shop_id', p_shop_id, 'to_user', v_seller_id),
                                                                                                                                                                                                                      'completed',
                                                                                                                                                                                                                          now()
                                                                                                                                                                                                                            );

                                                                                                                                                                                                                              insert into public.wallet_scans(user_id, module, action, amount, reference_id, payload, status, completed_at)
                                                                                                                                                                                                                                values (
                                                                                                                                                                                                                                    v_seller_id,
                                                                                                                                                                                                                                        'shop',
                                                                                                                                                                                                                                            'order_receive',
                                                                                                                                                                                                                                                p_amount,
                                                                                                                                                                                                                                                    p_order_id,
                                                                                                                                                                                                                                                        jsonb_build_object('shop_id', p_shop_id, 'from_user', v_buyer_id),
                                                                                                                                                                                                                                                            'completed',
                                                                                                                                                                                                                                                                now()
                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                    return jsonb_build_object(
                                                                                                                                                                                                                                                                        'ok', true,
                                                                                                                                                                                                                                                                            'buyer_id', v_buyer_id,
                                                                                                                                                                                                                                                                                'seller_id', v_seller_id,
                                                                                                                                                                                                                                                                                    'amount', p_amount
                                                                                                                                                                                                                                                                                      );
                                                                                                                                                                                                                                                                                      end;
                                                                                                                                                                                                                                                                                      $$;


ALTER FUNCTION "public"."mtaa_shop_wallet_checkout"("p_order_id" "uuid", "p_shop_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_start_ad_campaign"("p_campaign_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Campaign activated for billing'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_user_id uuid;
  v_currency text;
begin
  update public.ad_campaigns
  set
    status = 'active',
    billing_status = 'active',
    updated_at = now()
  where id = p_campaign_id
    and reserved_amount > 0
    and status in ('draft','pending_review','paused','active')
  returning advertiser_user_id, currency into v_user_id, v_currency;

  if v_user_id is null then
    raise exception 'Campaign not found or not funded';
  end if;

  perform public.mtaa_add_ad_billing_event(
    p_campaign_id,
    'campaign_activated',
    p_actor_user_id,
    null,
    v_currency,
    p_note,
    null,
    coalesce(p_metadata, '{}'::jsonb)
  );

  perform public.mtaa_emit_event(
    v_user_id,
    'AD_CAMPAIGN_ACTIVE',
    'advertise',
    'ad_campaigns',
    p_campaign_id,
    null,
    v_currency,
    coalesce(p_metadata, '{}'::jsonb)
  );

  return p_campaign_id;
end;
$$;


ALTER FUNCTION "public"."mtaa_start_ad_campaign"("p_campaign_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_start_deposit_processing"("p_deposit_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Deposit processing started'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  update public.wallet_deposits
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    set status = 'processing',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          processing_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                processed_by = coalesce(p_actor_user_id, processed_by),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      updated_at = now()
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        where id = p_deposit_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            and status in ('requested','pending')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              returning user_id, currency into v_user_id, v_currency;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    raise exception 'Deposit not found or not processable';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        perform public.mtaa_add_deposit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    'processing',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        'WALLET_DEPOSIT_PROCESSING',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'wallet_deposits',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    p_deposit_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return p_deposit_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    $$;


ALTER FUNCTION "public"."mtaa_start_deposit_processing"("p_deposit_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_start_payout_processing"("p_payout_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_provider_name" "text" DEFAULT NULL::"text", "p_external_reference" "text" DEFAULT NULL::"text", "p_note" "text" DEFAULT 'Payout processing started'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                declare
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  v_user_id uuid;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    v_currency text;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    begin
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      update public.wallet_payouts
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        set status = 'processing',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              processing_at = now(),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    processed_by = coalesce(p_actor_user_id, processed_by),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          provider_name = coalesce(p_provider_name, provider_name),
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                external_reference = coalesce(p_external_reference, external_reference)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  where id = p_payout_id
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      and status in ('requested','queued')
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        returning user_id, currency into v_user_id, v_currency;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          if v_user_id is null then
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              raise exception 'Payout not found or not in requestable status';
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                end if;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  perform public.mtaa_add_payout_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          p_actor_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              'processing',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  p_note,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            'provider_name', p_provider_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'external_reference', p_external_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          perform public.mtaa_emit_event(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              v_user_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  'WALLET_PAYOUT_PROCESSING',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'wallet',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          'wallet_payouts',
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              p_payout_id,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                  null,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      v_currency,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          jsonb_build_object(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                'provider_name', p_provider_name,
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                      'external_reference', p_external_reference
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                          ) || coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              return p_payout_id;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              end;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              $$;


ALTER FUNCTION "public"."mtaa_start_payout_processing"("p_payout_id" "uuid", "p_actor_user_id" "uuid", "p_provider_name" "text", "p_external_reference" "text", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_start_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid" DEFAULT NULL::"uuid", "p_note" "text" DEFAULT 'Contract started'::"text", "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                          begin
                                                                                            update public.service_contracts
                                                                                              set
                                                                                                  status = 'in_progress',
                                                                                                      metadata = coalesce(metadata, '{}'::jsonb) || coalesce(p_metadata, '{}'::jsonb),
                                                                                                          updated_at = now()
                                                                                                            where id = p_contract_id;

                                                                                                              perform public.mtaa_add_service_contract_event(
                                                                                                                  p_contract_id,
                                                                                                                      'contract_started',
                                                                                                                          p_actor_user_id,
                                                                                                                              p_note,
                                                                                                                                  coalesce(p_metadata, '{}'::jsonb)
                                                                                                                                    );

                                                                                                                                      return p_contract_id;
                                                                                                                                      end;
                                                                                                                                      $$;


ALTER FUNCTION "public"."mtaa_start_service_contract"("p_contract_id" "uuid", "p_actor_user_id" "uuid", "p_note" "text", "p_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_submit_app_verification"("p_app_id" "uuid", "p_submission_notes" "text" DEFAULT NULL::"text", "p_assets" "jsonb" DEFAULT '[]'::"jsonb", "p_checklist" "jsonb" DEFAULT '{}'::"jsonb", "p_external_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                  declare
                                                                                                                    v_user_id uuid := auth.uid();
                                                                                                                      v_request_id uuid;
                                                                                                                        v_app record;
                                                                                                                        begin
                                                                                                                          select *
                                                                                                                            into v_app
                                                                                                                              from public.app_store_apps
                                                                                                                                where id = p_app_id;

                                                                                                                                  if not found then
                                                                                                                                      raise exception 'App not found';
                                                                                                                                        end if;

                                                                                                                                          if v_app.publisher_user_id <> v_user_id then
                                                                                                                                              raise exception 'Only the publisher can submit this app';
                                                                                                                                                end if;

                                                                                                                                                  insert into public.app_verification_requests (
                                                                                                                                                      app_id,
                                                                                                                                                          publisher_user_id,
                                                                                                                                                              submitted_by,
                                                                                                                                                                  reviewer_user_id,
                                                                                                                                                                      current_version,
                                                                                                                                                                          status,
                                                                                                                                                                              submission_notes,
                                                                                                                                                                                  reviewer_notes,
                                                                                                                                                                                      checklist,
                                                                                                                                                                                          assets,
                                                                                                                                                                                              external_metadata
                                                                                                                                                                                                )
                                                                                                                                                                                                  values (
                                                                                                                                                                                                      p_app_id,
                                                                                                                                                                                                          v_app.publisher_user_id,
                                                                                                                                                                                                              v_user_id,
                                                                                                                                                                                                                  null,
                                                                                                                                                                                                                      v_app.version,
                                                                                                                                                                                                                          'submitted',
                                                                                                                                                                                                                              p_submission_notes,
                                                                                                                                                                                                                                  null,
                                                                                                                                                                                                                                      p_checklist,
                                                                                                                                                                                                                                          p_assets,
                                                                                                                                                                                                                                              p_external_metadata
                                                                                                                                                                                                                                                )
                                                                                                                                                                                                                                                  returning id into v_request_id;

                                                                                                                                                                                                                                                    update public.app_store_apps
                                                                                                                                                                                                                                                      set status = 'submitted'
                                                                                                                                                                                                                                                        where id = p_app_id;

                                                                                                                                                                                                                                                          insert into public.app_verification_events (
                                                                                                                                                                                                                                                              request_id,
                                                                                                                                                                                                                                                                  app_id,
                                                                                                                                                                                                                                                                      actor_user_id,
                                                                                                                                                                                                                                                                          event_type,
                                                                                                                                                                                                                                                                              note,
                                                                                                                                                                                                                                                                                  payload
                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                      values (
                                                                                                                                                                                                                                                                                          v_request_id,
                                                                                                                                                                                                                                                                                              p_app_id,
                                                                                                                                                                                                                                                                                                  v_user_id,
                                                                                                                                                                                                                                                                                                      'submitted',
                                                                                                                                                                                                                                                                                                          p_submission_notes,
                                                                                                                                                                                                                                                                                                              jsonb_build_object(
                                                                                                                                                                                                                                                                                                                    'assets', p_assets,
                                                                                                                                                                                                                                                                                                                          'checklist', p_checklist,
                                                                                                                                                                                                                                                                                                                                'external_metadata', p_external_metadata
                                                                                                                                                                                                                                                                                                                                    )
                                                                                                                                                                                                                                                                                                                                      );

                                                                                                                                                                                                                                                                                                                                        insert into public.app_audit_logs (user_id, app_id, event_type, event)
                                                                                                                                                                                                                                                                                                                                          values (
                                                                                                                                                                                                                                                                                                                                              v_user_id,
                                                                                                                                                                                                                                                                                                                                                  p_app_id,
                                                                                                                                                                                                                                                                                                                                                      'verification_submitted',
                                                                                                                                                                                                                                                                                                                                                          jsonb_build_object('request_id', v_request_id)
                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                              return v_request_id;
                                                                                                                                                                                                                                                                                                                                                              end;
                                                                                                                                                                                                                                                                                                                                                              $$;


ALTER FUNCTION "public"."mtaa_submit_app_verification"("p_app_id" "uuid", "p_submission_notes" "text", "p_assets" "jsonb", "p_checklist" "jsonb", "p_external_metadata" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_touch_app_open"("p_app_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                                                                                                                                                              declare
                                                                                                                                                                                                                                v_user_id uuid := auth.uid();
                                                                                                                                                                                                                                begin
                                                                                                                                                                                                                                  update public.app_installations
                                                                                                                                                                                                                                    set last_opened_at = now(),
                                                                                                                                                                                                                                          open_count = coalesce(open_count, 0) + 1
                                                                                                                                                                                                                                            where user_id = v_user_id and app_id = p_app_id;

                                                                                                                                                                                                                                              insert into public.app_audit_logs (user_id, app_id, event_type, event)
                                                                                                                                                                                                                                                values (v_user_id, p_app_id, 'open', '{}'::jsonb);

                                                                                                                                                                                                                                                  return true;
                                                                                                                                                                                                                                                  end;
                                                                                                                                                                                                                                                  $$;


ALTER FUNCTION "public"."mtaa_touch_app_open"("p_app_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_touch_wallet_account"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                                                                          begin
                                                                                                                                                                                                                                                                                            new.updated_at := now();
                                                                                                                                                                                                                                                                                              return new;
                                                                                                                                                                                                                                                                                              end;
                                                                                                                                                                                                                                                                                              $$;


ALTER FUNCTION "public"."mtaa_touch_wallet_account"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaa_truck_set_status"("p_order_id" "uuid", "p_status" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                              declare v_driver uuid;
                                                                                                              declare v_curr text;
                                                                                                              begin
                                                                                                                if auth.uid() is null then raise exception 'Auth required'; end if;

                                                                                                                  select driver_id, status into v_driver, v_curr
                                                                                                                    from public.truck_orders
                                                                                                                      where id = p_order_id
                                                                                                                        for update;

                                                                                                                          if v_driver is null then raise exception 'No driver assigned'; end if;
                                                                                                                            if v_driver <> auth.uid() then raise exception 'Only assigned driver can update status'; end if;

                                                                                                                              if not public.mtaa_has_verified_truck_vehicle() then
                                                                                                                                  raise exception 'Truck vehicle verification required to operate truck orders';
                                                                                                                                    end if;

                                                                                                                                      if p_status not in ('in_transit','completed') then
                                                                                                                                          raise exception 'Invalid status transition';
                                                                                                                                            end if;

                                                                                                                                              if v_curr = 'cancelled' then raise exception 'Order cancelled'; end if;
                                                                                                                                                if v_curr = 'completed' then raise exception 'Order already completed'; end if;
                                                                                                                                                  if v_curr = 'requested' then raise exception 'Order not accepted yet'; end if;

                                                                                                                                                    if v_curr = 'accepted' and p_status = 'completed' then
                                                                                                                                                        raise exception 'Must go in_transit before completing';
                                                                                                                                                          end if;

                                                                                                                                                            update public.truck_orders
                                                                                                                                                              set status = p_status,
                                                                                                                                                                    updated_at = now()
                                                                                                                                                                      where id = p_order_id;
                                                                                                                                                                      end;
                                                                                                                                                                      $$;


