CREATE OR REPLACE FUNCTION "public"."mtaa_update_reputation"("p_user" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
                  declare
                    tc int;
                      cc int;
                        comp int;
                          score numeric;
                          begin

                            select tasks_completed,cancellations,complaints
                              into tc,cc,comp
                                from public.mtaa_worker_reputation
                                  where user_id=p_user;

                                    score := 100-(cc*5)-(comp*10);

                                      update public.mtaa_worker_reputation
                                        set reputation_score=score,
                                              updated_at=now()
                                                where user_id=p_user;

                                                end;
                                                $$;


