CREATE OR REPLACE FUNCTION "public"."mtaa_upsert_work_preferences"("p_work_profile_id" "uuid", "p_preferred_job_types" "text"[] DEFAULT '{}'::"text"[], "p_preferred_work_modes" "text"[] DEFAULT '{}'::"text"[], "p_preferred_locations" "text"[] DEFAULT '{}'::"text"[], "p_min_pay_amount" numeric DEFAULT NULL::numeric, "p_max_pay_amount" numeric DEFAULT NULL::numeric, "p_pay_currency" "text" DEFAULT 'KES'::"text", "p_available_for_travel" boolean DEFAULT false, "p_open_to_relocation" boolean DEFAULT false, "p_metadata" "jsonb" DEFAULT '{}'::"jsonb") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                    declare
                      v_id uuid;
                      begin
                        insert into public.work_preferences (
                            work_profile_id,
                                preferred_job_types,
                                    preferred_work_modes,
                                        preferred_locations,
                                            min_pay_amount,
                                                max_pay_amount,
                                                    pay_currency,
                                                        available_for_travel,
                                                            open_to_relocation,
                                                                metadata
                                                                  ) values (
                                                                      p_work_profile_id,
                                                                          coalesce(p_preferred_job_types, '{}'),
                                                                              coalesce(p_preferred_work_modes, '{}'),
                                                                                  coalesce(p_preferred_locations, '{}'),
                                                                                      p_min_pay_amount,
                                                                                          p_max_pay_amount,
                                                                                              p_pay_currency,
                                                                                                  coalesce(p_available_for_travel, false),
                                                                                                      coalesce(p_open_to_relocation, false),
                                                                                                          coalesce(p_metadata, '{}'::jsonb)
                                                                                                            )
                                                                                                              on conflict (work_profile_id)
                                                                                                                do update set
                                                                                                                    preferred_job_types = excluded.preferred_job_types,
                                                                                                                        preferred_work_modes = excluded.preferred_work_modes,
                                                                                                                            preferred_locations = excluded.preferred_locations,
                                                                                                                                min_pay_amount = excluded.min_pay_amount,
                                                                                                                                    max_pay_amount = excluded.max_pay_amount,
                                                                                                                                        pay_currency = excluded.pay_currency,
                                                                                                                                            available_for_travel = excluded.available_for_travel,
                                                                                                                                                open_to_relocation = excluded.open_to_relocation,
                                                                                                                                                    metadata = public.work_preferences.metadata || excluded.metadata,
                                                                                                                                                        updated_at = now()
                                                                                                                                                          returning id into v_id;

                                                                                                                                                            return v_id;
                                                                                                                                                            end;
                                                                                                                                                            $$;


