CREATE OR REPLACE FUNCTION "public"."mtaxi_calculate_zone_demand"() RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
            declare
              z record;
                d_count int;
                  drv_count int;
                    score numeric;
                    begin

                      for z in select * from public.mtaxi_service_zones where active = true loop

                          select count(*) into d_count
                              from public.mtaxi_rides
                                  where status = 'searching'
                                      and pickup_lat between (z.center_lat - 0.02) and (z.center_lat + 0.02)
                                          and pickup_lng between (z.center_lng - 0.02) and (z.center_lng + 0.02);

                                              select count(*) into drv_count
                                                  from public.mtaxi_driver_status
                                                      where online = true
                                                          and current_lat between (z.center_lat - 0.02) and (z.center_lat + 0.02)
                                                              and current_lng between (z.center_lng - 0.02) and (z.center_lng + 0.02);

                                                                  if drv_count = 0 then
                                                                        score := d_count * 2;
                                                                            else
                                                                                  score := d_count::numeric / drv_count;
                                                                                      end if;

                                                                                          insert into public.mtaxi_zone_demand (
                                                                                                zone_id,
                                                                                                      demand_count,
                                                                                                            driver_count,
                                                                                                                  demand_score
                                                                                                                      )
                                                                                                                          values (
                                                                                                                                z.id,
                                                                                                                                      d_count,
                                                                                                                                            drv_count,
                                                                                                                                                  score
                                                                                                                                                      );

                                                                                                                                                        end loop;

                                                                                                                                                        end;
                                                                                                                                                        $$;


ALTER FUNCTION "public"."mtaxi_calculate_zone_demand"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaxi_check_driver_vehicle"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
declare
  v_status text;
  begin

    if NEW.online = true then

        select inspection_status
            into v_status
                from public.mtaxi_vehicles
                    where user_id = NEW.user_id
                        limit 1;

                            if v_status is null then
                                  raise exception 'Driver has no registered vehicle';
                                      end if;

                                          if v_status <> 'approved' then
                                                raise exception 'Vehicle inspection not approved';
                                                    end if;

                                                      end if;

                                                        return NEW;

                                                        end;
                                                        $$;


ALTER FUNCTION "public"."mtaxi_check_driver_vehicle"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaxi_compute_surge"("demand" integer, "supply" integer) RETURNS numeric
    LANGUAGE "plpgsql"
    AS $$
      declare
        surge numeric := 1.0;
        begin
          if supply = 0 then
              return 2.5; -- max surge
                end if;

                  if demand::numeric / supply > 2 then
                      surge := 2.0;
                        elsif demand::numeric / supply > 1.5 then
                            surge := 1.5;
                              elsif demand::numeric / supply > 1.2 then
                                  surge := 1.2;
                                    else
                                        surge := 1.0;
                                          end if;

                                            return surge;
                                            end;
                                            $$;


ALTER FUNCTION "public"."mtaxi_compute_surge"("demand" integer, "supply" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."mtaxi_detect_gps_spoof"("p_driver" "uuid", "p_lat" numeric, "p_lng" numeric) RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
                  declare
                    last_lat numeric;
                      last_lng numeric;
                        last_time timestamptz;
                          distance numeric;
                            seconds_passed numeric;
                              speed_kmh numeric;
                              begin

                                select lat, lng, recorded_at
                                  into last_lat, last_lng, last_time
                                    from public.mtaxi_driver_location_history
                                      where driver_id = p_driver
                                        order by recorded_at desc
                                          limit 1;

                                            if last_time is null then
                                                return false;
                                                  end if;

                                                    distance := sqrt(power(p_lat - last_lat,2) + power(p_lng - last_lng,2)) * 111;
                                                      seconds_passed := extract(epoch from (now() - last_time));

                                                        if seconds_passed = 0 then
                                                            return false;
                                                              end if;

                                                                speed_kmh := (distance / seconds_passed) * 3600;

                                                                  if speed_kmh > 180 then
                                                                      return true;
                                                                        end if;

                                                                          return false;

                                                                          end;
                                                                          $$;


ALTER FUNCTION "public"."mtaxi_detect_gps_spoof"("p_driver" "uuid", "p_lat" numeric, "p_lng" numeric) OWNER TO "postgres";


