CREATE OR REPLACE FUNCTION "public"."mtaxi_zone_heat_level"("score" numeric) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                        begin

                                                                                                                                                          if score >= 2 then
                                                                                                                                                              return 'red';
                                                                                                                                                                elsif score >= 1.2 then
                                                                                                                                                                    return 'orange';
                                                                                                                                                                      elsif score >= 0.8 then
                                                                                                                                                                          return 'yellow';
                                                                                                                                                                            else
                                                                                                                                                                                return 'green';
                                                                                                                                                                                  end if;

                                                                                                                                                                                  end;
                                                                                                                                                                                  $$;


