CREATE OR REPLACE FUNCTION "public"."notify_live_session"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
begin
  -- Only trigger when status changes
    if new.status = old.status then
        return new;
          end if;

            -- When session goes live, notify all registered users
              if new.status = 'live' then
                  perform public.emit_notification(
                        r.user_id,             -- target user_id
                              new.host_user_id,      -- actor (host)
                                    'live_session_started',
                                          'live',
                                                new.id,
                                                      'Live Session Started',
                                                            'A live session you registered for has started!',
                                                                  '/live/' || new.id,
                                                                        jsonb_build_object(
                                                                                'session_id', new.id,
                                                                                        'host_user_id', new.host_user_id,
                                                                                                'title', new.title
                                                                                                      )
                                                                                                          )
                                                                                                              from public.live_session_registrations r
                                                                                                                  where r.live_session_id = new.id;
