CREATE OR REPLACE FUNCTION "public"."notify_on_milestone_status_change"() RETURNS "trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare
  v_employer_user_id uuid;
  begin
    -- Only react if status actually changed
      if new.status = old.status then
          return new;
            end if;

              -- Get employer (job owner)
                select j.user_id
                  into v_employer_user_id
                    from public.jobs j
                      where j.id = new.job_id;

                        -- MILESTONE SUBMITTED (worker → employer)
                          if new.status = 'submitted' then
                              perform public.emit_notification(
                                    v_employer_user_id,      -- target (employer)
                                          new.user_id,             -- actor (worker)
                                                'milestone_submitted',
                                                      'jobs',
                                                            new.id,
                                                                  'Milestone submitted',
                                                                        'A milestone has been submitted for your review.',
                                                                              '/jobs/' || new.job_id || '/milestones',
                                                                                    jsonb_build_object(
                                                                                            'job_id', new.job_id,
                                                                                                    'milestone_id', new.id,
                                                                                                            'amount', new.amount
                                                                                                                  )
                                                                                                                      );
                                                                                                                        end if;

                                                                                                                          -- MILESTONE APPROVED (employer → worker)
                                                                                                                            if new.status = 'approved' then
                                                                                                                                perform public.emit_notification(
                                                                                                                                      new.user_id,             -- target (worker)
                                                                                                                                            v_employer_user_id,      -- actor (employer)
                                                                                                                                                  'milestone_approved',
                                                                                                                                                        'jobs',
                                                                                                                                                              new.id,
                                                                                                                                                                    'Milestone approved 🎉',
                                                                                                                                                                          'Your milestone has been approved.',
                                                                                                                                                                                '/jobs/' || new.job_id || '/milestones',
                                                                                                                                                                                      jsonb_build_object(
                                                                                                                                                                                              'job_id', new.job_id,
                                                                                                                                                                                                      'milestone_id', new.id,
                                                                                                                                                                                                              'amount', new.amount
                                                                                                                                                                                                                    )
                                                                                                                                                                                                                        );
                                                                                                                                                                                                                          end if;

                                                                                                                                                                                                                            -- MILESTONE RELEASED (employer → worker)
                                                                                                                                                                                                                              if new.status = 'released' then
                                                                                                                                                                                                                                  perform public.emit_notification(
                                                                                                                                                                                                                                        new.user_id,             -- target (worker)
                                                                                                                                                                                                                                              v_employer_user_id,      -- actor (employer)
                                                                                                                                                                                                                                                    'milestone_released',
                                                                                                                                                                                                                                                          'jobs',
                                                                                                                                                                                                                                                                new.id,
                                                                                                                                                                                                                                                                      'Payment released 💰',
                                                                                                                                                                                                                                                                            'Payment for your milestone has been released.',
                                                                                                                                                                                                                                                                                  '/jobs/' || new.job_id || '/milestones',
                                                                                                                                                                                                                                                                                        jsonb_build_object(
                                                                                                                                                                                                                                                                                                'job_id', new.job_id,
                                                                                                                                                                                                                                                                                                        'milestone_id', new.id,
                                                                                                                                                                                                                                                                                                                'amount', new.amount
                                                                                                                                                                                                                                                                                                                      )
                                                                                                                                                                                                                                                                                                                          );
                                                                                                                                                                                                                                                                                                                            end if;

                                                                                                                                                                                                                                                                                                                              return new;
                                                                                                                                                                                                                                                                                                                              end;
                                                                                                                                                                                                                                                                                                                              $$;


ALTER FUNCTION "public"."notify_on_milestone_status_change"() OWNER TO "postgres";


