CREATE OR REPLACE FUNCTION "public"."purchase_lesson"("p_lesson_id" "uuid", "p_buyer_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_lesson_price numeric;
  v_staff_id uuid;
  v_teacher_share numeric;
  v_platform_fee numeric;
BEGIN
  SELECT price, staff_id INTO v_lesson_price, v_staff_id FROM education_lessons WHERE id = p_lesson_id AND is_premium = true;
  IF v_lesson_price IS NULL OR v_lesson_price <= 0 THEN RETURN false; END IF;

  v_teacher_share := v_lesson_price * 0.70;
  v_platform_fee := v_lesson_price * 0.30;

  INSERT INTO education_purchases (lesson_id, buyer_id, amount, teacher_share, platform_fee)
  VALUES (p_lesson_id, p_buyer_id, v_lesson_price, v_teacher_share, v_platform_fee);

  UPDATE education_staff SET earnings_balance = earnings_balance + v_teacher_share, total_earnings = total_earnings + v_teacher_share WHERE id = v_staff_id;

  INSERT INTO education_earnings_transactions (staff_id, lesson_id, type, amount, description)
  VALUES (v_staff_id, p_lesson_id, 'purchase', v_teacher_share, 'Premium lesson purchase');

  RETURN true;
END;
$$;


ALTER FUNCTION "public"."purchase_lesson"("p_lesson_id" "uuid", "p_buyer_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."purge_soft_deleted"("p_table_name" "text", "p_days" integer DEFAULT 7) RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  EXECUTE format(
    'DELETE FROM public.%I WHERE deleted_at < now() - interval ''1 day'' * %s',
    p_table_name, p_days
  );
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$$;


