CREATE OR REPLACE FUNCTION "public"."rail_health_check"("p_module_name" "text" DEFAULT NULL::"text") RETURNS TABLE("app_name" "text", "route_path" "text", "status" "text", "last_check_at" timestamp with time zone, "response_time_ms" integer, "error_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    r.app_name,
    r.route_path,
    COALESCE(m.status, 'unknown') as status,
    m.last_check_at,
    m.response_time_ms,
    m.error_count
  FROM public.rail_registry r
  LEFT JOIN public.rail_monitor m ON m.registry_id = r.id
  WHERE (p_module_name IS NULL OR r.module_name = p_module_name)
  AND r.is_active = true
  ORDER BY r.display_order;
END;
$$;


ALTER FUNCTION "public"."rail_health_check"("p_module_name" "text") OWNER TO "postgres";


