CREATE OR REPLACE FUNCTION "public"."record_lesson_view"("p_lesson_id" "uuid", "p_viewer_id" "uuid" DEFAULT NULL::"uuid", "p_watch_duration" integer DEFAULT 0) RETURNS numeric
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_is_unique boolean;
  v_earnings numeric;
  v_staff_id uuid;
  v_existing_view uuid;
BEGIN
  IF p_viewer_id IS NOT NULL THEN
    SELECT id INTO v_existing_view FROM education_lesson_views WHERE lesson_id = p_lesson_id AND viewer_id = p_viewer_id LIMIT 1;
    v_is_unique := (v_existing_view IS NULL);
  ELSE
    v_is_unique := true;
  END IF;

  IF v_is_unique THEN v_earnings := 0.50; ELSE v_earnings := 0.10; END IF;
  SELECT staff_id INTO v_staff_id FROM education_lessons WHERE id = p_lesson_id;

  INSERT INTO education_lesson_views (lesson_id, viewer_id, watch_duration, is_unique, earnings_generated)
  VALUES (p_lesson_id, p_viewer_id, p_watch_duration, v_is_unique, v_earnings);

  UPDATE education_lessons SET views_count = views_count + 1, unique_views_count = unique_views_count + CASE WHEN v_is_unique THEN 1 ELSE 0 END, earnings_total = earnings_total + v_earnings WHERE id = p_lesson_id;

  IF v_staff_id IS NOT NULL THEN
    UPDATE education_staff SET earnings_balance = earnings_balance + v_earnings, total_earnings = total_earnings + v_earnings WHERE id = v_staff_id;
    INSERT INTO education_earnings_transactions (staff_id, lesson_id, type, amount, description)
    VALUES (v_staff_id, p_lesson_id, 'view', v_earnings, CASE WHEN v_is_unique THEN 'Unique view' ELSE 'Repeat view' END);
  END IF;

  RETURN v_earnings;
END;
$$;


ALTER FUNCTION "public"."record_lesson_view"("p_lesson_id" "uuid", "p_viewer_id" "uuid", "p_watch_duration" integer) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."refresh_dashboard_metrics"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    INSERT INTO treasury_dashboard_metrics (metric_name, metric_category, metric_value, metric_unit, fiscal_year, period, ministry_id, last_updated)
    SELECT 
        'execution_rate',
        'budget',
        ROUND(SUM(spent_amount) / NULLIF(SUM(approved_amount), 0) * 100, 2),
        'percent',
        bc.fiscal_year,
        to_char(now(), 'YYYY-MM'),
        ba.ministry_id,
        now()
    FROM treasury_budget_allocations ba
    JOIN treasury_budget_cycles bc ON ba.budget_cycle_id = bc.id
    WHERE bc.status = 'active'
    GROUP BY bc.fiscal_year, ba.ministry_id
    ON CONFLICT (metric_name, fiscal_year, period, ministry_id) 
    DO UPDATE SET metric_value = EXCLUDED.metric_value, last_updated = now();
    
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."refresh_dashboard_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_business"("p_user_id" "uuid", "p_name" "text", "p_registration_number" "text", "p_kra_pin" "text", "p_company_type" "text", "p_agpo_category" "text" DEFAULT 'none'::"text", "p_email" "text" DEFAULT NULL::"text", "p_phone" "text" DEFAULT NULL::"text", "p_physical_address" "text" DEFAULT NULL::"text", "p_county" "text" DEFAULT NULL::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_business_id uuid;
    v_wallet_id uuid;
BEGIN
    IF EXISTS (SELECT 1 FROM civic_contractors WHERE kra_pin = p_kra_pin) THEN
        RAISE EXCEPTION 'KRA PIN already registered';
    END IF;

    IF EXISTS (SELECT 1 FROM civic_contractors WHERE registration_number = p_registration_number) THEN
        RAISE EXCEPTION 'Registration number already exists';
    END IF;

    INSERT INTO civic_contractors (
        name, registration_number, kra_pin, company_type, agpo_category,
        agpo_certified, company_score, tax_compliant, email, phone,
        physical_address, county, created_by, blacklist_status
    ) VALUES (
        p_name, p_registration_number, p_kra_pin, p_company_type, p_agpo_category,
        false, 50, false, p_email, p_phone, p_physical_address, p_county, p_user_id, 'clear'
    ) RETURNING id INTO v_business_id;

    SELECT id INTO v_wallet_id FROM wallets WHERE user_id = p_user_id;
    IF v_wallet_id IS NOT NULL THEN
        INSERT INTO wallet_ledger (wallet_id, type, amount, balance_after, description, reference_id)
        VALUES (v_wallet_id, 'debit', 0, (SELECT balance FROM wallets WHERE id = v_wallet_id), 'Business registration fee', v_business_id);
    END IF;

    INSERT INTO identity_verification_logs (user_id, event_type, event_data)
    VALUES (p_user_id, 'kyc_submitted', jsonb_build_object('business_id', v_business_id, 'action', 'business_registered'));

    RETURN v_business_id;
END;
$$;


ALTER FUNCTION "public"."register_business"("p_user_id" "uuid", "p_name" "text", "p_registration_number" "text", "p_kra_pin" "text", "p_company_type" "text", "p_agpo_category" "text", "p_email" "text", "p_phone" "text", "p_physical_address" "text", "p_county" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_health_facility"("p_name" "text", "p_type" "text", "p_ownership" "text", "p_level" integer, "p_country" "text", "p_county" "text", "p_town" "text", "p_address" "text", "p_phone" "text", "p_email" "text", "p_bed_capacity" integer, "p_specialties" "text"[], "p_services" "text"[], "p_founder_name" "text", "p_founder_id_number" "text", "p_founder_phone" "text", "p_founder_email" "text", "p_license_number" "text", "p_license_body" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_founder_id UUID := auth.uid();
  v_registration_id UUID;
BEGIN
  IF v_founder_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Authentication required');
  END IF;

  IF p_name IS NULL OR p_name = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Facility name is required');
  END IF;

  IF p_phone IS NULL OR p_phone = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Phone number is required');
  END IF;

  INSERT INTO health_facility_registrations (
    name, type, ownership, level, country, county, town, address,
    phone, email, bed_capacity, specialties, services,
    founder_user_id, founder_name, founder_id_number, founder_phone, founder_email,
    license_number, license_body, status, submitted_at
  ) VALUES (
    p_name, p_type, p_ownership, p_level, p_country, p_county, p_town, p_address,
    p_phone, p_email, p_bed_capacity, p_specialties, p_services,
    v_founder_id, p_founder_name, p_founder_id_number, p_founder_phone, p_founder_email,
    p_license_number, p_license_body, 'submitted', now()
  )
  RETURNING id INTO v_registration_id;

  RETURN jsonb_build_object(
    'success', true,
    'registration_id', v_registration_id,
    'message', 'Facility registration submitted successfully',
    'status', 'submitted',
    'next_steps', ARRAY[
      'Upload license documents',
      'Upload facility photos',
      'Wait for verification by Ministry of Health',
      'Verification typically takes 3-5 business days'
    ]
  );
END;
$$;


ALTER FUNCTION "public"."register_health_facility"("p_name" "text", "p_type" "text", "p_ownership" "text", "p_level" integer, "p_country" "text", "p_county" "text", "p_town" "text", "p_address" "text", "p_phone" "text", "p_email" "text", "p_bed_capacity" integer, "p_specialties" "text"[], "p_services" "text"[], "p_founder_name" "text", "p_founder_id_number" "text", "p_founder_phone" "text", "p_founder_email" "text", "p_license_number" "text", "p_license_body" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."register_referral"("referral_code_arg" "text", "source_platform_arg" "text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                                                                  DECLARE
                                                                                    referrer uuid;
                                                                                    BEGIN
                                                                                      -- Find referrer
                                                                                        SELECT user_id INTO referrer
                                                                                          FROM referral_codes
                                                                                            WHERE code = referral_code_arg
                                                                                              AND active = true;

                                                                                                -- Prevent self-referral & duplicates
                                                                                                  IF referrer IS NULL OR referrer = auth.uid() THEN
                                                                                                      RETURN;
                                                                                                        END IF;

                                                                                                          -- Record referral
                                                                                                            INSERT INTO referrals (
                                                                                                                referrer_id,
                                                                                                                    referred_user_id,
                                                                                                                        referral_code,
                                                                                                                            source_platform
                                                                                                                              )
                                                                                                                                VALUES (
                                                                                                                                    referrer,
                                                                                                                                        auth.uid(),
                                                                                                                                            referral_code_arg,
                                                                                                                                                source_platform_arg
                                                                                                                                                  )
                                                                                                                                                    ON CONFLICT DO NOTHING;

                                                                                                                                                      -- Reward referrer (example: points)
                                                                                                                                                        INSERT INTO referral_rewards (
                                                                                                                                                            user_id,
                                                                                                                                                                referral_id,
                                                                                                                                                                    reward_type,
                                                                                                                                                                        reward_value,
                                                                                                                                                                            issued
                                                                                                                                                                              )
                                                                                                                                                                                SELECT
                                                                                                                                                                                    referrer,
                                                                                                                                                                                        r.id,
                                                                                                                                                                                            'points',
                                                                                                                                                                                                10,
                                                                                                                                                                                                    true
                                                                                                                                                                                                      FROM referrals r
                                                                                                                                                                                                        WHERE r.referred_user_id = auth.uid();

                                                                                                                                                                                                        END;
                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."register_referral"("referral_code_arg" "text", "source_platform_arg" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_escrow"("_escrow_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
declare
  esc record;
begin

  select * into esc
  from public.escrow_accounts
  where id = _escrow_id
  for update;

  if esc.status != 'LOCKED' then
    return false;
  end if;

  update public.escrow_accounts
  set status = 'RELEASED'
  where id = _escrow_id;

  perform public.wallet_credit(
    esc.payee_id,
    esc.amount,
    'ESCROW_RELEASE'
  );

  return true;

end;
$$;


ALTER FUNCTION "public"."release_escrow"("_escrow_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_escrow"("_escrow_id" "uuid", "_reference" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
declare v record;
begin
  select * into v
  from public.escrow_accounts
  where id = _escrow_id;

  update public.escrow_accounts
  set status = 'released',
      updated_at = now()
  where id = _escrow_id;

  perform public.wallet_credit(v.payee_id, v.amount, _reference);
end;
$$;


ALTER FUNCTION "public"."release_escrow"("_escrow_id" "uuid", "_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_job_escrow"("p_escrow" "uuid", "p_worker_wallet" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

amount_value numeric;
worker_account uuid;
tx_id uuid;

begin

select amount into amount_value
from escrow_accounts
where id = p_escrow;


insert into ledger_transactions(reference,transaction_type)

values(gen_random_uuid()::text,'escrow_release')

returning id into tx_id;


select id into worker_account
from ledger_accounts
where wallet_id = p_worker_wallet
limit 1;


insert into ledger_entries(transaction_id,account_id,entry_type,amount)

values
(tx_id,worker_account,'credit',amount_value);


update escrow_accounts
set status='released'
where id = p_escrow;


return tx_id;

end;

$$;


ALTER FUNCTION "public"."release_job_escrow"("p_escrow" "uuid", "p_worker_wallet" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_milestone"("p_escrow_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_escrow RECORD;
    BEGIN
        -- 1. Fetch the escrow record
            SELECT *
                INTO v_escrow
                    FROM escrow_accounts
                        WHERE id = p_escrow_id;

                            IF NOT FOUND THEN
                                    RAISE EXCEPTION 'Escrow with ID % not found', p_escrow_id;
                                        END IF;

                                            -- 2. Insert transaction for worker
                                                INSERT INTO wallet_transactions (user_id, amount, type)
                                                    VALUES (v_escrow.worker_id, v_escrow.amount, 'milestone_release');

                                                        -- 3. Update worker wallet balance
                                                            PERFORM update_wallet_balance(v_escrow.worker_id);

                                                                -- 4. Update escrow status
                                                                    UPDATE escrow_accounts
                                                                        SET status = 'completed'
                                                                            WHERE id = p_escrow_id;

                                                                            END;
                                                                            $$;


ALTER FUNCTION "public"."release_milestone"("p_escrow_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_milestone_to_wallet"("p_worker_id" "uuid", "p_amount" numeric, "p_job_id" "uuid", "p_milestone_id" "uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
        declare
          v_employer_id uuid;
            v_mil_worker uuid;
              v_prev_status text;
                v_remaining int;
                begin
                  -- Verify caller is employer/owner of job
                    select j.user_id into v_employer_id
                      from public.jobs j
                        where j.id = p_job_id;

                          if v_employer_id is null then
                              raise exception 'Job not found';
                                end if;

                                  if auth.uid() is null then
                                      raise exception 'Auth required';
                                        end if;

                                          if auth.uid() <> v_employer_id then
                                              raise exception 'Only employer can release milestones';
                                                end if;

                                                  -- Verify milestone belongs to job + not already completed + worker matches
                                                    select m.user_id, m.status into v_mil_worker, v_prev_status
                                                      from public.milestones m
                                                        where m.id = p_milestone_id and m.job_id = p_job_id
                                                          for update;

                                                            if v_mil_worker is null then
                                                                raise exception 'Milestone not found for job';
                                                                  end if;

                                                                    if v_mil_worker <> p_worker_id then
                                                                        raise exception 'Milestone worker mismatch';
                                                                          end if;

                                                                            if v_prev_status = 'completed' then
                                                                                raise exception 'Milestone already completed';
                                                                                  end if;

                                                                                    if p_amount is null or p_amount <= 0 then
                                                                                        raise exception 'Invalid amount';
                                                                                          end if;

                                                                                            -- Ensure wallet row exists
                                                                                              insert into public.wallet (user_id, balance, currency)
                                                                                                values (p_worker_id, 0, 'MTAA')
                                                                                                  on conflict (user_id) do nothing;

                                                                                                    -- Credit wallet
                                                                                                      update public.wallet
                                                                                                          set balance = balance + p_amount,
                                                                                                                  updated_at = now()
                                                                                                                    where user_id = p_worker_id;

                                                                                                                      -- Record wallet transaction (schema table: wallet_transactions)
                                                                                                                        insert into public.wallet_transactions (user_id, amount, type)
                                                                                                                          values (p_worker_id, p_amount, 'milestone_release');

                                                                                                                            -- Mark milestone completed + released_at for audit
                                                                                                                              update public.milestones
                                                                                                                                  set status = 'completed',
                                                                                                                                          released_at = now(),
                                                                                                                                                  updated_at = now()
                                                                                                                                                    where id = p_milestone_id;

                                                                                                                                                      -- Update escrow status based on remaining milestones
                                                                                                                                                        select count(*) into v_remaining
                                                                                                                                                          from public.milestones
                                                                                                                                                            where job_id = p_job_id and status <> 'completed';

                                                                                                                                                              update public.escrow_accounts
                                                                                                                                                                  set status = case when v_remaining > 0 then 'partially_released' else 'completed' end
                                                                                                                                                                    where job_id = p_job_id;

                                                                                                                                                                    end;
                                                                                                                                                                    $$;


ALTER FUNCTION "public"."release_milestone_to_wallet"("p_worker_id" "uuid", "p_amount" numeric, "p_job_id" "uuid", "p_milestone_id" "uuid") OWNER TO "postgres";


COMMENT ON FUNCTION "public"."release_milestone_to_wallet"("p_worker_id" "uuid", "p_amount" numeric, "p_job_id" "uuid", "p_milestone_id" "uuid") IS 'MTAA Jobs: secure milestone release. Only job employer (jobs.user_id) can call. Credits worker wallet + logs wallet_transactions and updates milestones/escrow.';



CREATE OR REPLACE FUNCTION "public"."release_partial_milestone"("p_escrow_id" "uuid", "p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
        DECLARE
            v_escrow RECORD;
                v_new_status text;
                BEGIN
                    -- 1. Fetch the escrow record
                        SELECT *
                            INTO v_escrow
                                FROM escrow_accounts
                                    WHERE id = p_escrow_id;

                                        IF NOT FOUND THEN
                                                RAISE EXCEPTION 'Escrow with ID % not found', p_escrow_id;
                                                    END IF;

                                                        -- 2. Validate release amount
                                                            IF p_amount <= 0 OR p_amount > v_escrow.amount THEN
                                                                    RAISE EXCEPTION 'Invalid release amount: %', p_amount;
                                                                        END IF;

                                                                            -- 3. Insert wallet transaction for worker
                                                                                INSERT INTO wallet_transactions (user_id, amount, type)
                                                                                    VALUES (v_escrow.worker_id, p_amount, 'milestone_release');

                                                                                        -- 4. Update worker wallet balance
                                                                                            PERFORM update_wallet_balance(v_escrow.worker_id);

                                                                                                -- 5. Update escrow amount and status
                                                                                                    IF p_amount = v_escrow.amount THEN
                                                                                                            v_new_status := 'completed';
                                                                                                                    UPDATE escrow_accounts
                                                                                                                            SET status = v_new_status
                                                                                                                                    WHERE id = p_escrow_id;
                                                                                                                                        ELSE
                                                                                                                                                v_new_status := 'partially_released';
                                                                                                                                                        UPDATE escrow_accounts
                                                                                                                                                                SET amount = amount - p_amount,
                                                                                                                                                                            status = v_new_status
                                                                                                                                                                                    WHERE id = p_escrow_id;
                                                                                                                                                                                        END IF;

                                                                                                                                                                                        END;
                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."release_partial_milestone"("p_escrow_id" "uuid", "p_amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."release_pool"("p_pool" "uuid", "p_wallet" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

amount_value numeric;
wallet_account uuid;
tx_id uuid;

begin

select sum(amount)
into amount_value
from pool_contributions
where pool_id = p_pool;

insert into ledger_transactions(reference,transaction_type)

values(gen_random_uuid()::text,'pool_release')

returning id into tx_id;

select id into wallet_account
from ledger_accounts
where wallet_id = p_wallet
limit 1;

insert into ledger_entries(transaction_id,account_id,entry_type,amount)

values
(tx_id,wallet_account,'credit',amount_value);

update savings_pools
set status='released'
where id = p_pool;

return tx_id;

end;

$$;


ALTER FUNCTION "public"."release_pool"("p_pool" "uuid", "p_wallet" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_ride"("p_pickup" "jsonb", "p_dropoff" "jsonb", "p_ride_type" "text" DEFAULT 'instant'::"text", "p_vehicle_type" "text" DEFAULT 'sedan'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_ride_id UUID; 
  v_estimated_fare NUMERIC; 
  v_distance_km NUMERIC;
BEGIN
  v_distance_km := public.calculate_distance_km(
    (p_pickup->>'lat')::double precision, 
    (p_pickup->>'lng')::double precision,
    (p_dropoff->>'lat')::double precision, 
    (p_dropoff->>'lng')::double precision
  );
  v_estimated_fare := public.calculate_fare(v_distance_km);
  
  INSERT INTO public.rides (
    rider_id, 
    pickup_location, 
    dropoff_location, 
    ride_type, 
    estimated_fare, 
    status,
    pickup_lat,
    pickup_lng,
    dropoff_lat,
    dropoff_lng,
    distance_km
  ) VALUES (
    auth.uid(), 
    p_pickup, 
    p_dropoff, 
    p_ride_type, 
    v_estimated_fare, 
    'requested',
    (p_pickup->>'lat')::double precision,
    (p_pickup->>'lng')::double precision,
    (p_dropoff->>'lat')::double precision,
    (p_dropoff->>'lng')::double precision,
    v_distance_km
  ) RETURNING id INTO v_ride_id;
  
  INSERT INTO public.escrow_accounts (
    job_id, 
    employer_id, 
    amount, 
    status
  ) VALUES (
    v_ride_id, 
    auth.uid(), 
    v_estimated_fare, 
    'held'
  );
  
  RETURN v_ride_id;
END;
$$;


ALTER FUNCTION "public"."request_ride"("p_pickup" "jsonb", "p_dropoff" "jsonb", "p_ride_type" "text", "p_vehicle_type" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."request_trip"("pickup_lat" numeric, "pickup_lng" numeric, "drop_lat" numeric, "drop_lng" numeric, "transport" "text", "capacity" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql"
    AS $$
              declare
                op_id uuid;
                  dist_km numeric;
                    price numeric;
                      trip_id uuid;
                      begin
                        -- distance
                          dist_km :=
                              st_distance(
                                    st_setsrid(st_makepoint(pickup_lng, pickup_lat), 4326)::geography,
                                          st_setsrid(st_makepoint(drop_lng, drop_lat), 4326)::geography
                                              ) / 1000;

                                                -- find operator
                                                  select user_id
                                                    into op_id
                                                      from public.live_locations ll
                                                        join public.transport_operators op on op.user_id = ll.user_id
                                                          where
                                                              ll.transport_type = transport
                                                                  and op.max_capacity >= capacity
                                                                      and op.active = true
                                                                        order by
                                                                            ll.location <-> st_setsrid(st_makepoint(pickup_lng, pickup_lat), 4326)::geography
                                                                              limit 1;

                                                                                if op_id is null then
                                                                                    raise exception 'No operator nearby';
                                                                                      end if;

                                                                                        price := public.calculate_trip_price(transport, dist_km, capacity);

                                                                                          insert into public.trips (
                                                                                              user_id,
                                                                                                  operator_id,
                                                                                                      transport_type,
                                                                                                          requested_capacity,
                                                                                                              pickup,
                                                                                                                  dropoff,
                                                                                                                      distance_km,
                                                                                                                          estimated_price,
                                                                                                                              status
                                                                                                                                ) values (
                                                                                                                                    auth.uid(),
                                                                                                                                        op_id,
                                                                                                                                            transport,
                                                                                                                                                capacity,
                                                                                                                                                    st_setsrid(st_makepoint(pickup_lng, pickup_lat), 4326)::geography,
                                                                                                                                                        st_setsrid(st_makepoint(drop_lng, drop_lat), 4326)::geography,
                                                                                                                                                            dist_km,
                                                                                                                                                                price,
                                                                                                                                                                    'assigned'
                                                                                                                                                                      )
                                                                                                                                                                        returning id into trip_id;

                                                                                                                                                                          return trip_id;
                                                                                                                                                                          end;
                                                                                                                                                                          $$;


ALTER FUNCTION "public"."request_trip"("pickup_lat" numeric, "pickup_lng" numeric, "drop_lat" numeric, "drop_lng" numeric, "transport" "text", "capacity" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."reset_agent_daily_counters"() RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    UPDATE agents SET today_deposited = 0, today_withdrawn = 0 WHERE status = 'active';
END;
$$;


ALTER FUNCTION "public"."reset_agent_daily_counters"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."resolve_storage_url"("file_path" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    resolved TEXT;
    project_id TEXT := 'exmfzrgsxnwwliatva';
BEGIN
    IF file_path IS NULL OR file_path = '' THEN
        RETURN NULL;
    END IF;

    -- Already a full URL, return as-is
    IF file_path LIKE 'http://%' OR file_path LIKE 'https://%' THEN
        RETURN file_path;
    END IF;

    -- Build public URL from storage 'content' bucket
    resolved := 'https://' || project_id || 
                '.supabase.co/storage/v1/object/public/content/' || file_path;

    RETURN resolved;
END;
$$;


ALTER FUNCTION "public"."resolve_storage_url"("file_path" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rls_auto_enable"() RETURNS "event_trigger"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'pg_catalog'
    AS $$
DECLARE
  cmd record;
BEGIN
  FOR cmd IN
    SELECT *
    FROM pg_event_trigger_ddl_commands()
    WHERE command_tag IN ('CREATE TABLE', 'CREATE TABLE AS', 'SELECT INTO')
      AND object_type IN ('table','partitioned table')
  LOOP
     IF cmd.schema_name IS NOT NULL AND cmd.schema_name IN ('public') AND cmd.schema_name NOT IN ('pg_catalog','information_schema') AND cmd.schema_name NOT LIKE 'pg_toast%' AND cmd.schema_name NOT LIKE 'pg_temp%' THEN
      BEGIN
        EXECUTE format('alter table if exists %s enable row level security', cmd.object_identity);
        RAISE LOG 'rls_auto_enable: enabled RLS on %', cmd.object_identity;
      EXCEPTION
        WHEN OTHERS THEN
          RAISE LOG 'rls_auto_enable: failed to enable RLS on %', cmd.object_identity;
      END;
     ELSE
        RAISE LOG 'rls_auto_enable: skip % (either system schema or not in enforced list: %.)', cmd.object_identity, cmd.schema_name;
     END IF;
  END LOOP;
END;
$$;


ALTER FUNCTION "public"."rls_auto_enable"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."route_event_channel"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
begin

    -- assign channel based on event type
    if new.event_type like 'wallet.%' then
        new.payload = jsonb_set(new.payload, '{channel}', '"wallet"');
    elsif new.event_type like 'job.%' then
        new.payload = jsonb_set(new.payload, '{channel}', '"jobs"');
    elsif new.event_type like 'live.%' then
        new.payload = jsonb_set(new.payload, '{channel}', '"live"');
    else
        new.payload = jsonb_set(new.payload, '{channel}', '"system"');
    end if;

    return new;
end;
$$;


ALTER FUNCTION "public"."route_event_channel"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."rpc_wallet_transfer"("p_sender_wallet" "uuid", "p_receiver_wallet" "uuid", "p_amount" numeric, "p_reference" "text" DEFAULT NULL::"text") RETURNS json
    LANGUAGE "plpgsql"
    AS $$

declare
  v_reference text;
  v_sender_balance numeric;
  v_receiver_balance numeric;
begin

  -- =========================
  -- VALIDATION
  -- =========================

  if p_amount <= 0 then
    raise exception 'Invalid amount';
  end if;

  -- =========================
  -- LOCK WALLET ROWS (CRITICAL FOR SCALE)
  -- =========================

  select balance
  into v_sender_balance
  from wallets
  where id = p_sender_wallet
  for update;

  if v_sender_balance is null then
    raise exception 'Sender wallet not found';
  end if;

  if v_sender_balance < p_amount then
    raise exception 'Insufficient balance';
  end if;

  select balance
  into v_receiver_balance
  from wallets
  where id = p_receiver_wallet
  for update;

  if v_receiver_balance is null then
    raise exception 'Receiver wallet not found';
  end if;

  -- =========================
  -- GENERATE REFERENCE
  -- =========================

  v_reference := coalesce(p_reference, gen_random_uuid()::text);

  -- =========================
  -- UPDATE WALLET BALANCES
  -- =========================

  update wallets
  set balance = balance - p_amount,
      updated_at = now()
  where id = p_sender_wallet;

  update wallets
  set balance = balance + p_amount,
      updated_at = now()
  where id = p_receiver_wallet;

  -- =========================
  -- LEDGER ENTRIES (TRUTH LAYER)
  -- =========================

  insert into ledger_entries (
    account_id,
    entry_type,
    amount,
    created_at
  ) values (
    p_sender_wallet,
    'debit',
    p_amount,
    now()
  );

  insert into ledger_entries (
    account_id,
    entry_type,
    amount,
    created_at
  ) values (
    p_receiver_wallet,
    'credit',
    p_amount,
    now()
  );

  -- =========================
  -- PAYMENT INTENT LOG
  -- =========================

  insert into payment_intents (
    sender_wallet_id,
    receiver_wallet_id,
    amount,
    status,
    reference
  ) values (
    p_sender_wallet,
    p_receiver_wallet,
    p_amount,
    'completed',
    v_reference
  );

  -- =========================
  -- RESPONSE
  -- =========================

  return json_build_object(
    'status', 'success',
    'reference', v_reference,
    'sender_wallet', p_sender_wallet,
    'receiver_wallet', p_receiver_wallet,
    'amount', p_amount
  );

end;
$$;


ALTER FUNCTION "public"."rpc_wallet_transfer"("p_sender_wallet" "uuid", "p_receiver_wallet" "uuid", "p_amount" numeric, "p_reference" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."run_wallet_migration"("migration_name" "text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
