    SELECT 1 FROM wallet_migrations WHERE name = migration_name
  ) THEN
    RAISE NOTICE 'Migration already applied: %', migration_name;
    RETURN;
  END IF;

  INSERT INTO wallet_migrations(name)
  VALUES (migration_name);

END;
$$;


