CREATE OR REPLACE FUNCTION "public"."safe_create_policy"("p_table" "text", "p_name" "text", "p_cmd" "text", "p_using" "text" DEFAULT NULL::"text", "p_with_check" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    EXECUTE format('DROP POLICY IF EXISTS %I ON %I', p_name, p_table);
    IF p_with_check IS NOT NULL THEN
        EXECUTE format('CREATE POLICY %I ON %I FOR %s WITH CHECK (%s)', p_name, p_table, p_cmd, p_with_check);
    ELSIF p_using IS NOT NULL THEN
        EXECUTE format('CREATE POLICY %I ON %I FOR %s USING (%s)', p_name, p_table, p_cmd, p_using);
    ELSE
        EXECUTE format('CREATE POLICY %I ON %I FOR %s', p_name, p_table, p_cmd);
    END IF;
END;
$$;


ALTER FUNCTION "public"."safe_create_policy"("p_table" "text", "p_name" "text", "p_cmd" "text", "p_using" "text", "p_with_check" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."safe_job_score"("_job_id" "uuid") RETURNS numeric
    LANGUAGE "plpgsql" STABLE
    AS $$
declare
    j record;
    score numeric := 0;
begin
    select * into j from public.jobs where id = _job_id;

    if j is null then
        return 0;
    end if;

    -- ONLY USE GUARANTEED FIELDS
    if j.id is not null then
        score := score + 50;
    end if;

    if j.title is not null then
        score := score + 20;
    end if;

    if j.status = 'open' then
        score := score + 30;
    end if;

    return score;
end;
$$;


ALTER FUNCTION "public"."safe_job_score"("_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."safe_wallet_transfer"("p_idempotency" "text", "sender_wallet" "uuid", "receiver_wallet" "uuid", "amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

tx_id uuid;
sender_account uuid;
receiver_account uuid;

begin

if exists (
select 1
from payment_idempotency
where idempotency_key = p_idempotency
) then

return (
select reference_id
from payment_idempotency
where idempotency_key = p_idempotency
);

end if;

perform lock_wallet(sender_wallet);


insert into ledger_transactions(reference,transaction_type)

values(gen_random_uuid()::text,'transfer')

returning id into tx_id;


select id into sender_account
from ledger_accounts
where wallet_id = sender_wallet
limit 1;


select id into receiver_account
from ledger_accounts
where wallet_id = receiver_wallet
limit 1;


insert into ledger_entries(transaction_id,account_id,entry_type,amount)

values
(tx_id,sender_account,'debit',amount),
(tx_id,receiver_account,'credit',amount);


insert into payment_idempotency(
idempotency_key,
user_id,
request_type,
reference_id
)

values(
p_idempotency,
auth.uid(),
'transfer',
tx_id
);


perform wallet_log(auth.uid(),'transfer',tx_id);


perform unlock_wallet(sender_wallet);


return tx_id;

end;

$$;


ALTER FUNCTION "public"."safe_wallet_transfer"("p_idempotency" "text", "sender_wallet" "uuid", "receiver_wallet" "uuid", "amount" numeric) OWNER TO "postgres";


