CREATE OR REPLACE FUNCTION "public"."search_contractors"("p_query" "text" DEFAULT NULL::"text", "p_county" "text" DEFAULT NULL::"text", "p_company_type" "text" DEFAULT NULL::"text", "p_agpo_category" "text" DEFAULT NULL::"text", "p_blacklist_standing" "text" DEFAULT NULL::"text", "p_limit" integer DEFAULT 20, "p_offset" integer DEFAULT 0) RETURNS TABLE("id" "uuid", "name" "text", "registration_number" "text", "kra_pin" "text", "company_type" "text", "agpo_category" "text", "company_score" integer, "county" "text", "blacklist_status" "text", "created_at" timestamp with time zone, "director_count" integer)
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
BEGIN
    RETURN QUERY
    SELECT 
        c.id, c.name, c.registration_number, c.kra_pin, c.company_type,
        c.agpo_category, c.company_score, c.county, c.blacklist_status, c.created_at, c.director_count
    FROM civic_contractors c
    WHERE (p_query IS NULL OR 
           c.name ILIKE '%' || p_query || '%' OR 
           c.registration_number ILIKE '%' || p_query || '%' OR
           c.kra_pin ILIKE '%' || p_query || '%')
      AND (p_county IS NULL OR c.county = p_county)
      AND (p_company_type IS NULL OR c.company_type = p_company_type)
      AND (p_agpo_category IS NULL OR c.agpo_category = p_agpo_category)
      AND (p_blacklist_standing IS NULL OR c.blacklist_status = p_blacklist_standing)
    ORDER BY c.company_score DESC, c.created_at DESC
    LIMIT p_limit OFFSET p_offset;
END;
$$;


