CREATE OR REPLACE FUNCTION "public"."search_users"("p_query" "text", "p_limit" integer DEFAULT 20) RETURNS TABLE("id" "uuid", "full_name" "text", "email" "text", "avatar_url" "text", "similarity" numeric)
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT 
    p.id,
    p.full_name,
    p.email,
    p.avatar_url,
    similarity(p.full_name, p_query) as sim
  FROM public.profiles p
  WHERE 
    p.full_name % p_query
    OR p.full_name ILIKE '%' || p_query || '%'
    OR p.email ILIKE '%' || p_query || '%'
  ORDER BY sim DESC
  LIMIT p_limit;
END;
$$;


