CREATE OR REPLACE FUNCTION "public"."secure_transfer_money"("sender_id" "uuid", "receiver_id" "uuid", "amount" numeric, "idempotency_key" "text") RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
          declare
            sender_balance numeric;
              existing_tx int;
              begin

                -- 🚫 IDENTITY CHECK (PREVENT REPLAY)
                  select count(*) into existing_tx
                    from wallet_transactions
                      where wallet_transactions.idempotency_key = secure_transfer_money.idempotency_key;

                        if existing_tx > 0 then
                            return 'DUPLICATE_REQUEST';
                              end if;

                                -- 🔒 LOCK SENDER LEDGER
                                  select coalesce(sum(amount), 0)
                                    into sender_balance
                                      from wallet_transactions
                                        where user_id = sender_id
                                          for update;

                                            -- 🚫 BALANCE CHECK
                                              if sender_balance < amount then
                                                  raise exception 'INSUFFICIENT_FUNDS';
                                                    end if;

                                                      -- 💳 DEBIT
                                                        insert into wallet_transactions(user_id, amount, type, reference_id, idempotency_key)
                                                          values (sender_id, -amount, 'transfer_out', receiver_id, idempotency_key);

                                                            -- 💰 CREDIT
                                                              insert into wallet_transactions(user_id, amount, type, reference_id, idempotency_key)
                                                                values (receiver_id, amount, 'transfer_in', sender_id, idempotency_key);

                                                                  return 'SUCCESS';

                                                                  end;
                                                                  $$;


ALTER FUNCTION "public"."secure_transfer_money"("sender_id" "uuid", "receiver_id" "uuid", "amount" numeric, "idempotency_key" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_batch_notifications"("p_user_ids" "uuid"[], "p_title" "text", "p_body" "text", "p_type" "text" DEFAULT 'system'::"text", "p_data" "jsonb" DEFAULT '{}'::"jsonb") RETURNS integer
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_count integer := 0;
  v_user_id uuid;
BEGIN
  FOREACH v_user_id IN ARRAY p_user_ids
  LOOP
    INSERT INTO public.notifications (user_id, actor_id, type, is_read, created_at)
    VALUES (v_user_id, auth.uid(), p_type, false, now());
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$$;


ALTER FUNCTION "public"."send_batch_notifications"("p_user_ids" "uuid"[], "p_title" "text", "p_body" "text", "p_type" "text", "p_data" "jsonb") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."send_tip"("p_receiver_id" "uuid", "p_amount" numeric, "p_gift_id" "uuid" DEFAULT NULL::"uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
        declare
          v_sender_id uuid := auth.uid();
            v_sender_wallet_id uuid;
              v_receiver_wallet_id uuid;
                v_sender_balance numeric;
                  v_tip_id uuid;
                  begin
                    if v_sender_id is null then
                        raise exception 'Not authenticated';
                          end if;

                            -- Get wallets
                              select id, balance into v_sender_wallet_id, v_sender_balance
                                from wallets
                                  where owner_id = v_sender_id;

                                    if v_sender_balance < p_amount then
                                        raise exception 'Insufficient balance';
                                          end if;

                                            select id into v_receiver_wallet_id
                                              from wallets
                                                where owner_id = p_receiver_id;

                                                  if v_receiver_wallet_id is null then
                                                      raise exception 'Receiver has no wallet';
                                                        end if;

                                                          -- Create tip record
                                                            insert into tips (sender_id, receiver_id, gift_id, amount)
                                                              values (v_sender_id, p_receiver_id, p_gift_id, p_amount)
                                                                returning id into v_tip_id;

                                                                  -- Debit sender
                                                                    update wallets
                                                                      set balance = balance - p_amount
                                                                        where id = v_sender_wallet_id;

                                                                          insert into wallet_ledger (
                                                                              wallet_id, entry_type, amount, balance_after, description, reference_id
                                                                                )
                                                                                  values (
                                                                                      v_sender_wallet_id,
                                                                                          'debit',
                                                                                              p_amount,
                                                                                                  v_sender_balance - p_amount,
                                                                                                      'Tip sent',
                                                                                                          v_tip_id
                                                                                                            );

                                                                                                              -- Credit receiver
                                                                                                                update wallets
                                                                                                                  set balance = balance + p_amount
                                                                                                                    where id = v_receiver_wallet_id;

                                                                                                                      insert into wallet_ledger (
                                                                                                                          wallet_id, entry_type, amount, balance_after, description, reference_id
                                                                                                                            )
                                                                                                                              select
                                                                                                                                  v_receiver_wallet_id,
                                                                                                                                      'credit',
                                                                                                                                          p_amount,
                                                                                                                                              balance,
                                                                                                                                                  'Tip received',
                                                                                                                                                      v_tip_id
                                                                                                                                                        from wallets
                                                                                                                                                          where id = v_receiver_wallet_id;

                                                                                                                                                            return v_tip_id;
                                                                                                                                                            end;
                                                                                                                                                            $$;


ALTER FUNCTION "public"."send_tip"("p_receiver_id" "uuid", "p_amount" numeric, "p_gift_id" "uuid") OWNER TO "postgres";


