    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.status = 'verified' THEN
        UPDATE profiles SET kyc_status = 'verified', verification_level = 2, is_verified = TRUE WHERE user_id = NEW.user_id;
    ELSIF NEW.status = 'rejected' THEN
