CREATE OR REPLACE FUNCTION "public"."sync_post_media_urls"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
                   DECLARE
                     cleaned text;
                     BEGIN
                       IF NEW.media_urls IS NULL THEN
                           NEW.media_urls := ARRAY[]::text[];
                             END IF;

                               IF NEW.media_url IS NOT NULL AND left(trim(NEW.media_url), 1) = '[' THEN
                                   cleaned := trim(both '"' from replace(replace(NEW.media_url, '[', ''), ']', ''));
                                       IF position(',' in cleaned) > 0 THEN
                                             cleaned := split_part(cleaned, ',', 1);
                                                 END IF;
                                                     NEW.media_url := trim(cleaned);
                                                       END IF;

                                                         IF (array_length(NEW.media_urls, 1) IS NULL OR array_length(NEW.media_urls, 1) = 0)
                                                              AND NEW.media_url IS NOT NULL AND length(NEW.media_url) > 0 THEN
                                                                  NEW.media_urls := ARRAY[NEW.media_url];
                                                                    END IF;

                                                                      RETURN NEW;
                                                                      END;
                                                                      $$;


ALTER FUNCTION "public"."sync_post_media_urls"() OWNER TO "postgres";


