CREATE OR REPLACE FUNCTION "public"."toggle_job_saved_item"("p_job_id" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
                                                                                                                                                                                  declare
                                                                                                                                                                                    v_user_id uuid := auth.uid();
                                                                                                                                                                                      v_exists boolean;
                                                                                                                                                                                      begin
                                                                                                                                                                                        if v_user_id is null then
                                                                                                                                                                                            raise exception 'Not authenticated';
                                                                                                                                                                                              end if;

                                                                                                                                                                                                select exists(
                                                                                                                                                                                                    select 1
                                                                                                                                                                                                        from public.job_saved_items
                                                                                                                                                                                                            where job_id = p_job_id
                                                                                                                                                                                                                  and user_id = v_user_id
                                                                                                                                                                                                                    ) into v_exists;

                                                                                                                                                                                                                      if v_exists then
                                                                                                                                                                                                                          delete from public.job_saved_items
                                                                                                                                                                                                                              where job_id = p_job_id
                                                                                                                                                                                                                                    and user_id = v_user_id;
                                                                                                                                                                                                                                        return false;
                                                                                                                                                                                                                                          else
                                                                                                                                                                                                                                              insert into public.job_saved_items (job_id, user_id)
                                                                                                                                                                                                                                                  values (p_job_id, v_user_id);
                                                                                                                                                                                                                                                      return true;
                                                                                                                                                                                                                                                        end if;
                                                                                                                                                                                                                                                        end;
                                                                                                                                                                                                                                                        $$;


ALTER FUNCTION "public"."toggle_job_saved_item"("p_job_id" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."toggle_like"("post_id_arg" "uuid") RETURNS boolean
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
                                              DECLARE
                                                liked boolean;
                                                BEGIN
                                                  SELECT EXISTS (
                                                      SELECT 1 FROM post_likes
                                                          WHERE post_id = post_id_arg
                                                              AND user_id = auth.uid()
                                                                ) INTO liked;

                                                                  IF liked THEN
                                                                      DELETE FROM post_likes
                                                                          WHERE post_id = post_id_arg
                                                                              AND user_id = auth.uid();
                                                                                ELSE
                                                                                    INSERT INTO post_likes (post_id, user_id)
                                                                                        VALUES (post_id_arg, auth.uid());
                                                                                          END IF;

                                                                                            UPDATE posts
                                                                                              SET like_count = (
                                                                                                  SELECT COUNT(*) FROM post_likes WHERE post_id = post_id_arg
                                                                                                    )
                                                                                                      WHERE id = post_id_arg;

                                                                                                        RETURN NOT liked;
                                                                                                        END;
                                                                                                        $$;


ALTER FUNCTION "public"."toggle_like"("post_id_arg" "uuid") OWNER TO "postgres";


