CREATE OR REPLACE FUNCTION "public"."transfer_funds"("p_from_wallet_id" "uuid", "p_to_wallet_id" "uuid", "p_amount" numeric, "p_description" "text" DEFAULT 'Transfer'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    SET "search_path" TO 'public'
    AS $$
DECLARE
  v_from_balance numeric;
  v_transaction_id uuid;
BEGIN
  SELECT available_balance INTO v_from_balance FROM public.wallets WHERE id = p_from_wallet_id FOR UPDATE;

  IF v_from_balance < p_amount THEN
    RAISE EXCEPTION 'Insufficient funds: % < %', v_from_balance, p_amount;
  END IF;

  UPDATE public.wallets SET balance = balance - p_amount, available_balance = available_balance - p_amount, updated_at = now() WHERE id = p_from_wallet_id;
  INSERT INTO public.transactions (wallet_id, transaction_type, amount, status, description, created_at, net_amount)
  VALUES (p_from_wallet_id, 'debit', p_amount, 'completed', p_description, now(), p_amount);

  UPDATE public.wallets SET balance = balance + p_amount, available_balance = available_balance + p_amount, updated_at = now() WHERE id = p_to_wallet_id;
  INSERT INTO public.transactions (wallet_id, transaction_type, amount, status, description, created_at, net_amount)
  VALUES (p_to_wallet_id, 'credit', p_amount, 'completed', p_description, now(), p_amount)
  RETURNING id INTO v_transaction_id;

  RETURN v_transaction_id;
END;
$$;


ALTER FUNCTION "public"."transfer_funds"("p_from_wallet_id" "uuid", "p_to_wallet_id" "uuid", "p_amount" numeric, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."transfer_money"("sender_id" "uuid", "receiver_id" "uuid", "amount" numeric) RETURNS "text"
    LANGUAGE "plpgsql"
    AS $$
        declare
          sender_balance numeric;
          begin

            -- 🔒 LOCK sender's rows (prevents concurrent modification)
              select coalesce(sum(amount), 0)
                into sender_balance
                  from wallet_transactions
                    where user_id = sender_id
                      for update;

                        -- 🚫 CHECK BALANCE
                          if sender_balance < amount then
                              raise exception 'INSUFFICIENT_FUNDS';
                                end if;

                                  -- 💳 DEBIT SENDER
                                    insert into wallet_transactions(user_id, amount, type, reference_id)
                                      values (sender_id, -amount, 'transfer_out', receiver_id);

                                        -- 💰 CREDIT RECEIVER
                                          insert into wallet_transactions(user_id, amount, type, reference_id)
                                            values (receiver_id, amount, 'transfer_in', sender_id);

                                              return 'SUCCESS';

                                              end;
                                              $$;


ALTER FUNCTION "public"."transfer_money"("sender_id" "uuid", "receiver_id" "uuid", "amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."treasury_audit_trigger"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'DELETE' THEN
        INSERT INTO treasury_audit_logs (table_name, record_id, action, old_data, changed_by)
        VALUES (TG_TABLE_NAME, OLD.id, 'DELETE', row_to_json(OLD), auth.uid());
        RETURN OLD;
    ELSIF TG_OP = 'UPDATE' THEN
        INSERT INTO treasury_audit_logs (table_name, record_id, action, old_data, new_data, changed_by)
        VALUES (TG_TABLE_NAME, NEW.id, 'UPDATE', row_to_json(OLD), row_to_json(NEW), auth.uid());
        RETURN NEW;
    ELSIF TG_OP = 'INSERT' THEN
        INSERT INTO treasury_audit_logs (table_name, record_id, action, new_data, changed_by)
        VALUES (TG_TABLE_NAME, NEW.id, 'INSERT', row_to_json(NEW), auth.uid());
        RETURN NEW;
    END IF;
    RETURN NULL;
END;
$$;


ALTER FUNCTION "public"."treasury_audit_trigger"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_attendance_hours_calc"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.clock_out IS NOT NULL AND OLD.clock_out IS NULL AND NEW.clock_in IS NOT NULL THEN
        NEW.hours_worked = ROUND(EXTRACT(EPOCH FROM (NEW.clock_out - NEW.clock_in)) / 3600, 2);
    END IF;
    RETURN NEW;
END;
$$;


