CREATE OR REPLACE FUNCTION "public"."trg_calc_declaration_taxes"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.local_value = NEW.invoice_value * NEW.exchange_rate;
    NEW.duty_amount = NEW.local_value * COALESCE(NEW.duty_rate, 0);
    NEW.vat_amount = (NEW.local_value + NEW.duty_amount) * COALESCE(NEW.vat_rate, 0);
    NEW.total_taxes = NEW.duty_amount + NEW.vat_amount + COALESCE(NEW.excise_amount, 0) + COALESCE(NEW.other_taxes, 0);
    NEW.risk_channel = CASE
        WHEN NEW.risk_score <= 30 THEN 'green'
        WHEN NEW.risk_score <= 70 THEN 'yellow'
        ELSE 'red'
    END;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_calc_declaration_taxes"() OWNER TO "postgres";


