CREATE OR REPLACE FUNCTION "public"."trg_create_seizure_on_find"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.contraband_found = true THEN
        INSERT INTO contraband_seizures (
            post_id, declaration_id, container_id, inspection_id,
            seizure_type, seizure_description, quantity,
            case_status, officer_id, images_attached, created_at
        )
        SELECT
            NEW.post_id, NEW.declaration_id, NEW.container_id, NEW.id,
            CASE WHEN NEW.findings ILIKE '%drug%' THEN 'drugs'
                 WHEN NEW.findings ILIKE '%weapon%' THEN 'weapons'
                 WHEN NEW.findings ILIKE '%counterfeit%' THEN 'counterfeit'
                 WHEN NEW.findings ILIKE '%wildlife%' THEN 'wildlife'
                 ELSE 'other' END,
            NEW.contraband_description, NEW.contraband_quantity,
            'seized', NEW.officer_id, NEW.images_attached, now()
        WHERE NOT EXISTS (
            SELECT 1 FROM contraband_seizures WHERE inspection_id = NEW.id
        );
    END IF;
    RETURN NEW;
END;
$$;


