CREATE OR REPLACE FUNCTION "public"."trg_inspection_risk_update"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.contraband_found = true THEN
        UPDATE cargo_declarations
        SET risk_score = LEAST(risk_score + 30, 100), inspection_required = true, updated_at = now()
        WHERE id = NEW.declaration_id;
    ELSIF NEW.discrepancy_found = true THEN
        UPDATE cargo_declarations
        SET risk_score = LEAST(risk_score + 15, 100), updated_at = now()
        WHERE id = NEW.declaration_id;
    ELSE
        UPDATE cargo_declarations
        SET risk_score = GREATEST(risk_score - 10, 0), inspection_required = false, updated_at = now()
        WHERE id = NEW.declaration_id;
    END IF;
    RETURN NEW;
END;
$$;


