        UPDATE revenue_tax_obligations
        SET amount_paid = amount_paid + NEW.amount,
            status = CASE 
                WHEN (amount_paid + NEW.amount) >= amount_assessed THEN 'paid'
                WHEN (amount_paid + NEW.amount) > 0 THEN 'partially_paid'
                ELSE status
            END,
            updated_at = now()
        WHERE id = NEW.obligation_id;
    END IF;
