CREATE OR REPLACE FUNCTION "public"."trg_update_cell_occupancy"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF TG_OP = 'INSERT' AND NEW.cell_block IS NOT NULL AND NEW.cell_number IS NOT NULL THEN
        UPDATE prison_cells 
        SET current_occupancy = current_occupancy + 1
        WHERE facility_id = NEW.facility_id AND cell_block = NEW.cell_block AND cell_number = NEW.cell_number;
    ELSIF TG_OP = 'UPDATE' AND (OLD.cell_block IS DISTINCT FROM NEW.cell_block OR OLD.cell_number IS DISTINCT FROM NEW.cell_number) THEN
        IF OLD.cell_block IS NOT NULL AND OLD.cell_number IS NOT NULL THEN
            UPDATE prison_cells 
            SET current_occupancy = GREATEST(current_occupancy - 1, 0)
            WHERE facility_id = OLD.facility_id AND cell_block = OLD.cell_block AND cell_number = OLD.cell_number;
        END IF;
        IF NEW.cell_block IS NOT NULL AND NEW.cell_number IS NOT NULL THEN
            UPDATE prison_cells 
            SET current_occupancy = current_occupancy + 1
            WHERE facility_id = NEW.facility_id AND cell_block = NEW.cell_block AND cell_number = NEW.cell_number;
        END IF;
    ELSIF TG_OP = 'DELETE' AND OLD.cell_block IS NOT NULL AND OLD.cell_number IS NOT NULL THEN
        UPDATE prison_cells 
        SET current_occupancy = GREATEST(current_occupancy - 1, 0)
        WHERE facility_id = OLD.facility_id AND cell_block = OLD.cell_block AND cell_number = OLD.cell_number;
    END IF;
    RETURN COALESCE(NEW, OLD);
END;
$$;


ALTER FUNCTION "public"."trg_update_cell_occupancy"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_update_compliance_status"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    v_overdue_count INTEGER;
    v_total_obligations INTEGER;
BEGIN
    SELECT COUNT(*) INTO v_overdue_count
    FROM revenue_tax_obligations
    WHERE taxpayer_id = NEW.taxpayer_id AND status = 'overdue';

    SELECT COUNT(*) INTO v_total_obligations
    FROM revenue_tax_obligations
    WHERE taxpayer_id = NEW.taxpayer_id;

    UPDATE revenue_taxpayers
    SET compliance_status = CASE
        WHEN v_overdue_count = 0 THEN 'compliant'
        WHEN v_overdue_count <= v_total_obligations * 0.2 THEN 'under_review'
        ELSE 'non_compliant'
    END,
    updated_at = now()
    WHERE id = NEW.taxpayer_id;

    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_update_compliance_status"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."trg_update_debt_days"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.days_overdue = CURRENT_DATE - (
        SELECT due_date FROM revenue_tax_obligations WHERE id = NEW.obligation_id
    );
    NEW.collection_stage = CASE
        WHEN NEW.days_overdue > 365 THEN 'litigation'
        WHEN NEW.days_overdue > 180 THEN 'auction'
        WHEN NEW.days_overdue > 90 THEN 'lien'
        WHEN NEW.days_overdue > 60 THEN 'garnishment'
        WHEN NEW.days_overdue > 30 THEN 'demand_notice'
        ELSE 'reminder'
    END;
    RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."trg_update_debt_days"() OWNER TO "postgres";


