CREATE OR REPLACE FUNCTION "public"."unlock_wallet_investment"("p_position" "uuid") RETURNS boolean
    LANGUAGE "plpgsql"
    AS $$
                                                                                                                                                                                                                                DECLARE
                                                                                                                                                                                                                                  v_user uuid;
                                                                                                                                                                                                                                    v_amount numeric;
                                                                                                                                                                                                                                    BEGIN

                                                                                                                                                                                                                                      SELECT user_id,amount
                                                                                                                                                                                                                                        INTO v_user,v_amount
                                                                                                                                                                                                                                          FROM public.investment_positions
                                                                                                                                                                                                                                            WHERE id = p_position
                                                                                                                                                                                                                                              AND unlock_date <= now()
                                                                                                                                                                                                                                                AND status = 'locked';

                                                                                                                                                                                                                                                  IF v_user IS NULL THEN
                                                                                                                                                                                                                                                      RAISE EXCEPTION 'Position not unlockable';
                                                                                                                                                                                                                                                        END IF;

                                                                                                                                                                                                                                                          UPDATE public.investment_positions
                                                                                                                                                                                                                                                            SET status = 'unlocked'
                                                                                                                                                                                                                                                              WHERE id = p_position;

                                                                                                                                                                                                                                                                INSERT INTO public.wallet_transactions(
                                                                                                                                                                                                                                                                    user_id,
                                                                                                                                                                                                                                                                        amount,
                                                                                                                                                                                                                                                                            type
                                                                                                                                                                                                                                                                              )
                                                                                                                                                                                                                                                                                VALUES(
                                                                                                                                                                                                                                                                                    v_user,
                                                                                                                                                                                                                                                                                        v_amount,
                                                                                                                                                                                                                                                                                            'investment_unlock'
                                                                                                                                                                                                                                                                                              );

                                                                                                                                                                                                                                                                                                RETURN true;

                                                                                                                                                                                                                                                                                                END;
                                                                                                                                                                                                                                                                                                $$;


ALTER FUNCTION "public"."unlock_wallet_investment"("p_position" "uuid") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."unlock_wallet_vault"("p_vault" "uuid") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

amount_value numeric;
wallet_value uuid;
wallet_account uuid;
tx_id uuid;

begin

select amount,wallet_id
into amount_value,wallet_value
from wallet_vaults
where id = p_vault
and status='locked';


if exists(
select 1
from wallet_vaults
where id = p_vault
and lock_until > now()
) then
raise exception 'Vault still locked';
end if;


insert into ledger_transactions(reference,transaction_type)

values(gen_random_uuid()::text,'vault_unlock')

returning id into tx_id;


select id into wallet_account
from ledger_accounts
where wallet_id = wallet_value
limit 1;


insert into ledger_entries(transaction_id,account_id,entry_type,amount)

values
(tx_id,wallet_account,'credit',amount_value);


update wallet_vaults
set status='unlocked'
where id = p_vault;


return tx_id;

end;

$$;


ALTER FUNCTION "public"."unlock_wallet_vault"("p_vault" "uuid") OWNER TO "postgres";


