CREATE OR REPLACE FUNCTION "public"."update_business_blacklist_standing"("p_contractor_id" "uuid", "p_blacklist_standing" "text", "p_review_notes" "text" DEFAULT NULL::"text", "p_admin_id" "uuid" DEFAULT NULL::"uuid") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
    v_old_standing text;
    v_user_id uuid;
BEGIN
    SELECT blacklist_status, created_by INTO v_old_standing, v_user_id 
    FROM civic_contractors WHERE id = p_contractor_id;

    UPDATE civic_contractors SET
        blacklist_status = p_blacklist_standing,
        blacklist_reason = CASE 
            WHEN p_blacklist_standing = 'blacklisted' THEN p_review_notes
            ELSE blacklist_reason
        END,
        blacklisted_by = CASE 
            WHEN p_blacklist_standing = 'blacklisted' THEN p_admin_id
            ELSE blacklisted_by
        END,
        blacklist_date = CASE 
            WHEN p_blacklist_standing = 'blacklisted' THEN now()
            ELSE blacklist_date
        END,
        updated_at = now()
    WHERE id = p_contractor_id;

    INSERT INTO notifications (user_id, type, title, body, metadata)
    VALUES (
        v_user_id,
        'business_blacklist_changed',
        'Business Standing Updated',
        'Your business standing: ' || p_blacklist_standing || '. ' || COALESCE(p_review_notes, 'No notes provided'),
        jsonb_build_object('contractor_id', p_contractor_id, 'old_standing', v_old_standing, 'new_standing', p_blacklist_standing)
    );

    INSERT INTO identity_verification_logs (user_id, event_type, event_data)
    VALUES (v_user_id, 'badge_awarded', jsonb_build_object('blacklist_standing_change', p_blacklist_standing, 'admin_id', p_admin_id));
END;
$$;


ALTER FUNCTION "public"."update_business_blacklist_standing"("p_contractor_id" "uuid", "p_blacklist_standing" "text", "p_review_notes" "text", "p_admin_id" "uuid") OWNER TO "postgres";


