CREATE OR REPLACE FUNCTION "public"."update_crypto_wallet_value"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    NEW.total_usd_value := 
        COALESCE(NEW.btc_balance * (SELECT price FROM crypto_prices WHERE asset = 'BTC' LIMIT 1), 0) +
        COALESCE(NEW.eth_balance * (SELECT price FROM crypto_prices WHERE asset = 'ETH' LIMIT 1), 0) +
        COALESCE(NEW.sol_balance * (SELECT price FROM crypto_prices WHERE asset = 'SOL' LIMIT 1), 0) +
        COALESCE(NEW.usdt_balance, 0) +
        COALESCE(NEW.usdc_balance, 0);
    
    NEW.total_kes_value := NEW.total_usd_value * 130;
    NEW.updated_at := NOW();
    RETURN NEW;
END;
$$;


