CREATE OR REPLACE FUNCTION "public"."update_garage_metrics"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    -- Job completed
    IF NEW.status = 'completed' AND OLD.status != 'completed' THEN
      UPDATE public.garages
      SET 
        total_jobs = total_jobs + 1,
        completed_jobs = completed_jobs + 1,
        active_jobs = GREATEST(active_jobs - 1, 0),
        total_revenue = total_revenue + COALESCE(NEW.final_cost, NEW.estimated_cost, 0)
      WHERE id = NEW.garage_id;
    END IF;

    -- Job started
    IF NEW.status = 'in_progress' AND OLD.status != 'in_progress' THEN
      UPDATE public.garages
      SET active_jobs = active_jobs + 1
      WHERE id = NEW.garage_id;
    END IF;

    -- Job cancelled
    IF NEW.status = 'cancelled' AND OLD.status != 'cancelled' THEN
      UPDATE public.garages
      SET 
        cancelled_jobs = cancelled_jobs + 1,
        active_jobs = GREATEST(active_jobs - 1, 0)
      WHERE id = NEW.garage_id;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_garage_metrics"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_garage_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql"
