      SELECT ROUND(AVG(overall_rating)::numeric, 2)
      FROM public.garage_reviews
      WHERE garage_id = COALESCE(NEW.garage_id, OLD.garage_id)
      AND is_visible = true
    ), 0),
    review_count = (
      SELECT COUNT(*)
      FROM public.garage_reviews
      WHERE garage_id = COALESCE(NEW.garage_id, OLD.garage_id)
      AND is_visible = true
    )
  WHERE id = COALESCE(NEW.garage_id, OLD.garage_id);
  RETURN COALESCE(NEW, OLD);
END;
$$;


