  SELECT volume_30d INTO vol
  FROM gofund_volume_metrics
  WHERE wallet_id = NEW.wallet_id;

  new_limit := calculate_gofund_limit(vol);

  UPDATE gofund_accounts
  SET
    credit_limit = new_limit,
    last_updated = now()
  WHERE wallet_id = NEW.wallet_id;

  RETURN NEW;
END;
