CREATE OR REPLACE FUNCTION "public"."update_job_applications_count"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    UPDATE public.jobs
    SET applications_count = COALESCE(applications_count, 0) + 1
    WHERE id = NEW.job_id;

  ELSIF TG_OP = 'DELETE' THEN
    UPDATE public.jobs
    SET applications_count = GREATEST(COALESCE(applications_count, 0) - 1, 0)
    WHERE id = OLD.job_id;
  END IF;

  RETURN NULL;
END;
$$;


