    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF TG_OP = 'INSERT' AND NEW.status = 'submitted' THEN
    UPDATE jobs SET applications_count = applications_count + 1 WHERE id = NEW.job_id;
  ELSIF TG_OP = 'UPDATE' AND OLD.status != 'hired' AND NEW.status = 'hired' THEN
    UPDATE jobs SET status = 'filled', filled_at = now(), filled_by = NEW.applicant_id WHERE id = NEW.job_id;
  END IF;
  RETURN NEW;
END;
$$;


