    LANGUAGE "plpgsql"
    AS $$
          begin
            insert into public.live_locations (user_id, role, transport_type, location)
              values (
                  auth.uid(),
                      user_role,
                          transport,
                              st_setsrid(st_makepoint(lng, lat), 4326)::geography
                                )
                                  on conflict (user_id)
                                    do update set
                                        location = excluded.location,
                                            last_seen = now(),
                                                transport_type = excluded.transport_type,
                                                    role = excluded.role;
                                                    end;
                                                    $$;


