CREATE OR REPLACE FUNCTION "public"."update_mechanic_rating"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  v_mechanic_id UUID;
BEGIN
  -- Determine which mechanic_id to update
  IF TG_OP = 'DELETE' THEN
    v_mechanic_id := OLD.mechanic_id;
  ELSE
    v_mechanic_id := NEW.mechanic_id;
  END IF;

  -- Also handle case where mechanic_id changed on UPDATE
  IF TG_OP = 'UPDATE' AND OLD.mechanic_id IS DISTINCT FROM NEW.mechanic_id THEN
    -- Update old mechanic
    IF OLD.mechanic_id IS NOT NULL THEN
      UPDATE public.garage_mechanics
      SET 
        rating = COALESCE((
          SELECT ROUND(AVG(overall_rating)::numeric, 2)
          FROM public.garage_reviews
          WHERE mechanic_id = OLD.mechanic_id AND is_visible = true
        ), 0),
        jobs_completed = (
          SELECT COUNT(*) FROM public.garage_appointments
          WHERE mechanic_id = OLD.mechanic_id AND status = 'completed'
        )
      WHERE id = OLD.mechanic_id;
    END IF;
  END IF;

  -- Update current mechanic
  IF v_mechanic_id IS NOT NULL THEN
    UPDATE public.garage_mechanics
    SET 
      rating = COALESCE((
        SELECT ROUND(AVG(overall_rating)::numeric, 2)
        FROM public.garage_reviews
        WHERE mechanic_id = v_mechanic_id AND is_visible = true
      ), 0),
      jobs_completed = (
        SELECT COUNT(*) FROM public.garage_appointments
        WHERE mechanic_id = v_mechanic_id AND status = 'completed'
      )
    WHERE id = v_mechanic_id;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$;


