CREATE OR REPLACE FUNCTION "public"."update_product_stock"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.type = 'purchase' OR NEW.type = 'transfer_in' THEN
    UPDATE products SET stock_quantity = stock_quantity + NEW.quantity, updated_at = now() WHERE id = NEW.product_id;
  ELSIF NEW.type = 'sale' OR NEW.type = 'transfer_out' OR NEW.type = 'damage' OR NEW.type = 'expiry' THEN
    UPDATE products SET stock_quantity = GREATEST(0, stock_quantity - NEW.quantity), updated_at = now() WHERE id = NEW.product_id;
  ELSIF NEW.type = 'return' THEN
    UPDATE products SET stock_quantity = stock_quantity + NEW.quantity, updated_at = now() WHERE id = NEW.product_id;
  ELSIF NEW.type = 'adjustment' THEN
    UPDATE products SET stock_quantity = GREATEST(0, stock_quantity + NEW.quantity), updated_at = now() WHERE id = NEW.product_id;
  END IF;
  RETURN NEW;
END;
$$;


