    total_lessons INTEGER;
    completed_lessons INTEGER;
BEGIN
    SELECT COUNT(*) INTO total_lessons FROM learning_progress WHERE enrollment_id = NEW.enrollment_id;
    SELECT COUNT(*) INTO completed_lessons FROM learning_progress WHERE enrollment_id = NEW.enrollment_id AND status = 'completed';
    
    IF total_lessons > 0 THEN
        UPDATE course_enrollments SET
            progress_percentage = (completed_lessons * 100 / total_lessons),
