CREATE OR REPLACE FUNCTION "public"."update_student_finance_totals"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE v_fees_due numeric(12,2); v_fees_paid numeric(12,2); v_bursaries numeric(12,2); v_savings numeric(12,2);
BEGIN
  SELECT COALESCE(SUM(amount),0) INTO v_fees_due FROM fee_transactions WHERE account_id=NEW.account_id AND transaction_type='fee_charge' AND status='completed';
  SELECT COALESCE(SUM(amount),0) INTO v_fees_paid FROM fee_transactions WHERE account_id=NEW.account_id AND transaction_type='payment' AND status='completed';
  SELECT COALESCE(SUM(amount),0) INTO v_bursaries FROM fee_transactions WHERE account_id=NEW.account_id AND transaction_type='bursary' AND status='completed';
  SELECT COALESCE(SUM(CASE WHEN transaction_type='savings_deposit' THEN amount ELSE -amount END),0) INTO v_savings FROM fee_transactions WHERE account_id=NEW.account_id AND transaction_type IN ('savings_deposit','savings_withdrawal') AND status='completed';
  UPDATE student_finance_accounts SET total_fees_due=v_fees_due, total_fees_paid=v_fees_paid, total_bursaries=v_bursaries, total_savings=v_savings, balance=v_fees_paid+v_bursaries-v_fees_due+v_savings, updated_at=now() WHERE id=NEW.account_id;
  RETURN NEW;
END;
$$;


