CREATE OR REPLACE FUNCTION "public"."update_track_revenue"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
    total numeric;
        creator_part numeric;
            mtaa_part numeric;
            BEGIN
                SELECT COALESCE(SUM(revenue_share),0) INTO total
                    FROM public.track_adverts
                        WHERE track_id = NEW.track_id;

                            -- Placeholder split: 70% creator / 30% MTAA
                                creator_part := total * 0.7;
                                    mtaa_part := total * 0.3;

                                        INSERT INTO public.track_revenue(track_id, total_earned, creator_share, mtaa_share, last_updated)
                                            VALUES (NEW.track_id, total, creator_part, mtaa_part, now())
                                                ON CONFLICT (track_id)
                                                    DO UPDATE SET
                                                            total_earned = total,
                                                                    creator_share = creator_part,
                                                                            mtaa_share = mtaa_part,
                                                                                    last_updated = now();

                                                                                        RETURN NEW;
                                                                                        END;
                                                                                        $$;


