CREATE OR REPLACE FUNCTION "public"."update_trust_on_verification"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
    IF NEW.is_verified = TRUE AND OLD.is_verified = FALSE THEN
        INSERT INTO trust_scores (user_id, overall_score, identity_score)
        VALUES (NEW.user_id, 70, 70)
        ON CONFLICT (user_id) DO UPDATE SET
            identity_score = 70,
            overall_score = (trust_scores.transaction_score + trust_scores.behavior_score + trust_scores.social_score + 70) / 4;
    END IF;
    RETURN NEW;
END;
$$;


