CREATE OR REPLACE FUNCTION "public"."update_wallet_balance"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN
  IF NEW.status = 'completed' AND NEW.wallet_id IS NOT NULL THEN
    IF NEW.transaction_type IN ('credit', 'deposit', 'refund') THEN
      UPDATE public.wallets 
      SET balance = balance + NEW.amount, available_balance = available_balance + NEW.amount, updated_at = now() 
      WHERE id = NEW.wallet_id;
    ELSIF NEW.transaction_type IN ('debit', 'withdrawal', 'payment') THEN
      UPDATE public.wallets 
      SET balance = balance - NEW.amount, available_balance = available_balance - NEW.amount, updated_at = now() 
      WHERE id = NEW.wallet_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."update_wallet_balance"() OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."update_wallet_balance"("p_user" "uuid") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
begin
  update public.wallets w
    set
        balance = coalesce((
              select sum(t.amount)
                    from public.wallet_transactions t
                          where t.wallet_id = w.id
                                  and coalesce(t.status, 'completed') = 'completed'
                                      ), 0),
                                          updated_at = now()
                                            where w.owner_id = p_user;
                                            end;
                                            $$;


