CREATE OR REPLACE FUNCTION "public"."wallet_apply_risk_actions"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  -- HIGH RISK AUTO-FREEZE RULE
  IF NEW.risk_score >= 80 THEN
    UPDATE wallets
    SET is_frozen = true,
        risk_level = 'high',
        risk_score = NEW.risk_score
    WHERE id = NEW.wallet_id;
  END IF;

  -- MEDIUM RISK UPDATE
  IF NEW.risk_score BETWEEN 50 AND 79 THEN
    UPDATE wallets
    SET risk_level = 'medium',
        risk_score = NEW.risk_score
    WHERE id = NEW.wallet_id;
  END IF;

  RETURN NEW;

END;
$$;


ALTER FUNCTION "public"."wallet_apply_risk_actions"() OWNER TO "postgres";


