CREATE OR REPLACE FUNCTION "public"."wallet_credit"("_user_id" "uuid", "_amount" numeric, "_reference" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  update public.wallets
  set balance = balance + _amount,
      updated_at = now()
  where user_id = _user_id;

  insert into public.wallet_transactions(user_id, amount, type, reference, created_at)
  values (_user_id, _amount, 'credit', _reference, now());
end;
$$;


