    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
begin
  update public.wallets
  set balance = balance - _amount,
      updated_at = now()
  where user_id = _user_id
  and balance >= _amount;

  insert into public.wallet_transactions(user_id, amount, type, reference, created_at)
  values (_user_id, -_amount, 'debit', _reference, now());
end;
$$;


