CREATE OR REPLACE FUNCTION "public"."wallet_deposit"("wallet" "uuid", "amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

tx_id uuid;
wallet_account uuid;

begin

insert into public.ledger_transactions(reference,transaction_type)
values(gen_random_uuid()::text,'deposit')
returning id into tx_id;

select id into wallet_account
from public.ledger_accounts
where wallet_id = wallet
limit 1;

insert into public.ledger_entries(transaction_id,account_id,entry_type,amount)
values
(tx_id,wallet_account,'credit',amount);

insert into public.wallet_events(user_id,event_type,reference_id)
values(auth.uid(),'deposit',tx_id);

return tx_id;

end;

$$;


