CREATE OR REPLACE FUNCTION "public"."wallet_fraud_check"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  recent_count integer;
  total_volume numeric;
BEGIN

  -- Count last 10 minutes activity
  SELECT COUNT(*)
  INTO recent_count
  FROM wallet_transactions
  WHERE wallet_id = NEW.wallet_id
    AND created_at > now() - interval '10 minutes';

  -- Sum volume in last 10 minutes
  SELECT COALESCE(SUM(amount),0)
  INTO total_volume
  FROM wallet_transactions
  WHERE wallet_id = NEW.wallet_id
    AND created_at > now() - interval '10 minutes'
    AND direction = 'outbound';

  -- Risk logic
  IF recent_count > 20 OR total_volume > 100000 THEN

    INSERT INTO wallet_risk_scores (wallet_id, risk_score, risk_level, last_updated)
    VALUES (NEW.wallet_id, 80, 'high', now())
    ON CONFLICT (wallet_id)
    DO UPDATE SET
      risk_score = 80,
      risk_level = 'high',
      last_updated = now();

    RAISE NOTICE 'HIGH RISK ACTIVITY DETECTED';

  ELSIF recent_count > 10 THEN

    INSERT INTO wallet_risk_scores (wallet_id, risk_score, risk_level, last_updated)
    VALUES (NEW.wallet_id, 50, 'medium', now())
    ON CONFLICT (wallet_id)
    DO UPDATE SET
      risk_score = 50,
      risk_level = 'medium',
      last_updated = now();

  END IF;

  RETURN NEW;
END;
$$;


ALTER FUNCTION "public"."wallet_fraud_check"() OWNER TO "postgres";


