CREATE OR REPLACE FUNCTION "public"."wallet_partner_approve"("p_application_id" "uuid", "p_approved_by" "uuid", "p_commission_rate" numeric DEFAULT 2.5, "p_notes" "text" DEFAULT NULL::"text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_app record;
  v_partner record;
BEGIN
  -- Check if caller is admin
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = p_approved_by AND role = 'admin'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Get application
  SELECT * INTO v_app 
  FROM public.wallet_partner_applications 
  WHERE id = p_application_id;
  
  IF v_app IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application not found');
  END IF;

  -- Update application
  UPDATE public.wallet_partner_applications
  SET status = 'approved',
      reviewed_by = p_approved_by,
      reviewed_at = now(),
      review_notes = p_notes
  WHERE id = p_application_id;

  -- Create partner
  INSERT INTO public.wallet_partners (
    application_id, partner_category, partner_type, organization_name,
    registration_number, country, city, contact_name, contact_email,
    contact_phone, website, services_offered, description,
    estimated_premium_min, estimated_premium_max, target_market,
    jurisdiction, department, authorization_level,
    commission_rate, status, approved_by, approved_at
  ) VALUES (
    v_app.id, v_app.partner_category, v_app.partner_type, v_app.organization_name,
    v_app.registration_number, v_app.country, v_app.city, v_app.contact_name,
    v_app.contact_email, v_app.contact_phone, v_app.website, v_app.services_offered,
    v_app.description, v_app.estimated_premium_min, v_app.estimated_premium_max,
    v_app.target_market, v_app.jurisdiction, v_app.department,
    COALESCE(v_app.authorization_level, 1), p_commission_rate, 'active',
    p_approved_by, now()
  )
  RETURNING * INTO v_partner;

  -- Audit log
  INSERT INTO public.wallet_audit_logs (table_name, record_id, action, performed_by, details)
  VALUES ('wallet_partner_applications', p_application_id, 'APPROVE', p_approved_by,
    jsonb_build_object('partner_id', v_partner.id, 'organization_name', v_app.organization_name));

  RETURN jsonb_build_object('success', true, 'partner', to_jsonb(v_partner));
END;
$$;


ALTER FUNCTION "public"."wallet_partner_approve"("p_application_id" "uuid", "p_approved_by" "uuid", "p_commission_rate" numeric, "p_notes" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wallet_partner_reject"("p_application_id" "uuid", "p_rejected_by" "uuid", "p_reason" "text") RETURNS "jsonb"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_app record;
BEGIN
  -- Check if caller is admin
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles 
    WHERE id = p_rejected_by AND role = 'admin'
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Not authorized');
  END IF;

  -- Get application
  SELECT * INTO v_app 
  FROM public.wallet_partner_applications 
  WHERE id = p_application_id;
  
  IF v_app IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Application not found');
  END IF;

  -- Update application
  UPDATE public.wallet_partner_applications
  SET status = 'rejected',
      reviewed_by = p_rejected_by,
      reviewed_at = now(),
      review_notes = p_reason
  WHERE id = p_application_id;

  -- Audit log
  INSERT INTO public.wallet_audit_logs (table_name, record_id, action, performed_by, details)
  VALUES ('wallet_partner_applications', p_application_id, 'REJECT', p_rejected_by,
    jsonb_build_object('reason', p_reason, 'organization_name', v_app.organization_name));

  RETURN jsonb_build_object('success', true, 'data', to_jsonb(v_app));
END;
$$;


