CREATE OR REPLACE FUNCTION "public"."wallet_replay_protection"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
BEGIN

  IF EXISTS (
    SELECT 1 FROM wallet_transactions
    WHERE tx_hash = NEW.tx_hash
    LIMIT 1
  ) THEN
    RAISE EXCEPTION 'Replay attack detected: duplicate transaction hash';
  END IF;

  RETURN NEW;

END;
$$;


