CREATE OR REPLACE FUNCTION "public"."wallet_send"("p_sender" "uuid", "p_receiver" "uuid", "p_amount" numeric) RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
      declare
        sender_wallet uuid;
          receiver_wallet uuid;
          begin

            select id into sender_wallet
              from public.wallets
                where owner_id = p_sender;

                  select id into receiver_wallet
                    from public.wallets
                      where owner_id = p_receiver;

                        if sender_wallet is null then
                            raise exception 'Sender wallet not found';
                              end if;

                                if receiver_wallet is null then
                                    raise exception 'Receiver wallet not found';
                                      end if;

                                        insert into public.wallet_transactions
                                          (user_id, wallet_id, transaction_type, amount, status)
                                            values
                                              (p_sender, sender_wallet, 'send', -p_amount, 'completed');

                                                insert into public.wallet_transactions
                                                  (user_id, wallet_id, transaction_type, amount, status)
                                                    values
                                                      (p_receiver, receiver_wallet, 'receive', p_amount, 'completed');

                                                      end;
                                                      $$;


ALTER FUNCTION "public"."wallet_send"("p_sender" "uuid", "p_receiver" "uuid", "p_amount" numeric) OWNER TO "postgres";


