CREATE OR REPLACE FUNCTION "public"."wallet_transfer"("sender_wallet" "uuid", "receiver_wallet" "uuid", "amount" numeric) RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$

declare

tx_id uuid;
sender_account uuid;
receiver_account uuid;

begin

insert into public.ledger_transactions(reference,transaction_type)
values(gen_random_uuid()::text,'transfer')
returning id into tx_id;

select id into sender_account
from public.ledger_accounts
where wallet_id = sender_wallet
limit 1;

select id into receiver_account
from public.ledger_accounts
where wallet_id = receiver_wallet
limit 1;

insert into public.ledger_entries(transaction_id,account_id,entry_type,amount)

values
(tx_id,sender_account,'debit',amount),
(tx_id,receiver_account,'credit',amount);

insert into public.wallet_events(user_id,event_type,reference_id)
values(auth.uid(),'transfer',tx_id);

return tx_id;

end;

$$;


ALTER FUNCTION "public"."wallet_transfer"("sender_wallet" "uuid", "receiver_wallet" "uuid", "amount" numeric) OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wallet_transfer"("p_sender_wallet_id" "uuid", "p_recipient_wallet_id" "uuid", "p_amount" numeric, "p_description" "text" DEFAULT 'P2P Transfer'::"text") RETURNS "uuid"
    LANGUAGE "plpgsql" SECURITY DEFINER
    AS $$
DECLARE
  v_sender_wallet record;
  v_recipient_wallet record;
  v_transaction_id uuid;
  v_fee numeric;
BEGIN
  SELECT * INTO v_sender_wallet 
  FROM public.wallets 
  WHERE id = p_sender_wallet_id 
  FOR UPDATE;
  
  IF NOT FOUND OR v_sender_wallet.is_frozen THEN
    RAISE EXCEPTION 'Sender wallet not found or frozen';
  END IF;
  
  IF v_sender_wallet.available_balance < p_amount THEN
    RAISE EXCEPTION 'Insufficient balance';
  END IF;
  
  SELECT * INTO v_recipient_wallet 
  FROM public.wallets 
  WHERE id = p_recipient_wallet_id;
  
  IF NOT FOUND OR v_recipient_wallet.is_frozen THEN
    RAISE EXCEPTION 'Recipient wallet not found or frozen';
  END IF;
  
  v_fee := 0;
  
  UPDATE public.wallets 
  SET balance = balance - p_amount,
      available_balance = available_balance - p_amount,
      updated_at = now()
  WHERE id = p_sender_wallet_id;
  
  UPDATE public.wallets 
  SET balance = balance + p_amount,
      available_balance = available_balance + p_amount,
      updated_at = now()
  WHERE id = p_recipient_wallet_id;
  
  INSERT INTO public.transactions (
    transaction_code, wallet_id, account_id, transaction_type, status,
    amount, currency, fee_amount, net_amount, balance_before, balance_after,
    recipient_wallet_id, recipient_name, description, reference, metadata
  ) VALUES (
    'TXN-' || substr(md5(random()::text), 1, 12), 
    p_sender_wallet_id, v_sender_wallet.account_id, 'transfer', 'completed',
    p_amount, v_sender_wallet.currency, v_fee, p_amount - v_fee,
    v_sender_wallet.balance, v_sender_wallet.balance - p_amount,
    p_recipient_wallet_id, v_recipient_wallet.wallet_name, p_description,
    'P2P-' || substr(md5(random()::text), 1, 8), '{}'::jsonb
  ) RETURNING id INTO v_transaction_id;
  
  RETURN v_transaction_id;
END;
$$;


ALTER FUNCTION "public"."wallet_transfer"("p_sender_wallet_id" "uuid", "p_recipient_wallet_id" "uuid", "p_amount" numeric, "p_description" "text") OWNER TO "postgres";


CREATE OR REPLACE FUNCTION "public"."wallet_transfer"("sender" "uuid", "receiver" "uuid", "amt" numeric, "tx_type" "text", "ref" "text" DEFAULT NULL::"text") RETURNS "void"
    LANGUAGE "plpgsql"
    AS $$
            begin
              update public.wallets
                set balance = balance - amt
                  where user_id = sender and balance >= amt;

                    if not found then
                        raise exception 'Insufficient balance';
                          end if;

                            update public.wallets
                              set balance = balance + amt
                                where user_id = receiver;

                                  insert into public.transactions (
                                      from_user, to_user, amount, type, reference
                                        ) values (
                                            sender, receiver, amt, tx_type, ref
                                              );
                                              end;
                                              $$;


