CREATE OR REPLACE FUNCTION "public"."wallet_velocity_check"() RETURNS "trigger"
    LANGUAGE "plpgsql"
    AS $$
DECLARE
  tx_count int;
BEGIN
  SELECT COUNT(*)
  INTO tx_count
  FROM wallet_transactions
  WHERE user_id = NEW.user_id
  AND created_at > now() - interval '1 minute';

  IF tx_count > 10 THEN
    RAISE EXCEPTION 'Velocity limit exceeded';
  END IF;

  RETURN NEW;
END;
$$;


