CREATE OR REPLACE VIEW "public"."child_health_summary" AS
 SELECT "id" AS "child_profile_link_id",
    "guardian_profile_id",
    "child_profile_id",
    "relationship",
    "is_primary_guardian",
    ( SELECT "count"(*) AS "count"
           FROM "public"."vaccinations"
          WHERE ("vaccinations"."child_profile_id" = "cp"."id")) AS "vaccination_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."missing_child_reports"
          WHERE (("missing_child_reports"."child_profile_id" = "cp"."id") AND (("missing_child_reports"."status")::"text" = ANY ((ARRAY['reported'::character varying, 'searching'::character varying])::"text"[])))) AS "missing_reports"
   FROM "public"."child_profiles" "cp"
  WHERE ("is_active" = true);


