CREATE OR REPLACE VIEW "public"."content_stats" AS
 SELECT "content_id",
    "count"(*) FILTER (WHERE ("type" = 'like'::"text")) AS "likes",
    "count"(*) FILTER (WHERE ("type" = 'view'::"text")) AS "views",
    "count"(*) FILTER (WHERE ("type" = 'comment'::"text")) AS "comments"
   FROM "public"."interactions"
  WHERE ("content_id" IS NOT NULL)
  GROUP BY "content_id";


