COMMENT ON COLUMN "public"."posts"."body" IS 'Optional post text / caption';



CREATE OR REPLACE VIEW "public"."creator_analytics" AS
 SELECT "p"."user_id",
    "count"(DISTINCT "p"."id") AS "total_posts",
    "count"(DISTINCT "v"."id") AS "total_views",
    "count"(DISTINCT "l"."id") AS "total_likes",
    "count"(DISTINCT "c"."id") AS "total_comments"
   FROM ((("public"."posts" "p"
     LEFT JOIN "public"."post_views" "v" ON (("v"."post_id" = "p"."id")))
     LEFT JOIN "public"."post_likes" "l" ON (("l"."post_id" = "p"."id")))
     LEFT JOIN "public"."comments" "c" ON (("c"."post_id" = "p"."id")))
  WHERE ("p"."is_published" = true)
  GROUP BY "p"."user_id";


ALTER VIEW "public"."creator_analytics" OWNER TO "postgres";


