CREATE OR REPLACE VIEW "public"."gofund_dashboard" AS
 SELECT "fp"."wallet_id",
    "fp"."entity_type",
    "public"."compute_gofund_limit"("fp"."wallet_id") AS "available_credit",
    COALESCE("g"."current_debt", (0)::numeric) AS "current_debt",
    ("public"."compute_gofund_limit"("fp"."wallet_id") - COALESCE("g"."current_debt", (0)::numeric)) AS "usable_credit"
   FROM ("public"."financial_profiles" "fp"
     LEFT JOIN "public"."gofund_accounts" "g" ON (("g"."wallet_id" = "fp"."wallet_id")));


