CREATE OR REPLACE VIEW "public"."main_feed" AS
 SELECT "id",
    "user_id",
    "module",
    "title",
    "content",
    "media_url",
    "created_at",
    "hide_from_main_feed",
    "is_processing",
    "is_published"
   FROM "public"."posts"
  WHERE (("is_published" = true) AND ("is_processing" = false) AND ("hide_from_main_feed" = false))
  ORDER BY "created_at" DESC;


