CREATE OR REPLACE VIEW "public"."patient_summary" AS
 SELECT "id" AS "patient_id",
    "patient_name",
    "phone_number",
    "id_number",
    "date_of_birth",
    "gender",
    "blood_group",
    "allergies",
    "chronic_conditions",
    "current_medication",
    "emergency_contact_name",
    "emergency_contact_phone",
    "insurance_provider",
    "insurance_number",
    "primary_hospital_id",
    "primary_doctor_id",
    "wallet_id",
    "account_id",
    "biometric_template_id",
    "status",
    "triage_level",
    "created_at",
    "updated_at",
    ( SELECT "count"(*) AS "count"
           FROM "public"."health_ehr_records"
          WHERE ("health_ehr_records"."patient_id" = "pq"."id")) AS "ehr_count",
    ( SELECT "count"(*) AS "count"
           FROM "public"."health_prescriptions"
          WHERE (("health_prescriptions"."patient_id" = "pq"."id") AND (("health_prescriptions"."status")::"text" = 'active'::"text"))) AS "active_prescriptions",
    ( SELECT "count"(*) AS "count"
           FROM "public"."health_lab_orders"
          WHERE (("health_lab_orders"."patient_id" = "pq"."id") AND (("health_lab_orders"."status")::"text" = ANY ((ARRAY['ordered'::character varying, 'in_progress'::character varying])::"text"[])))) AS "pending_labs",
    ( SELECT "count"(*) AS "count"
           FROM "public"."health_imaging_orders"
          WHERE (("health_imaging_orders"."patient_id" = "pq"."id") AND (("health_imaging_orders"."status")::"text" = ANY ((ARRAY['ordered'::character varying, 'scheduled'::character varying, 'in_progress'::character varying])::"text"[])))) AS "pending_imaging",
    ( SELECT "count"(*) AS "count"
           FROM "public"."vaccinations"
          WHERE ("vaccinations"."patient_id" = "pq"."id")) AS "vaccination_count"
   FROM "public"."health_patient_queues" "pq";


ALTER VIEW "public"."patient_summary" OWNER TO "postgres";


