CREATE OR REPLACE VIEW "public"."public_participation_by_county" AS
 SELECT "pp"."county_id",
    "c"."name" AS "county_name",
    "count"(*) AS "total_participations",
    "count"(
        CASE
            WHEN (("pp"."participation_type")::"text" = 'vote'::"text") THEN 1
            ELSE NULL::integer
        END) AS "votes",
    "count"(
        CASE
            WHEN (("pp"."participation_type")::"text" = 'comment'::"text") THEN 1
            ELSE NULL::integer
        END) AS "comments",
    "count"(
        CASE
            WHEN (("pp"."participation_type")::"text" = 'petition'::"text") THEN 1
            ELSE NULL::integer
        END) AS "petitions",
    "count"(
        CASE
            WHEN (("pp"."vote")::"text" = 'support'::"text") THEN 1
            ELSE NULL::integer
        END) AS "support_votes",
    "count"(
        CASE
            WHEN (("pp"."vote")::"text" = 'oppose'::"text") THEN 1
            ELSE NULL::integer
        END) AS "oppose_votes",
    "count"(DISTINCT "pp"."citizen_id") AS "unique_citizens"
   FROM ("public"."public_participation" "pp"
     LEFT JOIN "public"."counties" "c" ON (("pp"."county_id" = "c"."id")))
  WHERE ("pp"."county_id" IS NOT NULL)
  GROUP BY "pp"."county_id", "c"."name";


ALTER VIEW "public"."public_participation_by_county" OWNER TO "postgres";


