CREATE OR REPLACE VIEW "public"."transaction_summary" AS
 SELECT "t"."id",
    "t"."created_at",
    "t"."updated_at",
    "t"."transaction_code",
    "t"."wallet_id",
    "t"."account_id",
    "t"."transaction_type",
    "t"."status",
    "t"."amount",
    "t"."currency",
    "t"."fee_amount",
    "t"."tax_amount",
    "t"."net_amount",
    "t"."balance_before",
    "t"."balance_after",
    "t"."recipient_wallet_id",
    "t"."recipient_account_id",
    "t"."recipient_type",
    "t"."recipient_id",
    "t"."recipient_name",
    "t"."recipient_phone",
    "t"."description",
    "t"."reference",
    "t"."external_transaction_id",
    "t"."payment_method",
    "t"."payment_provider",
    "t"."metadata",
    "t"."compliance_flag",
    "t"."compliance_reviewed_at",
    "t"."reversal_of",
    "t"."reversed_at",
    "t"."reversed_by",
    "t"."reversal_reason",
    "t"."risk_score",
    "a"."user_id",
    "p"."full_name" AS "user_full_name",
    "p"."phone" AS "user_phone"
   FROM (("public"."transactions" "t"
     LEFT JOIN "public"."accounts" "a" ON (("t"."account_id" = "a"."id")))
     LEFT JOIN "public"."profiles" "p" ON (("a"."user_id" = "p"."user_id")));


ALTER VIEW "public"."transaction_summary" OWNER TO "postgres";


