    "table_name" character varying(50) NOT NULL,
    "record_id" "uuid" NOT NULL,
    "action" character varying(20),
    "old_data" "jsonb",
    "new_data" "jsonb",
    "changed_by" "uuid",
    "changed_at" timestamp with time zone DEFAULT "now"(),
    "session_id" "uuid",
    "ip_address" "inet",
    "user_agent" "text",
    CONSTRAINT "treasury_audit_logs_action_check" CHECK ((("action")::"text" = ANY ((ARRAY['INSERT'::character varying, 'UPDATE'::character varying, 'DELETE'::character varying])::"text"[])))
);


ALTER TABLE "public"."treasury_audit_logs" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."treasury_audit_overdue" AS
 SELECT "id",
    "audit_reference",
    "audit_type",
    "finding_title",
    "risk_rating",
    "amount_involved",
    "target_resolution_date",
    "status",
        CASE
            WHEN ("target_resolution_date" < CURRENT_DATE) THEN (CURRENT_DATE - "target_resolution_date")
            ELSE 0
        END AS "days_overdue"
   FROM "public"."treasury_audit_findings" "af"
  WHERE ((("status")::"text" = ANY ((ARRAY['open'::character varying, 'in_progress'::character varying, 'overdue'::character varying])::"text"[])) AND ("target_resolution_date" IS NOT NULL));


ALTER VIEW "public"."treasury_audit_overdue" OWNER TO "postgres";


