    "status" character varying(20) DEFAULT 'pending'::character varying,
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "treasury_bank_reconciliations_reconciliation_period_check" CHECK ((("reconciliation_period")::"text" = ANY ((ARRAY['daily'::character varying, 'weekly'::character varying, 'monthly'::character varying])::"text"[]))),
    CONSTRAINT "treasury_bank_reconciliations_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['pending'::character varying, 'in_progress'::character varying, 'reconciled'::character varying, 'disputed'::character varying, 'approved'::character varying])::"text"[])))
);


