    CONSTRAINT "treasury_budget_cycles_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'submitted'::character varying, 'approved'::character varying, 'rejected'::character varying, 'active'::character varying, 'closed'::character varying])::"text"[])))
