CREATE OR REPLACE VIEW "public"."treasury_budget_execution_summary" AS
 SELECT "bc"."fiscal_year",
    "ba"."ministry_id",
    "ba"."program_code",
    "ba"."program_name",
    "ba"."approved_amount",
    "ba"."released_amount",
    "ba"."spent_amount",
    "ba"."commitment_amount",
    "ba"."available_balance",
    "round"((("ba"."spent_amount" / NULLIF("ba"."approved_amount", (0)::numeric)) * (100)::numeric), 2) AS "execution_rate",
    "round"((("ba"."commitment_amount" / NULLIF("ba"."approved_amount", (0)::numeric)) * (100)::numeric), 2) AS "commitment_rate"
   FROM ("public"."treasury_budget_allocations" "ba"
     JOIN "public"."treasury_budget_cycles" "bc" ON (("ba"."budget_cycle_id" = "bc"."id")))
  WHERE (("bc"."status")::"text" = 'active'::"text");


ALTER VIEW "public"."treasury_budget_execution_summary" OWNER TO "postgres";


