    CONSTRAINT "treasury_tsa_transactions_transaction_type_check" CHECK ((("transaction_type")::"text" = ANY ((ARRAY['receipt'::character varying, 'payment'::character varying, 'transfer'::character varying, 'reversal'::character varying, 'adjustment'::character varying])::"text"[])))
