CREATE OR REPLACE VIEW "public"."treasury_cash_position" AS
 SELECT "tsa"."id",
    "tsa"."account_name",
    "tsa"."account_type",
    "tsa"."currency",
    "tsa"."current_balance",
    COALESCE("sum"(
        CASE
            WHEN ((("tst"."transaction_type")::"text" = 'receipt'::"text") AND (("tst"."status")::"text" = 'completed'::"text")) THEN "tst"."amount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_receipts_30d",
    COALESCE("sum"(
        CASE
            WHEN ((("tst"."transaction_type")::"text" = 'payment'::"text") AND (("tst"."status")::"text" = 'completed'::"text")) THEN "tst"."amount"
            ELSE (0)::numeric
        END), (0)::numeric) AS "total_payments_30d"
   FROM ("public"."treasury_tsa_accounts" "tsa"
     LEFT JOIN "public"."treasury_tsa_transactions" "tst" ON ((("tsa"."id" = "tst"."tsa_account_id") AND ("tst"."transaction_date" >= (CURRENT_DATE - '30 days'::interval)))))
  GROUP BY "tsa"."id", "tsa"."account_name", "tsa"."account_type", "tsa"."currency", "tsa"."current_balance";


ALTER VIEW "public"."treasury_cash_position" OWNER TO "postgres";


