CREATE OR REPLACE VIEW "public"."treasury_contract_performance" AS
 SELECT "c"."id",
    "c"."contract_number",
    "c"."supplier_name",
    "c"."contract_value",
    "c"."total_paid",
    "c"."remaining_value",
    "c"."performance_rating",
    "c"."status",
    "t"."tender_number",
    "t"."bids_received",
        CASE
            WHEN ("c"."contract_value" > (0)::numeric) THEN "round"((("c"."total_paid" / "c"."contract_value") * (100)::numeric), 2)
            ELSE (0)::numeric
        END AS "payment_progress",
        CASE
            WHEN (("c"."end_date" IS NOT NULL) AND ("c"."start_date" IS NOT NULL)) THEN "round"(((((CURRENT_DATE - "c"."start_date"))::numeric / NULLIF((("c"."end_date" - "c"."start_date"))::numeric, (0)::numeric)) * (100)::numeric), 2)
            ELSE NULL::numeric
        END AS "time_progress"
   FROM ("public"."treasury_contracts" "c"
     LEFT JOIN "public"."treasury_tenders" "t" ON (("c"."tender_id" = "t"."id")));


ALTER VIEW "public"."treasury_contract_performance" OWNER TO "postgres";


