    CONSTRAINT "treasury_debt_instruments_instrument_type_check" CHECK ((("instrument_type")::"text" = ANY ((ARRAY['external_bilateral'::character varying, 'external_multilateral'::character varying, 'external_commercial'::character varying, 'domestic_treasury_bill'::character varying, 'domestic_treasury_bond'::character varying, 'domestic_sukuk'::character varying, 'guarantee'::character varying, 'on_lending'::character varying])::"text"[]))),
    CONSTRAINT "treasury_debt_instruments_interest_type_check" CHECK ((("interest_type")::"text" = ANY ((ARRAY['fixed'::character varying, 'floating'::character varying, 'zero_coupon'::character varying, 'concessional'::character varying])::"text"[]))),
    CONSTRAINT "treasury_debt_instruments_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['active'::character varying, 'fully_disbursed'::character varying, 'repaid'::character varying, 'defaulted'::character varying, 'restructured'::character varying, 'cancelled'::character varying])::"text"[])))
);


