CREATE TABLE IF NOT EXISTS "public"."treasury_debt_payments" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "instrument_id" "uuid",
    "payment_type" character varying(20),
    "amount_due" numeric(18,2) NOT NULL,
    "amount_paid" numeric(18,2) DEFAULT 0,
    "payment_date" "date",
    "due_date" "date" NOT NULL,
    "currency" character varying(3) NOT NULL,
    "exchange_rate" numeric(18,6) DEFAULT 1,
    "local_amount" numeric(18,2) GENERATED ALWAYS AS (("amount_paid" * "exchange_rate")) STORED,
    "payment_method" character varying(20),
    "bank_transaction_ref" character varying(100),
    "wallet_transaction_id" "uuid",
    "status" character varying(20) DEFAULT 'scheduled'::character varying,
    "approved_by" "uuid",
    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "treasury_debt_payments_payment_type_check" CHECK ((("payment_type")::"text" = ANY ((ARRAY['principal'::character varying, 'interest'::character varying, 'commitment_fee'::character varying, 'service_charge'::character varying, 'penalty'::character varying])::"text"[]))),
    CONSTRAINT "treasury_debt_payments_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['scheduled'::character varying, 'pending_approval'::character varying, 'approved'::character varying, 'paid'::character varying, 'overdue'::character varying, 'defaulted'::character varying])::"text"[])))
);


ALTER TABLE "public"."treasury_debt_payments" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."treasury_debt_service_schedule" AS
 SELECT "di"."instrument_code",
    "di"."creditor_name",
    "di"."currency",
    "dp"."payment_type",
    "dp"."due_date",
    "dp"."amount_due",
    "dp"."amount_paid",
    "dp"."status",
    "di"."maturity_date",
    "di"."outstanding_principal"
   FROM ("public"."treasury_debt_instruments" "di"
     JOIN "public"."treasury_debt_payments" "dp" ON (("di"."id" = "dp"."instrument_id")))
  WHERE (("dp"."due_date" >= CURRENT_DATE) AND ("dp"."due_date" <= (CURRENT_DATE + '90 days'::interval)))
  ORDER BY "dp"."due_date";


ALTER VIEW "public"."treasury_debt_service_schedule" OWNER TO "postgres";


