    "item_description" "text" NOT NULL,
    "quantity" integer NOT NULL,
    "estimated_unit_cost" numeric(18,2) NOT NULL,
    "estimated_total_cost" numeric(18,2) GENERATED ALWAYS AS ((("quantity")::numeric * "estimated_unit_cost")) STORED,
    "procurement_method" character varying(30),
    "urgency_level" character varying(20),
    "budget_allocation_id" "uuid",
    "status" character varying(20) DEFAULT 'draft'::character varying,
