    "created_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "treasury_procurement_requisitions_procurement_method_check" CHECK ((("procurement_method")::"text" = ANY ((ARRAY['open_tender'::character varying, 'restricted_tender'::character varying, 'direct_procurement'::character varying, 'request_for_quotation'::character varying, 'framework_agreement'::character varying, 'emergency'::character varying])::"text"[]))),
    CONSTRAINT "treasury_procurement_requisitions_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'submitted'::character varying, 'under_review'::character varying, 'approved'::character varying, 'rejected'::character varying, 'converted_to_tender'::character varying])::"text"[]))),
    CONSTRAINT "treasury_procurement_requisitions_urgency_level_check" CHECK ((("urgency_level")::"text" = ANY ((ARRAY['low'::character varying, 'medium'::character varying, 'high'::character varying, 'critical'::character varying])::"text"[])))
);


