CREATE OR REPLACE VIEW "public"."treasury_procurement_status" AS
 SELECT "pr"."requisition_number",
    "pr"."ministry_id",
    "pr"."item_description",
    "pr"."estimated_total_cost",
    "pr"."status" AS "requisition_status",
    "t"."tender_number",
    "t"."tender_type",
    "t"."estimated_value",
    "t"."status" AS "tender_status",
    "c"."contract_number",
    "c"."supplier_name",
    "c"."contract_value",
    "c"."total_paid",
    "c"."remaining_value",
    "c"."status" AS "contract_status"
   FROM (("public"."treasury_procurement_requisitions" "pr"
     LEFT JOIN "public"."treasury_tenders" "t" ON (("pr"."id" = "t"."requisition_id")))
     LEFT JOIN "public"."treasury_contracts" "c" ON (("t"."id" = "c"."tender_id")));


