CREATE OR REPLACE VIEW "public"."treasury_revenue_summary" AS
 SELECT (EXTRACT(year FROM "collection_date"))::integer AS "fiscal_year",
    "revenue_source",
    "sum"("amount") AS "total_collected",
    "count"(*) AS "transaction_count",
    "avg"("amount") AS "avg_transaction",
    "min"("collection_date") AS "first_collection",
    "max"("collection_date") AS "last_collection"
   FROM "public"."treasury_revenue_collections"
  GROUP BY ((EXTRACT(year FROM "collection_date"))::integer), "revenue_source";


