CREATE OR REPLACE VIEW "public"."v_active_properties" AS
 SELECT "p"."id",
    "p"."owner_id",
    "p"."owner_type",
    "p"."title",
    "p"."description",
    "p"."property_type",
    "p"."listing_type",
    "p"."country",
    "p"."county",
    "p"."town",
    "p"."street",
    "p"."estate",
    "p"."village",
    "p"."building_name",
    "p"."unit_number",
    "p"."latitude",
    "p"."longitude",
    "p"."full_address",
    "p"."bedrooms",
    "p"."bathrooms",
    "p"."square_feet",
    "p"."floor_number",
    "p"."total_floors",
    "p"."year_built",
    "p"."furnished",
    "p"."price_per_night",
    "p"."price_per_month",
    "p"."price_per_year",
    "p"."deposit_amount",
    "p"."cleaning_fee",
    "p"."service_fee",
    "p"."currency",
    "p"."amenities",
    "p"."house_rules",
    "p"."min_stay_nights",
    "p"."max_stay_nights",
    "p"."instant_book",
    "p"."status",
    "p"."verification_status",
    "p"."cover_image",
    "p"."video_url",
    "p"."view_count",
    "p"."booking_count",
    "p"."review_count",
    "p"."average_rating",
    "p"."search_vector",
    "p"."tags",
    "p"."created_at",
    "p"."updated_at",
    "p"."published_at",
    "p"."deleted_at",
    "pr"."full_name" AS "owner_name",
    "pr"."avatar_url" AS "owner_avatar",
    "pr"."phone" AS "owner_phone"
   FROM ("public"."properties" "p"
     JOIN "public"."profiles" "pr" ON (("p"."owner_id" = "pr"."id")))
  WHERE (("p"."status" = 'active'::"text") AND ("p"."deleted_at" IS NULL));


