CREATE OR REPLACE VIEW "public"."v_landlord_dashboard" AS
 SELECT "l"."profile_id",
    "l"."landlord_status",
    "l"."total_properties",
    "l"."total_tenants",
    "l"."total_revenue",
    "count"(DISTINCT "prop"."id") AS "active_properties",
    "count"(DISTINCT "ls"."id") AS "active_leases",
    "count"(DISTINCT "mt"."id") AS "open_maintenance_tickets",
    COALESCE("sum"("pp"."amount"), (0)::numeric) AS "total_collected_this_month"
   FROM (((("public"."landlords" "l"
     LEFT JOIN "public"."properties" "prop" ON ((("l"."profile_id" = "prop"."owner_id") AND ("prop"."status" = 'active'::"text"))))
     LEFT JOIN "public"."leases" "ls" ON ((("l"."profile_id" = "ls"."landlord_id") AND ("ls"."status" = 'active'::"text"))))
     LEFT JOIN "public"."maintenance_tickets" "mt" ON ((("l"."profile_id" = "mt"."landlord_id") AND ("mt"."status" <> ALL (ARRAY['closed'::"text", 'paid'::"text"])))))
     LEFT JOIN "public"."property_payments" "pp" ON ((("l"."profile_id" = "pp"."payee_id") AND ("pp"."payment_type" = 'rent'::"text") AND ("date_trunc"('month'::"text", "pp"."created_at") = "date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone)))))
  GROUP BY "l"."profile_id", "l"."landlord_status", "l"."total_properties", "l"."total_tenants", "l"."total_revenue";


ALTER VIEW "public"."v_landlord_dashboard" OWNER TO "postgres";


