  GROUP BY "p"."id", "p"."pool_name";


ALTER VIEW "public"."v_pool_balances" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_post_cards_compat" AS
 WITH "first_media" AS (
         SELECT "pm"."post_id",
            "pm"."media_url",
            "pm"."media_type",
            "row_number"() OVER (PARTITION BY "pm"."post_id" ORDER BY "pm"."position", "pm"."created_at") AS "rn"
           FROM "public"."post_media" "pm"
        ), "like_counts" AS (
         SELECT "post_likes"."post_id",
            "count"(*) AS "likes_count"
           FROM "public"."post_likes"
          GROUP BY "post_likes"."post_id"
        ), "save_counts" AS (
         SELECT "post_saves"."post_id",
            "count"(*) AS "saves_count"
           FROM "public"."post_saves"
          GROUP BY "post_saves"."post_id"
        ), "share_counts" AS (
         SELECT "post_shares"."post_id",
            "count"(*) AS "shares_count"
           FROM "public"."post_shares"
          GROUP BY "post_shares"."post_id"
        ), "comment_counts" AS (
         SELECT "comments"."post_id",
            "count"(*) AS "comments_count"
           FROM "public"."comments"
          GROUP BY "comments"."post_id"
        )
 SELECT "p"."id",
    "p"."user_id",
    "p"."created_at",
    COALESCE("p"."media_url", "fm"."media_url") AS "media_url",
    COALESCE("fm"."media_type",
        CASE
            WHEN (COALESCE("p"."media_url", "fm"."media_url") ~* '\.(mp4|mov|m4v|webm)$'::"text") THEN 'video'::"text"
            WHEN (COALESCE("p"."media_url", "fm"."media_url") ~* '\.(jpg|jpeg|png|gif|webp)$'::"text") THEN 'image'::"text"
            ELSE 'video'::"text"
        END) AS "media_type",
    COALESCE(NULLIF("p"."content", ''::"text"), NULLIF("p"."body", ''::"text"), NULLIF("p"."title", ''::"text"), ''::"text") AS "caption",
    COALESCE("ps"."views", (0)::bigint) AS "views",
    COALESCE("lc"."likes_count", (0)::bigint) AS "likes_count",
    COALESCE("cc"."comments_count", (0)::bigint) AS "comments_count",
    COALESCE("sc"."saves_count", (0)::bigint) AS "saves_count",
    COALESCE("shc"."shares_count", (0)::bigint) AS "shares_count"
   FROM (((((("public"."posts" "p"
     LEFT JOIN "public"."post_stats" "ps" ON (("ps"."post_id" = "p"."id")))
     LEFT JOIN "first_media" "fm" ON ((("fm"."post_id" = "p"."id") AND ("fm"."rn" = 1))))
     LEFT JOIN "like_counts" "lc" ON (("lc"."post_id" = "p"."id")))
     LEFT JOIN "comment_counts" "cc" ON (("cc"."post_id" = "p"."id")))
     LEFT JOIN "save_counts" "sc" ON (("sc"."post_id" = "p"."id")))
     LEFT JOIN "share_counts" "shc" ON (("shc"."post_id" = "p"."id")))
  WHERE ((COALESCE("p"."is_published", true) = true) AND (COALESCE("p"."hide_from_main_feed", false) = false));


ALTER VIEW "public"."v_post_cards_compat" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_property_revenue" AS
 SELECT "p"."id" AS "property_id",
    "p"."title",
    "p"."property_type",
    "p"."listing_type",
    COALESCE("sum"("pp"."amount"), (0)::numeric) AS "total_revenue",
    "count"(DISTINCT "pp"."id") AS "total_transactions",
    "count"(DISTINCT "pb"."id") AS "total_bookings",
    "count"(DISTINCT "ls"."id") AS "total_leases"
   FROM ((("public"."properties" "p"
     LEFT JOIN "public"."property_payments" "pp" ON ((("p"."id" = "pp"."property_id") AND ("pp"."status" = 'completed'::"text"))))
     LEFT JOIN "public"."property_bookings" "pb" ON ((("p"."id" = "pb"."property_id") AND ("pb"."booking_status" = 'checked_out'::"text"))))
     LEFT JOIN "public"."leases" "ls" ON ((("p"."id" = "ls"."property_id") AND ("ls"."status" = 'active'::"text"))))
  WHERE ("p"."deleted_at" IS NULL)
  GROUP BY "p"."id", "p"."title", "p"."property_type", "p"."listing_type";


ALTER VIEW "public"."v_property_revenue" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."v_pulse_feed_posts" AS
