CREATE OR REPLACE VIEW "public"."v_tenant_dashboard" AS
 SELECT "t"."profile_id",
    "t"."tenant_status",
    "count"(DISTINCT "l"."id") AS "active_leases",
    "count"(DISTINCT "mt"."id") AS "open_maintenance_tickets",
    COALESCE("sum"("pp"."amount"), (0)::numeric) AS "total_rent_paid",
    "count"(DISTINCT "pp"."id") AS "total_payments"
   FROM ((("public"."tenants" "t"
     LEFT JOIN "public"."leases" "l" ON ((("t"."profile_id" = "l"."tenant_id") AND ("l"."status" = 'active'::"text"))))
     LEFT JOIN "public"."maintenance_tickets" "mt" ON ((("t"."profile_id" = "mt"."tenant_id") AND ("mt"."status" <> ALL (ARRAY['closed'::"text", 'paid'::"text"])))))
     LEFT JOIN "public"."property_payments" "pp" ON ((("t"."profile_id" = "pp"."payer_id") AND ("pp"."payment_type" = 'rent'::"text"))))
  GROUP BY "t"."profile_id", "t"."tenant_status";


