CREATE TABLE IF NOT EXISTS "public"."voting_sessions" (
    "id" "uuid" DEFAULT "gen_random_uuid"() NOT NULL,
    "session_type" character varying(30) NOT NULL,
    "title" character varying(255) NOT NULL,
    "description" "text",
    "level" character varying(20) NOT NULL,
    "county_id" "uuid",
    "ward_id" "uuid",
    "committee_id" "uuid",
    "bill_number" character varying(50),
    "sponsor_id" "uuid",
    "co_sponsors" "uuid"[],
    "voting_method" character varying(20) DEFAULT 'electronic'::character varying,
    "voting_type" character varying(20) DEFAULT 'simple_majority'::character varying,
    "quorum_required" integer NOT NULL,
    "introduced_date" timestamp with time zone,
    "first_reading" timestamp with time zone,
    "second_reading" timestamp with time zone,
    "public_participation_start" timestamp with time zone,
    "public_participation_end" timestamp with time zone,
    "committee_stage" timestamp with time zone,
    "third_reading" timestamp with time zone,
    "presidential_assent" timestamp with time zone,
    "effective_date" timestamp with time zone,
    "status" character varying(30) DEFAULT 'draft'::character varying,
    "total_votes" integer DEFAULT 0,
    "yes_votes" integer DEFAULT 0,
    "no_votes" integer DEFAULT 0,
    "abstain_votes" integer DEFAULT 0,
    "absent_votes" integer DEFAULT 0,
    "result" character varying(20),
    "created_at" timestamp with time zone DEFAULT "now"(),
    "updated_at" timestamp with time zone DEFAULT "now"(),
    CONSTRAINT "voting_sessions_level_check" CHECK ((("level")::"text" = ANY ((ARRAY['national'::character varying, 'county'::character varying, 'ward'::character varying, 'committee'::character varying])::"text"[]))),
    CONSTRAINT "voting_sessions_session_type_check" CHECK ((("session_type")::"text" = ANY ((ARRAY['national_bill'::character varying, 'national_motion'::character varying, 'national_amendment'::character varying, 'national_referendum'::character varying, 'county_bill'::character varying, 'county_motion'::character varying, 'county_budget'::character varying, 'county_cfb'::character varying, 'county_project'::character varying, 'ward_bursary'::character varying, 'ward_project'::character varying, 'ward_fee'::character varying, 'ward_decision'::character varying, 'committee_vote'::character varying, 'impeachment'::character varying, 'confidence_vote'::character varying])::"text"[]))),
    CONSTRAINT "voting_sessions_status_check" CHECK ((("status")::"text" = ANY ((ARRAY['draft'::character varying, 'introduced'::character varying, 'first_reading'::character varying, 'public_participation'::character varying, 'committee_stage'::character varying, 'second_reading'::character varying, 'third_reading'::character varying, 'passed'::character varying, 'rejected'::character varying, 'presidential_assent'::character varying, 'returned'::character varying, 'signed'::character varying, 'gazetted'::character varying, 'effective'::character varying, 'lapsed'::character varying, 'withdrawn'::character varying])::"text"[]))),
    CONSTRAINT "voting_sessions_voting_method_check" CHECK ((("voting_method")::"text" = ANY ((ARRAY['electronic'::character varying, 'roll_call'::character varying, 'secret_ballot'::character varying, 'voice_vote'::character varying, 'division'::character varying])::"text"[]))),
    CONSTRAINT "voting_sessions_voting_type_check" CHECK ((("voting_type")::"text" = ANY ((ARRAY['simple_majority'::character varying, 'two_thirds'::character varying, 'three_quarters'::character varying, 'unanimous'::character varying, 'weighted'::character varying])::"text"[])))
);


ALTER TABLE "public"."voting_sessions" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."voting_results_summary" AS
 SELECT "id" AS "voting_session_id",
    "title",
    "session_type",
    "level",
    "status",
    "total_votes",
    "yes_votes",
    "no_votes",
    "abstain_votes",
    "absent_votes",
        CASE
            WHEN ((("voting_type")::"text" = 'simple_majority'::"text") AND ("yes_votes" > "no_votes")) THEN 'passed'::"text"
            WHEN ((("voting_type")::"text" = 'two_thirds'::"text") AND ((("yes_votes")::double precision / (NULLIF("total_votes", 0))::double precision) >= (0.67)::double precision)) THEN 'passed'::"text"
            WHEN ((("voting_type")::"text" = 'three_quarters'::"text") AND ((("yes_votes")::double precision / (NULLIF("total_votes", 0))::double precision) >= (0.75)::double precision)) THEN 'passed'::"text"
            WHEN ("yes_votes" > "no_votes") THEN 'passed'::"text"
            ELSE 'rejected'::"text"
        END AS "calculated_result",
    "quorum_required",
    (("yes_votes" + "no_votes") + "abstain_votes") AS "present_votes",
        CASE
            WHEN ((("yes_votes" + "no_votes") + "abstain_votes") >= "quorum_required") THEN true
            ELSE false
        END AS "quorum_met"
   FROM "public"."voting_sessions" "vs";


ALTER VIEW "public"."voting_results_summary" OWNER TO "postgres";


