CREATE OR REPLACE VIEW "public"."vw_account_balances" AS
 SELECT "a"."id" AS "account_id",
    "a"."user_id",
    "a"."account_type",
    "a"."status",
    "a"."kyc_level",
    "a"."compliance_flag",
    "count"("w"."id") AS "wallet_count",
    COALESCE("sum"("w"."balance"), (0)::numeric) AS "total_balance",
    COALESCE("sum"("w"."held_balance"), (0)::numeric) AS "total_held",
    COALESCE("sum"("w"."available_balance"), (0)::numeric) AS "total_available"
   FROM ("public"."accounts" "a"
     LEFT JOIN "public"."wallets" "w" ON ((("w"."account_id" = "a"."id") AND ("w"."status" = 'active'::"public"."wallet_status"))))
  GROUP BY "a"."id", "a"."user_id", "a"."account_type", "a"."status", "a"."kyc_level", "a"."compliance_flag";


