    NULL::timestamp with time zone AS "updated_at",
    NULL::"uuid" AS "user_id",
    NULL::"text" AS "patient_code",
    NULL::"text" AS "first_name",
    NULL::"text" AS "last_name",
    NULL::"date" AS "date_of_birth",
    NULL::"text" AS "gender",
    NULL::"text" AS "blood_type",
    NULL::"text"[] AS "allergies",
    NULL::"text"[] AS "chronic_conditions",
    NULL::"jsonb" AS "current_medications",
    NULL::"text" AS "emergency_contact_name",
    NULL::"text" AS "emergency_contact_phone",
    NULL::"text" AS "emergency_contact_relationship",
    NULL::"text" AS "insurance_provider",
    NULL::"text" AS "insurance_policy_number",
    NULL::"public"."patient_status" AS "status",
    NULL::"uuid" AS "primary_physician_id",
    NULL::"date" AS "last_visit_date",
    NULL::"jsonb" AS "metadata",
    NULL::bigint AS "total_appointments",
    NULL::bigint AS "completed_appointments",
    NULL::bigint AS "total_records",
    NULL::bigint AS "active_prescriptions",
    NULL::"date" AS "next_appointment_date";


ALTER VIEW "public"."vw_patient_summary" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_provider_schedule" AS
 SELECT "a"."id",
    "a"."created_at",
    "a"."updated_at",
    "a"."appointment_code",
    "a"."patient_id",
    "a"."provider_id",
    "a"."provider_type",
    "a"."appointment_type",
    "a"."status",
    "a"."scheduled_date",
    "a"."scheduled_time",
    "a"."duration_minutes",
    "a"."reason",
    "a"."notes",
    "a"."diagnosis",
    "a"."treatment_plan",
    "a"."follow_up_required",
    "a"."follow_up_date",
    "a"."checked_in_at",
    "a"."started_at",
    "a"."completed_at",
    "a"."cancelled_at",
    "a"."cancellation_reason",
    "a"."metadata",
    (("p"."first_name" || ' '::"text") || "p"."last_name") AS "patient_name",
    "p"."blood_type",
    "p"."allergies"
   FROM ("public"."health_appointments" "a"
     JOIN "public"."health_patients" "p" ON (("p"."id" = "a"."patient_id")))
  WHERE ("a"."status" = ANY (ARRAY['scheduled'::"public"."appointment_status", 'confirmed'::"public"."appointment_status", 'checked_in'::"public"."appointment_status", 'in_progress'::"public"."appointment_status"]))
  ORDER BY "a"."scheduled_date", "a"."scheduled_time";


ALTER VIEW "public"."vw_provider_schedule" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_published_courses" AS
SELECT
    NULL::"uuid" AS "id",
