    NULL::"text" AS "institution_name",
    NULL::numeric(6,2) AS "duration_hours",
    NULL::integer AS "duration_weeks",
    NULL::"text" AS "language",
    NULL::"text" AS "thumbnail_url",
    NULL::"text" AS "promo_video_url",
    NULL::"jsonb" AS "syllabus",
    NULL::"jsonb" AS "modules",
    NULL::"text"[] AS "prerequisites",
    NULL::"text"[] AS "learning_outcomes",
    NULL::numeric(10,2) AS "price",
