    NULL::"text" AS "certification_type",
    NULL::integer AS "max_students",
    NULL::integer AS "enrolled_count",
    NULL::integer AS "completion_count",
    NULL::numeric(3,2) AS "avg_rating",
    NULL::integer AS "review_count",
    NULL::timestamp with time zone AS "published_at",
    NULL::"jsonb" AS "metadata",
    NULL::character varying(255) AS "instructor_email",
    NULL::bigint AS "total_enrollments",
    NULL::bigint AS "total_completions",
    NULL::numeric AS "avg_final_score";


ALTER VIEW "public"."vw_published_courses" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_student_dashboard" AS
 SELECT "u"."id" AS "student_id",
    "u"."email",
    "count"(DISTINCT "e"."id") AS "total_enrollments",
    "count"(DISTINCT
        CASE
            WHEN ("e"."status" = 'completed'::"public"."enrollment_status") THEN "e"."id"
            ELSE NULL::"uuid"
        END) AS "completed_courses",
    "count"(DISTINCT
        CASE
            WHEN ("e"."status" = 'in_progress'::"public"."enrollment_status") THEN "e"."id"
            ELSE NULL::"uuid"
        END) AS "in_progress_courses",
    "count"(DISTINCT "cert"."id") AS "total_certifications",
    COALESCE("sum"("e"."amount_paid"), (0)::numeric) AS "total_spent",
    COALESCE("avg"("e"."final_score"), (0)::numeric) AS "avg_score"
   FROM (("auth"."users" "u"
     LEFT JOIN "public"."course_enrollments" "e" ON (("e"."student_id" = "u"."id")))
     LEFT JOIN "public"."certifications" "cert" ON ((("cert"."student_id" = "u"."id") AND ("cert"."status" = 'active'::"public"."certification_status"))))
  GROUP BY "u"."id", "u"."email";


ALTER VIEW "public"."vw_student_dashboard" OWNER TO "postgres";


CREATE OR REPLACE VIEW "public"."vw_user_identity_summary" AS
 SELECT "p"."user_id",
    "p"."full_name" AS "profile_name",
    "p"."email" AS "profile_email",
    "p"."phone" AS "profile_phone",
    "p"."kyc_status",
    "p"."verification_level",
    "p"."is_verified",
    "p"."trust_score",
    "p"."role",
    "p"."country",
    "p"."city",
    "k"."id" AS "kyc_submission_id",
    "k"."status" AS "kyc_status_detail",
    "k"."submitted_at",
    "k"."reviewed_at",
    "t"."overall_score" AS "trust_overall",
    "t"."identity_score",
    "t"."transaction_score",
    "t"."behavior_score",
    "t"."social_score"
   FROM (("public"."profiles" "p"
     LEFT JOIN "public"."kyc_submissions" "k" ON ((("k"."user_id" = "p"."user_id") AND ("k"."status" = 'pending'::"public"."kyc_status"))))
     LEFT JOIN "public"."trust_scores" "t" ON (("t"."user_id" = "p"."user_id")));


ALTER VIEW "public"."vw_user_identity_summary" OWNER TO "postgres";


