CREATE OR REPLACE VIEW "public"."wallet_balances" AS
 SELECT "w"."id" AS "wallet_id",
    "w"."account_id",
    "a"."user_id",
    "w"."balance",
    "w"."held_balance",
    "w"."available_balance",
    "w"."pending_balance",
    "w"."reserved_balance",
    "w"."is_frozen",
    "w"."daily_limit",
    "w"."monthly_limit",
    COALESCE("d"."daily_total", (0)::numeric) AS "daily_usage",
    COALESCE("m"."monthly_total", (0)::numeric) AS "monthly_usage"
   FROM ((("public"."wallets" "w"
     LEFT JOIN "public"."accounts" "a" ON (("w"."account_id" = "a"."id")))
     LEFT JOIN LATERAL ( SELECT "sum"("transactions"."amount") AS "daily_total"
           FROM "public"."transactions"
          WHERE (("transactions"."wallet_id" = "w"."id") AND ("transactions"."created_at" >= CURRENT_DATE) AND ("transactions"."created_at" < (CURRENT_DATE + '1 day'::interval)))) "d" ON (true))
     LEFT JOIN LATERAL ( SELECT "sum"("transactions"."amount") AS "monthly_total"
           FROM "public"."transactions"
          WHERE (("transactions"."wallet_id" = "w"."id") AND ("transactions"."created_at" >= "date_trunc"('month'::"text", (CURRENT_DATE)::timestamp with time zone)))) "m" ON (true));


ALTER VIEW "public"."wallet_balances" OWNER TO "postgres";


