    CONSTRAINT "ward_projects_project_type_check" CHECK ((("project_type")::"text" = ANY ((ARRAY['bursary'::character varying, 'infrastructure'::character varying, 'health'::character varying, 'education'::character varying, 'water'::character varying, 'electricity'::character varying, 'market'::character varying, 'security'::character varying, 'environment'::character varying, 'other'::character varying])::"text"[]))),
