CREATE OR REPLACE VIEW "public"."ward_project_rankings" AS
 SELECT "wp"."id" AS "project_id",
    "wp"."ward_id",
    "w"."name" AS "ward_name",
    "wp"."county_id",
    "c"."name" AS "county_name",
    "wp"."project_name",
    "wp"."project_type",
    "wp"."estimated_cost",
    "wp"."status",
    "count"("wpv"."id") AS "total_votes",
    "count"(
        CASE
            WHEN (("wpv"."vote_type")::"text" = 'priority'::"text") THEN 1
            ELSE NULL::integer
        END) AS "priority_votes",
    "count"(
        CASE
            WHEN (("wpv"."vote_type")::"text" = 'support'::"text") THEN 1
            ELSE NULL::integer
        END) AS "support_votes",
    "count"(
        CASE
            WHEN (("wpv"."vote_type")::"text" = 'oppose'::"text") THEN 1
            ELSE NULL::integer
        END) AS "oppose_votes",
    "avg"("wpv"."priority_rank") AS "avg_priority_rank",
    "rank"() OVER (PARTITION BY "wp"."ward_id" ORDER BY ("count"(
        CASE
            WHEN (("wpv"."vote_type")::"text" = 'priority'::"text") THEN 1
            ELSE NULL::integer
        END)) DESC) AS "ward_priority_rank"
   FROM ((("public"."ward_projects" "wp"
     JOIN "public"."wards" "w" ON (("wp"."ward_id" = "w"."id")))
     JOIN "public"."counties" "c" ON (("wp"."county_id" = "c"."id")))
     LEFT JOIN "public"."ward_project_votes" "wpv" ON (("wp"."id" = "wpv"."project_id")))
  WHERE (("wp"."status")::"text" = ANY ((ARRAY['proposed'::character varying, 'approved'::character varying])::"text"[]))
  GROUP BY "wp"."id", "wp"."ward_id", "w"."name", "wp"."county_id", "c"."name", "wp"."project_name", "wp"."project_type", "wp"."estimated_cost", "wp"."status";


ALTER VIEW "public"."ward_project_rankings" OWNER TO "postgres";


