CREATE OR REPLACE VIEW "public"."post_performance" AS
 SELECT "p"."id" AS "post_id",
    "p"."user_id",
    "count"(DISTINCT "v"."id") AS "views",
    "count"(DISTINCT "l"."id") AS "likes",
    "count"(DISTINCT "c"."id") AS "comments",
    "p"."created_at"
   FROM ((("public"."posts" "p"
     LEFT JOIN "public"."post_views" "v" ON (("v"."post_id" = "p"."id")))
     LEFT JOIN "public"."post_likes" "l" ON (("l"."post_id" = "p"."id")))
     LEFT JOIN "public"."comments" "c" ON (("c"."post_id" = "p"."id")))
  GROUP BY "p"."id";



CREATE OR REPLACE VIEW "public"."v_hashtag_feed" AS
 SELECT "p"."id" AS "post_id",
    "p"."user_id",
    "p"."body",
    "p"."created_at",
    "array_agg"("h"."tag") AS "hashtags"
   FROM (("public"."posts" "p"
     LEFT JOIN "public"."post_hashtags" "ph" ON (("ph"."post_id" = "p"."id")))
     LEFT JOIN "public"."hashtags" "h" ON (("h"."id" = "ph"."hashtag_id")))
  GROUP BY "p"."id"
  ORDER BY "p"."created_at" DESC;



CREATE OR REPLACE VIEW "public"."v_interest_feed" AS
 SELECT "p"."id" AS "post_id",
    "p"."user_id",
    "p"."body",
    "p"."created_at",
    "count"(DISTINCT "pi"."interest_id") FILTER (WHERE ("pi"."interest_id" IN ( SELECT "ui"."interest_id"
           FROM "public"."user_interests" "ui"
          WHERE ("ui"."user_id" = "auth"."uid"())))) AS "interest_score"
   FROM ("public"."posts" "p"
     LEFT JOIN "public"."post_interests" "pi" ON (("pi"."post_id" = "p"."id")))
  GROUP BY "p"."id"
  ORDER BY ("count"(DISTINCT "pi"."interest_id") FILTER (WHERE ("pi"."interest_id" IN ( SELECT "ui"."interest_id"
           FROM "public"."user_interests" "ui"
          WHERE ("ui"."user_id" = "auth"."uid"()))))) DESC, "p"."created_at" DESC;



CREATE OR REPLACE VIEW "public"."vw_patient_summary" AS
 SELECT "p"."id",
    "p"."created_at",
    "p"."updated_at",
    "p"."user_id",
    "p"."patient_code",
    "p"."first_name",
    "p"."last_name",
    "p"."date_of_birth",
    "p"."gender",
    "p"."blood_type",
    "p"."allergies",
    "p"."chronic_conditions",
    "p"."current_medications",
    "p"."emergency_contact_name",
    "p"."emergency_contact_phone",
    "p"."emergency_contact_relationship",
    "p"."insurance_provider",
    "p"."insurance_policy_number",
    "p"."status",
    "p"."primary_physician_id",
    "p"."last_visit_date",
    "p"."metadata",
    "count"(DISTINCT "a"."id") AS "total_appointments",
    "count"(DISTINCT
        CASE
            WHEN ("a"."status" = 'completed'::"public"."appointment_status") THEN "a"."id"
            ELSE NULL::"uuid"
        END) AS "completed_appointments",
    "count"(DISTINCT "r"."id") AS "total_records",
    "count"(DISTINCT "rx"."id") AS "active_prescriptions",
    "max"("a"."scheduled_date") AS "next_appointment_date"
   FROM ((("public"."health_patients" "p"
     LEFT JOIN "public"."health_appointments" "a" ON (("a"."patient_id" = "p"."id")))
     LEFT JOIN "public"."health_records" "r" ON (("r"."patient_id" = "p"."id")))
     LEFT JOIN "public"."prescriptions" "rx" ON ((("rx"."patient_id" = "p"."id") AND ("rx"."status" = 'active'::"public"."prescription_status"))))
  GROUP BY "p"."id";



CREATE OR REPLACE VIEW "public"."vw_published_courses" AS
 SELECT "c"."id",
    "c"."created_at",
    "c"."updated_at",
    "c"."course_code",
    "c"."title",
    "c"."description",
    "c"."short_description",
    "c"."category",
    "c"."sub_category",
    "c"."tags",
    "c"."level",
    "c"."status",
    "c"."instructor_id",
    "c"."institution_id",
    "c"."institution_name",
    "c"."duration_hours",
    "c"."duration_weeks",
    "c"."language",
    "c"."thumbnail_url",
    "c"."promo_video_url",
    "c"."syllabus",
    "c"."modules",
    "c"."prerequisites",
    "c"."learning_outcomes",
    "c"."price",
    "c"."currency",
    "c"."is_certified",
    "c"."certification_type",
    "c"."max_students",
    "c"."enrolled_count",
    "c"."completion_count",
    "c"."avg_rating",
    "c"."review_count",
    "c"."published_at",
    "c"."metadata",
    "u"."email" AS "instructor_email",
    "count"(DISTINCT "e"."id") AS "total_enrollments",
    "count"(DISTINCT
        CASE
            WHEN ("e"."status" = 'completed'::"public"."enrollment_status") THEN "e"."id"
            ELSE NULL::"uuid"
        END) AS "total_completions",
    COALESCE("avg"("e"."final_score"), (0)::numeric) AS "avg_final_score"
   FROM (("public"."courses" "c"
     LEFT JOIN "auth"."users" "u" ON (("u"."id" = "c"."instructor_id")))
     LEFT JOIN "public"."course_enrollments" "e" ON (("e"."course_id" = "c"."id")))
  WHERE ("c"."status" = 'published'::"public"."course_status")
  GROUP BY "c"."id", "u"."email";



