CREATE POLICY "announcements_localized_read" ON "public"."education_announcements" FOR SELECT USING (
CASE "visibility_scope"
    WHEN 'national'::"text" THEN true
    WHEN 'state'::"text" THEN ((EXISTS ( SELECT 1
       FROM "public"."education_staff"
      WHERE ("education_staff"."user_id" = "auth"."uid"()))) OR (EXISTS ( SELECT 1
       FROM "public"."education_students"
      WHERE ("education_students"."user_id" = "auth"."uid"()))))
    WHEN 'county'::"text" THEN ((EXISTS ( SELECT 1
       FROM (("public"."education_staff" "s"
         JOIN "public"."education_institutions" "i" ON (("s"."institution_id" = "i"."id")))
         JOIN "public"."education_institutions" "fi" ON (("education_announcements"."institution_id" = "fi"."id")))
      WHERE (("s"."user_id" = "auth"."uid"()) AND ("i"."county" = "fi"."county")))) OR (EXISTS ( SELECT 1
       FROM (("public"."education_students" "s"
         JOIN "public"."education_institutions" "i" ON (("s"."institution_id" = "i"."id")))
         JOIN "public"."education_institutions" "fi" ON (("education_announcements"."institution_id" = "fi"."id")))
      WHERE (("s"."user_id" = "auth"."uid"()) AND ("i"."county" = "fi"."county")))))
    WHEN 'district'::"text" THEN ((EXISTS ( SELECT 1
       FROM (("public"."education_staff" "s"
         JOIN "public"."education_institutions" "i" ON (("s"."institution_id" = "i"."id")))
         JOIN "public"."education_institutions" "fi" ON (("education_announcements"."institution_id" = "fi"."id")))
      WHERE (("s"."user_id" = "auth"."uid"()) AND ("i"."district" = "fi"."district")))) OR (EXISTS ( SELECT 1
       FROM (("public"."education_students" "s"
         JOIN "public"."education_institutions" "i" ON (("s"."institution_id" = "i"."id")))
         JOIN "public"."education_institutions" "fi" ON (("education_announcements"."institution_id" = "fi"."id")))
      WHERE (("s"."user_id" = "auth"."uid"()) AND ("i"."district" = "fi"."district")))))
    WHEN 'school'::"text" THEN ((EXISTS ( SELECT 1
       FROM "public"."education_staff"
      WHERE (("education_staff"."user_id" = "auth"."uid"()) AND ("education_staff"."institution_id" = "education_announcements"."institution_id")))) OR (EXISTS ( SELECT 1
       FROM "public"."education_students"
      WHERE (("education_students"."user_id" = "auth"."uid"()) AND ("education_students"."institution_id" = "education_announcements"."institution_id")))))
    ELSE false
END);



